window.CONTENT.ict[9]=[{"t":"1-dars. Kompyuter qurilmalari va dasturiy ta‘minot. Kompyuter tizimining asosiy komponentlari","lesson":"<p><b>Kompyuter tizimi</b> — apparat va dasturiy ta’minotning birgalikdagi ishlashidan iborat tizim. <b>Apparat ta’minoti (hardware)</b> — qo‘l bilan ushlab ko‘rsa bo‘ladigan qurilmalar, <b>dasturiy ta’minot (software)</b> — kompyuterga ishlashni buyuradigan dasturlar.</p>\n<h4>Asosiy komponentlar</h4>\n<ul><li><b>Protsessor (CPU)</b> — buyruqlarni bajaradi va hisob-kitob qiladi.</li><li><b>Operativ xotira (RAM)</b> — ishlayotgan dastur va ma’lumotlar vaqtincha saqlanadi, o‘chirilganda tozalanadi.</li><li><b>Doimiy xotira</b> — fayllar uzoq saqlanadi (HDD, SSD).</li><li><b>Kiritish va chiqarish qurilmalari</b>.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Matn muharririda hujjat yozayotganda matn avval RAMda turadi. «Saqlash» bosilganda u doimiy xotiraga yoziladi.</div>\n<h4>Dasturiy ta’minot turlari</h4>\n<ul><li><b>Tizim dasturlari</b> — operatsion tizim, drayverlar.</li><li><b>Amaliy dasturlar</b> — matn muharriri, brauzer, o‘yinlar.</li></ul>\n<h4>Eslab qoling</h4><ul><li>Apparat ta’minoti — qurilmalar, dasturiy ta’minot — dasturlar.</li><li>RAM vaqtinchalik, SSD va HDD doimiy xotiradir.</li></ul>","quiz":[{"q":"Kompyuterning «apparat ta’minoti» nimani anglatadi?","o":["Foydalanuvchi yaratgan fayllarni","Internetdagi ma’lumotlarni","Kompyuterda o‘rnatilgan dasturlarni","Kompyuterning jismoniy qurilmalarini"],"a":3,"e":"Hardware — qo‘l bilan ushlab ko‘riladigan jismoniy qurilmalar."},{"q":"Quyidagilardan qaysi biri dasturiy ta’minotga kiradi?","o":["Sichqoncha","Klaviatura","Monitor","Brauzer"],"a":3,"e":"Brauzer — dastur, qolganlari qurilma."},{"q":"Buyruqlarni bajaradigan va hisob-kitob qiladigan asosiy qurilma qaysi?","o":["Skaner","Monitor","Printer","Protsessor"],"a":3,"e":"Protsessor (CPU) kompyuterning «miyasi»dir."},{"q":"Kompyuter o‘chirilganda operativ xotira (RAM)dagi ma’lumotlar nima bo‘ladi?","o":["Internetga yuklanadi","Yo‘qoladi","Saqlanib qoladi","Qattiq diskka ko‘chadi"],"a":1,"e":"RAM — o‘zgaruvchan (vaqtinchalik) xotira."},{"q":"Fayllarni uzoq muddat saqlash uchun qaysi xotira ishlatiladi?","o":["RAM","SSD yoki HDD","Protsessor registri","Videokarta xotirasi"],"a":1,"e":"SSD va HDD doimiy saqlash qurilmalaridir."},{"q":"Operatsion tizim qaysi dasturlar guruhiga kiradi?","o":["Tizim dasturlari","Amaliy dasturlar","O‘yin dasturlari","Antivirus bo‘lmagan dasturlar"],"a":0,"e":"Operatsion tizim kompyuter resurslarini boshqaradi, shuning uchun tizim dasturi."},{"q":"Matn muharririda yozilayotgan hujjat saqlanmaguncha qayerda turadi?","o":["Klaviaturada","Monitorda","Operativ xotirada","Printerda"],"a":2,"e":"Ishlayotgan ma’lumotlar RAMda turadi."},{"q":"Kompyuter tizimi nimadan iborat?","o":["Faqat dasturlardan","Apparat va dasturiy ta’minotdan","Faqat monitor va klaviaturadan","Faqat protsessordan"],"a":1,"e":"Tizim ikkala qismning birgalikdagi ishidir."},{"q":"«Drayver» nima?","o":["Qurilmani operatsion tizim bilan bog‘laydigan dastur","Xotira qurilmasi","Internet tarmog‘i","Yangi turdagi monitor"],"a":0,"e":"Drayver qurilmaning tizim bilan ishlashini ta’minlaydi."},{"q":"Dasturlarsiz faqat apparatdan iborat kompyuter nima qila oladi?","o":["Dastur yozadi","Barcha ishlarni o‘zi bajaradi","Foydali ishni deyarli bajara olmaydi","Faqat internetga ulanadi"],"a":2,"e":"Dastur apparatga nima qilishni buyuradi."}]},{"t":"2-dars. Operatsion tizimlar","lesson":"<p><b>Operatsion tizim (OT)</b> — kompyuter resurslarini boshqaradigan va foydalanuvchi hamda apparat o‘rtasida vositachilik qiladigan asosiy tizim dasturi.</p>\n<h4>OTning vazifalari</h4>\n<ul><li>Protsessor va xotirani dasturlar o‘rtasida taqsimlash.</li><li>Fayl va papkalarni boshqarish.</li><li>Qurilmalarni (printer, klaviatura) boshqarish.</li><li>Foydalanuvchi interfeysini taqdim etish.</li><li>Xavfsizlik va foydalanuvchi huquqlarini nazorat qilish.</li></ul>\n<h4>Foydalanuvchi interfeysi turlari</h4>\n<ul><li><b>Grafik (GUI)</b> — oynalar, belgilar, sichqoncha bilan ishlash.</li><li><b>Buyruqlar qatori (CLI)</b> — buyruqlar matn ko‘rinishida kiritiladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Windows, macOS, Linux, Android, iOS — operatsion tizimlarga misol.</div>\n<h4>Eslab qoling</h4><ul><li>OT bo‘lmasa, amaliy dastur apparatni boshqara olmaydi.</li><li>Turli qurilmalar uchun turli OT mavjud.</li></ul>","quiz":[{"q":"Operatsion tizimning asosiy vazifasi nima?","o":["Kompyuter resurslarini boshqarish","Faqat matn yozish","Fayllarni chop etish","Faqat internetga ulanish"],"a":0,"e":"OT protsessor, xotira va qurilmalarni boshqaradi."},{"q":"Quyidagilardan qaysi biri operatsion tizim hisoblanadi?","o":["Linux","Chrome","Photoshop","Excel"],"a":0,"e":"Linux — operatsion tizim; qolganlari amaliy dastur."},{"q":"Oyna, belgi va sichqoncha yordamida ishlash qaysi interfeysga xos?","o":["Ovozli interfeys bo‘lmagan har qanday","Faqat dasturlash tili","Grafik interfeys","Buyruqlar qatori"],"a":2,"e":"Grafik interfeys (GUI) shunday ishlaydi."},{"q":"Buyruqlar qatori interfeysida foydalanuvchi nima qiladi?","o":["Faqat sichqoncha bilan bosadi","Faqat ovoz bilan boshqaradi","Faqat barmoq bilan suradi","Buyruqlarni matn ko‘rinishida kiritadi"],"a":3,"e":"CLI matnli buyruqlar bilan ishlaydi."},{"q":"Quyidagilardan qaysi biri mobil qurilmalar uchun operatsion tizim?","o":["Paint","Windows Server bo‘lmagan antivirus","Word","Android"],"a":3,"e":"Android — mobil OT."},{"q":"Operatsion tizim fayllar bilan nima ish qiladi?","o":["Hech qanday ish qilmaydi","Ularni faqat internetda saqlaydi","Ularni tashkil qiladi va boshqaradi","Ularni faqat o‘chiradi"],"a":2,"e":"Fayl tizimini boshqarish OT vazifasi."},{"q":"OT bo‘lmasa amaliy dasturlarning ishlashi qanday bo‘ladi?","o":["Ular o‘zlari OT vazifasini bajaradi","Yanada tez ishlaydi","Hech narsa o‘zgarmaydi","Ular apparatni boshqara olmaydi"],"a":3,"e":"Amaliy dasturlar OT vositasida resurslardan foydalanadi."},{"q":"Printerni boshqarishda OT nimadan foydalanadi?","o":["Faqat antivirusdan","Faqat brauzerdan","Drayverdan","Elektron jadvaldan"],"a":2,"e":"Drayver qurilma bilan aloqani ta’minlaydi."},{"q":"Bir vaqtda bir nechta dasturni ishlatishda OT nima qiladi?","o":["Barchasini o‘chiradi","Ularni tarmoqqa yuboradi","Faqat bittasini qoldiradi","Resurslarni dasturlar orasida taqsimlaydi"],"a":3,"e":"Resurslarni taqsimlash OTning vazifasi."},{"q":"Foydalanuvchi huquqlarini cheklash OTning qaysi vazifasiga kiradi?","o":["Chop etishga","Xavfsizlikni nazorat qilishga","Videoni tahrirlashga","Dizaynga"],"a":1,"e":"OT kirish huquqlarini nazorat qiladi."}]},{"t":"3-dars. Kompyuter turlari","lesson":"<p>Kompyuterlar o‘lchami, vazifasi va quvvatiga ko‘ra turlarga bo‘linadi.</p>\n<h4>Asosiy turlar</h4>\n<ul><li><b>Superkompyuter</b> — juda katta hisoblash quvvatiga ega; ob-havo bashorati, ilmiy modellashtirishda.</li><li><b>Mainframe (yirik kompyuter)</b> — banklar, yirik tashkilotlarda ko‘p foydalanuvchiga xizmat qiladi, ishonchli.</li><li><b>Shaxsiy kompyuter (PC)</b> — stol usti kompyuteri, noutbuk.</li><li><b>Planshet va smartfon</b> — ixcham, sensorli ekranli mobil qurilmalar.</li><li><b>O‘rnatilgan (embedded) kompyuterlar</b> — maishiy texnika, avtomobil, kir yuvish mashinasi ichida.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Noutbukni ko‘chirib yurish qulay, stol usti kompyuteri esa odatda kuchliroq va arzonroq bo‘ladi.</div>\n<h4>Eslab qoling</h4><ul><li>Tur tanlash vazifaga, narxga va ko‘chma bo‘lishga bog‘liq.</li><li>Embedded kompyuter alohida bitta vazifani bajaradi.</li></ul>","quiz":[{"q":"Ob-havoni bashorat qilish kabi juda murakkab hisoblar uchun qaysi kompyuter ishlatiladi?","o":["Planshet","Smartfon","Elektron soat","Superkompyuter"],"a":3,"e":"Superkompyuter eng katta hisoblash quvvatiga ega."},{"q":"Banklarda ko‘p foydalanuvchiga xizmat qiluvchi ishonchli yirik kompyuter nima deyiladi?","o":["Smartfon","Mainframe","Planshet","Noutbuk"],"a":1,"e":"Mainframe tashkilotlarda katta hajmdagi ishni bajaradi."},{"q":"Kir yuvish mashinasi ichidagi boshqaruv kompyuteri qaysi turga kiradi?","o":["O‘rnatilgan (embedded)","Noutbuk","Superkompyuter","Mainframe"],"a":0,"e":"Embedded kompyuter qurilma ichida bitta vazifani bajaradi."},{"q":"Qaysi kompyuter ko‘chirib yurish uchun eng qulay?","o":["Noutbuk","Stol usti kompyuteri","Mainframe","Superkompyuter"],"a":0,"e":"Noutbuk ixcham va batareyada ishlaydi."},{"q":"Smartfon va planshetning umumiy xususiyati nima?","o":["Sensorli ekranli ixcham mobil qurilma","Faqat buyruqlar qatori bilan ishlashi","Faqat elektr tarmog‘idan ishlashi","Katta xona egallashi"],"a":0,"e":"Ular mobil qurilmalar."},{"q":"Stol usti kompyuterining noutbukka nisbatan odatiy afzalligi nima?","o":["Cho‘ntakka sig‘ishi","Narxga nisbatan quvvatli va kengaytirish oson","Og‘irligi juda yengil bo‘lishi","Batareyada uzoq ishlashi"],"a":1,"e":"Stol usti kompyuteri odatda arzon va kengaytiriladi."},{"q":"Quyidagilardan qaysi biri embedded kompyuterga misol?","o":["Avtomobil dvigatelini boshqaruvchi blok","Stol usti kompyuteri","Server xonasi","Noutbuk"],"a":0,"e":"Avtomobil ichida joylashgan boshqaruv bloki."},{"q":"Kompyuter turini tanlashda nimaga qarash kerak?","o":["Vazifa, narx va ko‘chma bo‘lishga","Faqat rangiga","Faqat nomiga","Faqat o‘lchamiga bo‘lmagan boshqa narsaga"],"a":0,"e":"Tanlov ehtiyojga bog‘liq."},{"q":"Superkompyuterlarga qaysi ish xos?","o":["Faqat musiqa tinglash","Faqat xat yozish","Faqat o‘yin o‘ynash","Ilmiy modellashtirish"],"a":3,"e":"Katta hisoblashlar kerak bo‘lgan ishlar."},{"q":"«Shaxsiy kompyuter» (PC) nimani anglatadi?","o":["Faqat superkompyuter","Faqat maishiy texnika ichidagi kompyuter","Bitta foydalanuvchi uchun mo‘ljallangan kompyuter","Faqat tashkilot serveri"],"a":2,"e":"PC — individual foydalanish uchun."}]},{"t":"4-dars. Yangi texnologiyalarning ta‘siri","lesson":"<p>Yangi texnologiyalar jamiyat, ish va kundalik hayotga katta ta’sir ko‘rsatadi. Ta’sir ham <b>ijobiy</b>, ham <b>salbiy</b> bo‘lishi mumkin.</p>\n<h4>Ijobiy ta’sirlar</h4>\n<ul><li>Aloqa tezlashadi: elektron pochta, video qo‘ng‘iroq.</li><li>Ta’lim imkoniyatlari kengayadi: onlayn kurslar.</li><li>Ishlab chiqarishda avtomatlashtirish va aniqlik.</li><li>Tibbiyotda tashxis va davolash yaxshilanadi.</li></ul>\n<h4>Salbiy ta’sirlar</h4>\n<ul><li>Ba’zi kasblar qisqarishi mumkin.</li><li>Shaxsiy ma’lumotlar xavfsizligiga tahdid.</li><li>Ekran oldida ko‘p vaqt o‘tkazish sog‘liqqa zarar.</li><li>Raqamli tengsizlik: texnologiyadan hamma birdek foydalana olmaydi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Elektron to‘lov tizimi vaqtni tejaydi, lekin parollarni himoya qilmasa, mablag‘ yo‘qolishi mumkin.</div>\n<h4>Eslab qoling</h4><ul><li>Texnologiyaga tanqidiy va mas’uliyatli yondashing.</li></ul>","quiz":[{"q":"Quyidagilardan qaysi biri texnologiyaning ijobiy ta’siri?","o":["Aloqaning tezlashishi","Ekran oldida ortiqcha o‘tirish","Shaxsiy ma’lumotlar o‘g‘irlanishi","Raqamli tengsizlik"],"a":0,"e":"Tezkor aloqa — ijobiy ta’sir."},{"q":"Raqamli tengsizlik nimani bildiradi?","o":["Dasturlar narxining pastligini","Faqat internet tezligini","Barcha kompyuterlar bir xil bo‘lishini","Texnologiyadan hamma birdek foydalana olmasligini"],"a":3,"e":"Imkoniyatlar odamlar o‘rtasida teng emas."},{"q":"Avtomatlashtirish ish o‘rinlariga qanday ta’sir qilishi mumkin?","o":["Hech qanday ta’sir qilmaydi","Barcha kasblar o‘zgarmaydi","Faqat maosh oshadi","Ba’zi kasblar qisqarib, yangilari paydo bo‘ladi"],"a":3,"e":"Texnologiya mehnat bozorini o‘zgartiradi."},{"q":"Onlayn kurslar texnologiyaning qaysi sohadagi ijobiy ta’siriga misol?","o":["Transportda tiqilinch","Qishloq xo‘jaligida zarar","Ob-havoda","Ta’limda"],"a":3,"e":"Masofaviy o‘qish imkoniyati."},{"q":"Elektron to‘lovlarning xavfi nima bo‘lishi mumkin?","o":["Internet o‘chmasligi","Parol yetarli himoyalanmasa mablag‘ yo‘qolishi","Pul qog‘ozga aylanishi","Hisob doim ko‘payishi"],"a":1,"e":"Himoyasiz hisoblar xavf ostida."},{"q":"Uzoq vaqt ekranga qarash qanday ta’sir qilishi mumkin?","o":["Ko‘rishni yaxshilaydi","Bo‘yni o‘stiradi","Ko‘z va umurtqa sog‘lig‘iga zarar","Hech qanday ta’sir qilmaydi"],"a":2,"e":"Gigiyena qoidalariga rioya qilish zarur."},{"q":"Tibbiyotda texnologiyaning ijobiy ta’siriga qaysi misol to‘g‘ri?","o":["Shifokorlarning yo‘qolishi","Bemorlar sonining ortishi","Tashxisning aniqligi oshishi","Dori narxining nolga tushishi"],"a":2,"e":"Zamonaviy uskunalar tashxisni yaxshilaydi."},{"q":"Texnologiyaga qanday munosabatda bo‘lish to‘g‘ri?","o":["Faqat maqtash","Umuman e’tibor bermaslik","Faqat rad etish","Foyda va xavflarini birgalikda baholash"],"a":3,"e":"Tanqidiy yondashuv zarur."},{"q":"Texnologiyalarning jamiyatga ta’siri qanday?","o":["Ham ijobiy, ham salbiy bo‘lishi mumkin","Faqat ijobiy","Faqat salbiy","Hech qanday ta’sir yo‘q"],"a":0,"e":"Ta’sirlar ikki yoqlama."},{"q":"Shaxsiy ma’lumotlarning o‘g‘irlanishi qaysi turdagi ta’sir?","o":["Ijobiy","Betaraf va foydali","Salbiy","Iqtisodiy foyda"],"a":2,"e":"Xavfsizlik tahdidi."}]},{"t":"5-dars. Kiritish qurilmalari va ularning qo‘llanishi","lesson":"<p><b>Kiritish qurilmalari</b> ma’lumot va buyruqlarni kompyuterga kiritish uchun xizmat qiladi. Ular inson tushunadigan ma’lumotni kompyuter ishlay oladigan raqamli signalga aylantiradi.</p>\n<h4>Asosiy kiritish qurilmalari</h4>\n<ul><li><b>Klaviatura</b> — matn va buyruqlar kiritadi. Harf tugmalari, raqamlar, funksiya tugmalari (F1–F12) va boshqaruv tugmalari (Enter, Shift, Backspace, Delete) mavjud.</li>\n<li><b>Sichqoncha</b> — ekrandagi ko‘rsatkichni boshqaradi, obyektni tanlash va siljitish imkonini beradi.</li>\n<li><b>Sensorli ekran</b> — barmoq bilan bosib boshqariladi, telefon va planshetlarda keng qo‘llanadi.</li>\n<li><b>Trekbol, sensorli panel (tachpad)</b> — noutbuklarda sichqoncha o‘rnini bosadi.</li>\n<li><b>Joystik</b> — o‘yinlarda va simulyatorlarda ishlatiladi.</li>\n<li><b>Grafik planshet</b> — maxsus qalam bilan rasm chizish uchun mo‘ljallangan.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Dizayner rasm chizishda grafik planshetdan, o‘quvchi matn terishda klaviaturadan foydalanadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Kiritish qurilmalari ma’lumotni kompyuterga uzatadi.</li><li>Klaviatura — matn, sichqoncha — ko‘rsatkichni boshqarish uchun.</li></ul>","quiz":[{"q":"Kiritish qurilmalarining vazifasi nima?","o":["Ma’lumotni ekranga chiqarish","Ma’lumot va buyruqlarni kompyuterga kiritish","Ma’lumotni qog‘ozga chop etish","Ma’lumotni uzoq muddat saqlash"],"a":1,"e":"Kiritish qurilmalari ma’lumotni kompyuterga uzatadi."},{"q":"Quyidagilardan qaysi biri kiritish qurilmasi hisoblanadi?","o":["Printer","Karnay","Sichqoncha","Monitor"],"a":2,"e":"Printer, monitor va karnay chiqarish qurilmalaridir."},{"q":"Funksiya tugmalari klaviaturada qanday belgilanadi?","o":["F1–F12","Alt va Ctrl","1–9","A–Z"],"a":0,"e":"Funksiya tugmalari F harfi va raqam bilan yoziladi."},{"q":"Rasm chizish uchun maxsus qalam bilan ishlatiladigan qurilma qaysi?","o":["Skaner","Joystik","Klaviatura","Grafik planshet"],"a":3,"e":"Grafik planshet qalam yordamida chizish imkonini beradi."},{"q":"Noutbukda sichqoncha o‘rnini odatda qaysi qurilma bosadi?","o":["Proyektor","Sensorli panel (tachpad)","Joystik","Mikrofon"],"a":1,"e":"Tachpad ko‘rsatkichni barmoq harakati bilan boshqaradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Sichqoncha faqat matn kiritadi","Sensorli ekran faqat ma’lumot chiqaradi","Sensorli ekran ham kiritish, ham ko‘rsatish vazifasini bajaradi","Joystik hujjat chop etadi"],"a":2,"e":"Sensorli ekran tasvirni ko‘rsatadi va bosishni sezadi."},{"q":"Kiritilgan matndagi oxirgi belgini o‘chirish uchun qaysi tugma ishlatiladi?","o":["Backspace","Caps Lock","Tab","Enter"],"a":0,"e":"Backspace kursor oldidagi belgini o‘chiradi."},{"q":"Telefon ekranini barmoq bilan bosib boshqarish qaysi qurilmaga asoslangan?","o":["Trekbol","Skaner","Plotter","Sensorli ekran"],"a":3,"e":"Sensorli ekran bosilgan joyni aniqlaydi."},{"q":"Matn terishda bosh harf yozish uchun qaysi tugma bosib turiladi?","o":["Shift","Esc","Delete","Insert"],"a":0,"e":"Shift bosilganda bosh harf yoziladi."},{"q":"Qaysi qatorda faqat kiritish qurilmalari berilgan?","o":["Joystik, plotter, printer","Klaviatura, sichqoncha, joystik","Klaviatura, printer, monitor","Sichqoncha, proyektor, karnay"],"a":1,"e":"Qolgan qatorlarda chiqarish qurilmalari aralashgan."}]},{"t":"6-dars. Ma‘lumotni bevosita kiritishda foydalaniladigan qurilmalar.","lesson":"<p>Ba’zi qurilmalar ma’lumotni qo‘lda terishsiz, <b>bevosita</b> (to‘g‘ridan-to‘g‘ri) manbadan o‘qib kompyuterga kiritadi. Bu ishni tezlashtiradi va xatolarni kamaytiradi.</p>\n<h4>Asosiy qurilmalar</h4>\n<ul><li><b>Skaner</b> — qog‘oz hujjat yoki rasmni raqamli tasvirga aylantiradi.</li>\n<li><b>Shtrix-kod o‘quvchi</b> — mahsulotdagi chiziqli kodni o‘qiydi; do‘konlarda keng qo‘llanadi.</li>\n<li><b>QR-kodni o‘qish</b> — telefon kamerasi yordamida amalga oshiriladi.</li>\n<li><b>Raqamli kamera va veb-kamera</b> — tasvir va videoni kiritadi.</li>\n<li><b>Mikrofon</b> — ovozni kiritadi.</li>\n<li><b>OMR</b> — test varaqlaridagi belgilangan katakchalarni o‘qiydi.</li>\n<li><b>OCR</b> — skanerlangan tasvirdagi matnni tahrirlanadigan matnga aylantiradi.</li>\n<li><b>Biometrik o‘quvchilar</b> — barmoq izi yoki yuzni tanib, shaxsni aniqlaydi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Kassir mahsulotni shtrix-kod o‘quvchi oldidan o‘tkazadi — narx va nom avtomatik chiqadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Bevosita kiritish — tezroq va xatosiz.</li><li>OCR rasmdagi matnni matnga aylantiradi.</li></ul>","quiz":[{"q":"Qog‘oz hujjatni raqamli tasvirga aylantiruvchi qurilma qaysi?","o":["Proyektor","Monitor","Printer","Skaner"],"a":3,"e":"Skaner hujjatni skanerlab, fayl hosil qiladi."},{"q":"Do‘konda mahsulot kodini o‘qiydigan qurilma qanday ataladi?","o":["Plotter","Karnay","Shtrix-kod o‘quvchi","Grafik planshet"],"a":2,"e":"U chiziqli kodni o‘qib mahsulot ma’lumotini topadi."},{"q":"OCR texnologiyasi nima uchun ishlatiladi?","o":["Faylni arxivlash","Ovozni yozib olish","Tasvirni chop etish","Tasvirdagi matnni tahrirlanadigan matnga aylantirish"],"a":3,"e":"OCR — optik belgilarni tanish texnologiyasi."},{"q":"Test varaqlaridagi belgilangan javob katakchalarini o‘qish uchun qaysi texnologiya mos?","o":["BIOS","OCR","QR","OMR"],"a":3,"e":"OMR belgilangan joylarni aniqlaydi."},{"q":"Barmoq izi bilan shaxsni aniqlaydigan qurilma qaysi guruhga kiradi?","o":["Chiqarish qurilmasi","Biometrik o‘quvchi","Tarmoq qurilmasi","Xotira qurilmasi"],"a":1,"e":"Biometrik qurilmalar shaxsning o‘ziga xos belgilarini o‘qiydi."},{"q":"Bevosita kiritishning afzalligi qaysi?","o":["Ma’lumot hajmi doim kamayadi","Dastur kerak bo‘lmaydi","Elektr talab qilinmaydi","Ish tezlashadi va xatolar kamayadi"],"a":3,"e":"Qo‘lda terish kamayganligi sababli xato ham kamayadi."},{"q":"Ovozni kompyuterga kiritish uchun qaysi qurilma ishlatiladi?","o":["Printer","Kolonka","Skaner","Mikrofon"],"a":3,"e":"Mikrofon tovushni signalga aylantiradi."},{"q":"Telefon kamerasi orqali o‘qiladigan kvadrat shakldagi kod qaysi?","o":["ASCII jadvali","Morze kodi","QR-kod","IP-manzil"],"a":2,"e":"QR-kod kamera yordamida o‘qiladi."},{"q":"Video qo‘ng‘iroq uchun qaysi qurilma kerak?","o":["Veb-kamera","Plotter","Skaner","Printer"],"a":0,"e":"Veb-kamera tasvirni real vaqtda uzatadi."},{"q":"Skanerlangan sahifani tahrir qilish uchun skanerdan tashqari nima kerak?","o":["OCR dasturi","Kolonka","Proyektor","Joystik"],"a":0,"e":"OCR tasvirni matnga aylantiradi."}]},{"t":"7-dars. Chiqarish qurilmalari va ulardan foydalanish","lesson":"<p><b>Chiqarish qurilmalari</b> kompyuterda qayta ishlangan natijani inson qabul qila oladigan ko‘rinishda — tasvir, matn, tovush yoki qog‘ozdagi nusxa sifatida — taqdim etadi.</p>\n<h4>Asosiy qurilmalar</h4>\n<ul><li><b>Monitor</b> — tasvirni ko‘rsatadi. Tasvir mayda nuqtalar — <b>piksellardan</b> tuzilgan. Ekran ruxsati (masalan, 1920 x 1080) pikselar sonini bildiradi.</li>\n<li><b>Printer</b> — natijani qog‘ozga chop etadi. Turlari: <b>lazerli</b> (tez, matn uchun qulay), <b>purkagichli</b> (rangli rasm uchun), <b>matritsali</b> (ignalar yordamida, nusxali hujjatlarda).</li>\n<li><b>Proyektor</b> — tasvirni katta ekranga proyeksiyalaydi.</li>\n<li><b>Karnay va quloqchin</b> — tovush chiqaradi.</li>\n<li><b>Plotter</b> — katta o‘lchamli chizma va xaritalarni chizadi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktabda taqdimotni proyektor orqali darsda ko‘rsatasiz, tayyor hisobotni esa printerda chop etasiz.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Chiqarish qurilmasi natijani ko‘rsatadi yoki chop etadi.</li><li>Printer sifati dpi bilan, tezligi sahifa/daqiqa bilan baholanadi.</li></ul>","quiz":[{"q":"Chiqarish qurilmalarining vazifasi nima?","o":["Ma’lumotni kompyuterga kiritish","Tarmoqqa ulanish","Qayta ishlangan natijani inson uchun tushunarli shaklda taqdim etish","Ma’lumotni abadiy saqlash"],"a":2,"e":"Chiqarish qurilmalari natijani ko‘rsatadi, chop etadi yoki eshittiradi."},{"q":"Quyidagilardan qaysi biri chiqarish qurilmasi?","o":["Proyektor","Mikrofon","Klaviatura","Skaner"],"a":0,"e":"Proyektor tasvirni ekranga chiqaradi."},{"q":"Monitor tasviri nimalardan tashkil topgan?","o":["Fayllar","Sektorlar","Baytlar","Piksellar"],"a":3,"e":"Tasvir mayda rangli nuqtalardan — piksellardan iborat."},{"q":"Katta o‘lchamli chizma va xaritalarni chizish uchun qaysi qurilma ishlatiladi?","o":["Tachpad","Plotter","Veb-kamera","Skaner"],"a":1,"e":"Plotter muhandislik chizmalari uchun mo‘ljallangan."},{"q":"Rangli rasmlarni chop etishda odatda qaysi printer ishlatiladi?","o":["Purkagichli printer","Mikrofon","Skaner","Matritsali printer"],"a":0,"e":"Purkagichli printer siyohni purkab rangli tasvir hosil qiladi."},{"q":"Nusxali (qatlamli) hujjatlarni bir yo‘la chop etishga qaysi printer mos?","o":["Lazerli printer","Proyektor","Matritsali printer","Purkagichli printer"],"a":2,"e":"Matritsali printer ignalar bilan bosib, nusxa hosil qiladi."},{"q":"Ekran ruxsati nimani bildiradi?","o":["Kompyuter xotirasini","Ekrandagi pikselar sonini","Internet tezligini","Monitorning og‘irligini"],"a":1,"e":"Ruxsat tasvirdagi pikselar soni bilan ifodalanadi."},{"q":"Quyidagi juftliklardan qaysi biri to‘g‘ri moslangan?","o":["Karnay — tovush chiqarish","Skaner — tovush chiqarish","Mikrofon — chop etish","Printer — ovoz yozish"],"a":0,"e":"Karnay tovushni eshittiradi."},{"q":"Sinfda taqdimotni butun sinfga ko‘rsatish uchun qaysi qurilma kerak?","o":["Klaviatura","Skaner","Proyektor","Mikrofon"],"a":2,"e":"Proyektor tasvirni katta ekranga uzatadi."},{"q":"Printerning tezligi odatda qanday o‘lchanadi?","o":["Voltlarda","Daqiqada chop etilgan sahifalar soni","Gigabaytlarda","Megapikselda"],"a":1,"e":"Tezlik sahifa/daqiqa ko‘rsatkichi bilan beriladi."}]},{"t":"8-dars. Xotira qurilmalari va ma‘lumot almashish vositalari","lesson":"<p>Kompyuterda ma’lumot saqlash uchun <b>xotira qurilmalari</b> xizmat qiladi. Ular <b>ichki</b> va <b>tashqi</b> turlarga bo‘linadi.</p>\n<h4>Ichki xotira</h4>\n<ul><li><b>Operativ xotira (RAM)</b> — ishlayotgan dastur va ma’lumotlarni vaqtincha saqlaydi; kompyuter o‘chsa, ma’lumot yo‘qoladi.</li>\n<li><b>ROM</b> — doimiy xotira, tarkibi o‘chirilganda ham saqlanadi.</li>\n<li><b>Kesh xotira</b> — protsessor uchun juda tez ishlaydigan oraliq xotira.</li></ul>\n<h4>Tashqi (doimiy) xotira</h4>\n<ul><li><b>Qattiq disk (HDD)</b> — magnit disklarda saqlaydi.</li>\n<li><b>SSD</b> — harakatlanuvchi qismlarsiz, tez ishlaydi.</li>\n<li><b>Fleshka</b> — ixcham, USB orqali ulanadi.</li>\n<li><b>Optik disklar</b> — CD, DVD, Blu-ray.</li></ul>\n<h4>O‘lchov birliklari</h4>\n<p>1 bayt = 8 bit; 1 KB = 1024 bayt; 1 MB = 1024 KB; 1 GB = 1024 MB.</p>\n<div class=\"ex\"><b>Misol.</b> Hujjat tahrirlanayotganda RAMda turadi, “Saqlash” bosilganda diskka yoziladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>RAM — vaqtinchalik, disk va fleshka — doimiy saqlash.</li></ul>","quiz":[{"q":"Kompyuter o‘chirilganda RAMdagi ma’lumotlar nima bo‘ladi?","o":["Yo‘qoladi","Fleshkaga yoziladi","Diskka avtomatik ko‘chadi","O‘zgarishsiz qoladi"],"a":0,"e":"RAM — vaqtinchalik xotira."},{"q":"Qaysi qurilma doimiy xotira (tashqi) hisoblanadi?","o":["Qattiq disk","RAM","Protsessor registri","Kesh xotira"],"a":0,"e":"Qattiq disk ma’lumotni uzoq muddat saqlaydi."},{"q":"1 bayt necha bitga teng?","o":["8","16","10","4"],"a":0,"e":"Bir bayt sakkiz bitdan iborat."},{"q":"1 KB necha baytga teng?","o":["1000","1024","512","100"],"a":1,"e":"Kompyuterda 1 KB = 1024 bayt."},{"q":"Harakatlanuvchi mexanik qismlarsiz ishlaydigan va tez xotira qurilmasi qaysi?","o":["CD-ROM","HDD","Disketa","SSD"],"a":3,"e":"SSD flesh-xotirada ishlaydi."},{"q":"Protsessor uchun juda tez, kichik hajmli oraliq xotira qanday ataladi?","o":["Kesh xotira","Optik disk","Virtual disk","Fleshka"],"a":0,"e":"Kesh protsessor ishini tezlatadi."},{"q":"Tahrirlanayotgan hujjat saqlanmaguncha qayerda turadi?","o":["Printerda","ROMda","Operativ xotirada","CD diskda"],"a":2,"e":"Ishlayotgan ma’lumot RAMda bo‘ladi."},{"q":"Quyidagilardan qaysi biri optik xotira?","o":["Fleshka","RAM","DVD","SSD"],"a":2,"e":"DVD lazer yordamida o‘qiladigan diskdir."},{"q":"Ma’lumotni USB portga ulab tashish uchun qulay qurilma qaysi?","o":["Operativ xotira moduli","Kesh","Fleshka","Protsessor"],"a":2,"e":"Fleshka ixcham va ko‘chma."},{"q":"To‘g‘ri tartibda joylashtiring (kichikdan kattaga):","o":["KB, GB, MB","MB, KB, GB","GB, MB, KB","KB, MB, GB"],"a":3,"e":"Har bir keyingi birlik 1024 marta katta."}]},{"t":"9-dars. Turli xotira qurilmalarining afzallik va kamchiliklari","lesson":"<p>Har bir xotira qurilmasining o‘z <b>afzalligi</b> va <b>kamchiligi</b> bor. Qurilmani tanlashda hajm, tezlik, narx, ishonchlilik va ko‘chma bo‘lishi hisobga olinadi.</p>\n<h4>Taqqoslash</h4>\n<ul><li><b>Qattiq disk (HDD):</b> hajmi katta, 1 GB narxi arzon; lekin mexanik qismlari bor, zarbadan zarar ko‘rishi mumkin, SSDga qaraganda sekin.</li>\n<li><b>SSD:</b> juda tez, shovqinsiz, zarbaga chidamli; lekin HDDga nisbatan qimmat.</li>\n<li><b>Fleshka:</b> ixcham, ko‘chma, ishlatish oson; lekin yo‘qotish oson, hajmi cheklangan.</li>\n<li><b>Optik disk (CD, DVD):</b> arzon, ma’lumotni tarqatishga qulay; hajmi kichik, yuzasi chizilsa o‘qilmaydi.</li>\n<li><b>Bulutli saqlash:</b> istalgan joydan kirish mumkin; internet kerak, xavfsizlik masalasi bor.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Ko‘p filmlarni arzon saqlash uchun HDD, tez yuklanadigan tizim uchun SSD tanlanadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Tezlik — SSD, arzon katta hajm — HDD, ko‘chma — fleshka.</li></ul>","quiz":[{"q":"Qaysi xotira qurilmasi tezligi bilan ajralib turadi?","o":["Magnit lenta","CD-R","SSD","Disketa"],"a":2,"e":"SSD harakatlanuvchi qismlarsiz ishlagani uchun tez."},{"q":"HDDning asosiy afzalligi nima?","o":["Katta hajmni arzon narxda taklif etishi","Zarbaga umuman chidamliligi","Shovqinsiz ishlashi","Eng tez ishlashi"],"a":0,"e":"HDD 1 GB uchun arzonroq."},{"q":"HDDning kamchiligi qaysi?","o":["Mexanik qismlari zarbadan zarar ko‘rishi mumkin","Hajmi juda kichik","Faqat musiqa yozishi","Elektr talab qilmasligi"],"a":0,"e":"Aylanuvchi disk va bosh zarbaga sezgir."},{"q":"Fleshkaning asosiy afzalligi nima?","o":["Eng katta hajm","Eng arzon bo‘lishi","Internet talab qilishi","Ixcham va ko‘chma"],"a":3,"e":"Fleshkani cho‘ntakda olib yurish mumkin."},{"q":"Quyidagilardan qaysi biri SSDning kamchiligi hisoblanadi?","o":["Bir xil hajmda HDDdan qimmatroq","Sekin ishlashi","Zarbadan tez buzilishi","Shovqin chiqarishi"],"a":0,"e":"SSD tezroq, lekin odatda qimmatroq."},{"q":"Bulutli saqlashdan foydalanish uchun nima zarur?","o":["Printer","Internet aloqasi","Optik disk yurituvchi","Skaner"],"a":1,"e":"Bulutga internet orqali kiriladi."},{"q":"Optik diskning kamchiligi qaysi?","o":["Ma’lumotni umuman saqlamasligi","Faqat elektr bilan ishlashi","Hajmi terabaytlarda bo‘lishi","Yuzasi chizilsa ma’lumot o‘qilmay qolishi mumkin"],"a":3,"e":"Chiziqlar lazer o‘qishiga xalaqit beradi."},{"q":"Vaziyat: tez yoqiladigan va shovqinsiz noutbuk kerak. Qaysi xotira mos?","o":["SSD","CD-ROM","Disketa","Magnit lenta"],"a":0,"e":"SSD tez va shovqinsiz."},{"q":"Vaziyat: katta video arxivni arzon saqlash kerak. Qaysi variant mos?","o":["ROM","Kesh xotira","Kichik CD","Katta hajmli HDD"],"a":3,"e":"HDDda hajm narxi past."},{"q":"To‘g‘ri mulohazani toping.","o":["SSD ichida aylanuvchi disk bor","Fleshka internetsiz ishlamaydi","HDD zarbaga eng chidamli qurilma","Fleshkani yo‘qotib qo‘yish ma’lumot yo‘qolishiga olib kelishi mumkin"],"a":3,"e":"Ko‘chma qurilmani yo‘qotish xavfi bor."}]},{"t":"10-dars. Xotira hajmiga bog‘liq masalalarni yechish","lesson":"<p>Xotira hajmini hisoblashda birliklarni bir-biriga aylantirish kerak. Esda tuting: <b>1 bayt = 8 bit</b>, <b>1 KB = 1024 bayt</b>, <b>1 MB = 1024 KB</b>, <b>1 GB = 1024 MB</b>, <b>1 TB = 1024 GB</b>.</p>\n<h4>Qoidalar</h4>\n<ul><li>Katta birlikdan kichigiga o‘tishda <b>ko‘paytiriladi</b> (1024 ga).</li>\n<li>Kichikdan kattaga o‘tishda <b>bo‘linadi</b>.</li>\n<li>Bir baytli kodlashda matnning har bir belgisi 1 bayt egallaydi.</li></ul>\n<div class=\"ex\"><b>Misol 1.</b> 2 GB = 2 · 1024 = 2048 MB.<br><b>Misol 2.</b> 3 MB = 3 · 1024 = 3072 KB.<br><b>Misol 3.</b> Sahifada 2000 belgi bo‘lsa, 10 sahifa = 20000 belgi = 20000 bayt.<br><b>Misol 4.</b> 16 GB fleshkaga har biri 4 MB bo‘lgan rasmlardan: 16 · 1024 : 4 = 4096 ta sig‘adi.</div>\n<h4>Amaliy vazifa</h4>\n<ol><li>5 KB necha baytga teng?</li><li>4096 KB necha MB?</li><li>Hajmini aniqlash uchun fayl xususiyatlarini (Properties) oching.</li></ol>\n<h4>Eslab qoling</h4>\n<ul><li>Katta → kichik: ko‘paytirish; kichik → katta: bo‘lish.</li></ul>","quiz":[{"q":"2 GB necha MBga teng?","o":["2000","1024","4096","2048"],"a":3,"e":"2 · 1024 = 2048."},{"q":"3 MB necha KBga teng?","o":["3000","3072","1024","300"],"a":1,"e":"3 · 1024 = 3072."},{"q":"4096 KB necha MB bo‘ladi?","o":["4","16","1024","40"],"a":0,"e":"4096 : 1024 = 4."},{"q":"5 KB necha baytga teng?","o":["5000","5120","8192","512"],"a":1,"e":"5 · 1024 = 5120."},{"q":"3 bayt necha bitga teng?","o":["3","24","12","8"],"a":1,"e":"3 · 8 = 24."},{"q":"Katta birlikdan kichik birlikka o‘tishda qanday amal bajariladi?","o":["Hech narsa qilinmaydi","1024 ga ko‘paytiriladi","8 ga qo‘shiladi","1024 ga bo‘linadi"],"a":1,"e":"Masalan, MB dan KB ga ko‘paytirib o‘tamiz."},{"q":"Bir baytli kodlashda 500 belgidan iborat matn necha bayt egallaydi?","o":["4000","500","5000","50"],"a":1,"e":"Har bir belgi 1 bayt."},{"q":"16 GB fleshkaga hajmi 8 MB bo‘lgan nechta fayl sig‘adi? (16 GB = 16384 MB)","o":["1024","8192","128","2048"],"a":3,"e":"16384 : 8 = 2048."},{"q":"1 TB necha GBga teng?","o":["100","8","1024","1000 MB"],"a":2,"e":"1 TB = 1024 GB."},{"q":"8192 bit necha baytga teng?","o":["1024","8","64","8192"],"a":0,"e":"8192 : 8 = 1024."}]},{"t":"11-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 1</b> quyidagi darslarni qamrab oladi:</p><ul><li>Kompyuter qurilmalari va dasturiy ta‘minot. Kompyuter tizimining asosiy komponentlari</li><li>Operatsion tizimlar</li><li>Kompyuter turlari</li><li>Yangi texnologiyalarning ta‘siri</li><li>Kiritish qurilmalari va ularning qo‘llanishi</li><li>Ma‘lumotni bevosita kiritishda foydalaniladigan qurilmalar.</li><li>Chiqarish qurilmalari va ulardan foydalanish</li><li>Xotira qurilmalari va ma‘lumot almashish vositalari</li><li>Turli xotira qurilmalarining afzallik va kamchiliklari</li><li>Xotira hajmiga bog‘liq masalalarni yechish</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Onlayn kurslar texnologiyaning qaysi sohadagi ijobiy ta’siriga misol?","o":["Transportda tiqilinch","Qishloq xo‘jaligida zarar","Ob-havoda","Ta’limda"],"a":3,"e":"Masofaviy o‘qish imkoniyati."},{"q":"Ma’lumotni USB portga ulab tashish uchun qulay qurilma qaysi?","o":["Operativ xotira moduli","Kesh","Fleshka","Protsessor"],"a":2,"e":"Fleshka ixcham va ko‘chma."},{"q":"Smartfon va planshetning umumiy xususiyati nima?","o":["Sensorli ekranli ixcham mobil qurilma","Faqat buyruqlar qatori bilan ishlashi","Faqat elektr tarmog‘idan ishlashi","Katta xona egallashi"],"a":0,"e":"Ular mobil qurilmalar."},{"q":"Skanerlangan sahifani tahrir qilish uchun skanerdan tashqari nima kerak?","o":["OCR dasturi","Kolonka","Proyektor","Joystik"],"a":0,"e":"OCR tasvirni matnga aylantiradi."},{"q":"Quyidagilardan qaysi biri mobil qurilmalar uchun operatsion tizim?","o":["Paint","Windows Server bo‘lmagan antivirus","Word","Android"],"a":3,"e":"Android — mobil OT."},{"q":"Bir vaqtda bir nechta dasturni ishlatishda OT nima qiladi?","o":["Barchasini o‘chiradi","Ularni tarmoqqa yuboradi","Faqat bittasini qoldiradi","Resurslarni dasturlar orasida taqsimlaydi"],"a":3,"e":"Resurslarni taqsimlash OTning vazifasi."},{"q":"Barmoq izi bilan shaxsni aniqlaydigan qurilma qaysi guruhga kiradi?","o":["Chiqarish qurilmasi","Biometrik o‘quvchi","Tarmoq qurilmasi","Xotira qurilmasi"],"a":1,"e":"Biometrik qurilmalar shaxsning o‘ziga xos belgilarini o‘qiydi."},{"q":"HDDning asosiy afzalligi nima?","o":["Katta hajmni arzon narxda taklif etishi","Zarbaga umuman chidamliligi","Shovqinsiz ishlashi","Eng tez ishlashi"],"a":0,"e":"HDD 1 GB uchun arzonroq."},{"q":"Operatsion tizim qaysi dasturlar guruhiga kiradi?","o":["Tizim dasturlari","Amaliy dasturlar","O‘yin dasturlari","Antivirus bo‘lmagan dasturlar"],"a":0,"e":"Operatsion tizim kompyuter resurslarini boshqaradi, shuning uchun tizim dasturi."},{"q":"Bulutli saqlashdan foydalanish uchun nima zarur?","o":["Printer","Internet aloqasi","Optik disk yurituvchi","Skaner"],"a":1,"e":"Bulutga internet orqali kiriladi."},{"q":"Katta birlikdan kichik birlikka o‘tishda qanday amal bajariladi?","o":["Hech narsa qilinmaydi","1024 ga ko‘paytiriladi","8 ga qo‘shiladi","1024 ga bo‘linadi"],"a":1,"e":"Masalan, MB dan KB ga ko‘paytirib o‘tamiz."},{"q":"Fayllarni uzoq muddat saqlash uchun qaysi xotira ishlatiladi?","o":["RAM","SSD yoki HDD","Protsessor registri","Videokarta xotirasi"],"a":1,"e":"SSD va HDD doimiy saqlash qurilmalaridir."},{"q":"Texnologiyaga qanday munosabatda bo‘lish to‘g‘ri?","o":["Faqat maqtash","Umuman e’tibor bermaslik","Faqat rad etish","Foyda va xavflarini birgalikda baholash"],"a":3,"e":"Tanqidiy yondashuv zarur."},{"q":"Noutbukda sichqoncha o‘rnini odatda qaysi qurilma bosadi?","o":["Proyektor","Sensorli panel (tachpad)","Joystik","Mikrofon"],"a":1,"e":"Tachpad ko‘rsatkichni barmoq harakati bilan boshqaradi."},{"q":"Stol usti kompyuterining noutbukka nisbatan odatiy afzalligi nima?","o":["Cho‘ntakka sig‘ishi","Narxga nisbatan quvvatli va kengaytirish oson","Og‘irligi juda yengil bo‘lishi","Batareyada uzoq ishlashi"],"a":1,"e":"Stol usti kompyuteri odatda arzon va kengaytiriladi."},{"q":"Matn terishda bosh harf yozish uchun qaysi tugma bosib turiladi?","o":["Shift","Esc","Delete","Insert"],"a":0,"e":"Shift bosilganda bosh harf yoziladi."},{"q":"Quyidagi juftliklardan qaysi biri to‘g‘ri moslangan?","o":["Karnay — tovush chiqarish","Skaner — tovush chiqarish","Mikrofon — chop etish","Printer — ovoz yozish"],"a":0,"e":"Karnay tovushni eshittiradi."},{"q":"2 GB necha MBga teng?","o":["2000","1024","4096","2048"],"a":3,"e":"2 · 1024 = 2048."},{"q":"Harakatlanuvchi mexanik qismlarsiz ishlaydigan va tez xotira qurilmasi qaysi?","o":["CD-ROM","HDD","Disketa","SSD"],"a":3,"e":"SSD flesh-xotirada ishlaydi."},{"q":"Printerning tezligi odatda qanday o‘lchanadi?","o":["Voltlarda","Daqiqada chop etilgan sahifalar soni","Gigabaytlarda","Megapikselda"],"a":1,"e":"Tezlik sahifa/daqiqa ko‘rsatkichi bilan beriladi."}]},{"t":"12-dars. Kompyuter tarmoqlari qurilmalari","lesson":"<p><b>Kompyuter tarmog‘i</b> — o‘zaro ulangan kompyuterlar va qurilmalar tizimi bo‘lib, ular ma’lumot almashadi va resurslarni (printer, fayl) birgalikda ishlatadi. Tarmoq turlari: <b>LAN</b> (mahalliy, masalan, maktab ichida) va <b>WAN</b> (global, masalan, internet).</p>\n<h4>Asosiy tarmoq qurilmalari</h4>\n<ul><li><b>Tarmoq kartasi</b> — kompyuterni tarmoqqa ulaydi.</li>\n<li><b>Modem</b> — signalni aloqa liniyasi uchun o‘zgartiradi va internetga chiqish imkonini beradi.</li>\n<li><b>Router (marshrutizator)</b> — turli tarmoqlarni bog‘laydi, ma’lumot yo‘lini belgilaydi; ko‘pincha Wi-Fi tarqatadi.</li>\n<li><b>Switch (kommutator)</b> — mahalliy tarmoqdagi qurilmalarni ulaydi va ma’lumotni aynan kerakli qurilmaga yo‘naltiradi.</li>\n<li><b>Simli ulanish</b> — juft o‘ralgan kabel, optik tola; <b>simsiz</b> — Wi-Fi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Kompyuter xonasida switch barcha kompyuterlarni ulaydi, router esa ularni internetga chiqaradi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Router tarmoqlarni bog‘laydi, switch — tarmoq ichidagi qurilmalarni.</li></ul>","quiz":[{"q":"LAN nima?","o":["Mahalliy kompyuter tarmog‘i","Global tarmoq","Antivirus dasturi","Operatsion tizim"],"a":0,"e":"LAN — kichik hududdagi tarmoq."},{"q":"Kompyuterni tarmoqqa ulaydigan ichki qurilma qaysi?","o":["Ovoz kartasi","Tarmoq kartasi","Video karta","Fleshka"],"a":1,"e":"Tarmoq kartasi ulanishni ta’minlaydi."},{"q":"Turli tarmoqlarni bog‘lab, ma’lumot yo‘lini belgilaydigan qurilma qaysi?","o":["Skaner","Mikrofon","Router","Klaviatura"],"a":2,"e":"Router marshrutni tanlaydi."},{"q":"Mahalliy tarmoqdagi qurilmalarni ulaydigan qurilma qaysi?","o":["Switch","Monitor","Plotter","Proyektor"],"a":0,"e":"Switch qurilmalarni bir tarmoqqa birlashtiradi."},{"q":"Optik tolali kabelning afzalligi nima?","o":["Elektr tokini o‘tkazishi","Faqat qisqa masofada ishlashi","Simsiz bo‘lishi","Ma’lumotni yuqori tezlikda va uzoq masofaga uzatishi"],"a":3,"e":"Optik tola yorug‘lik orqali uzatadi."},{"q":"Wi-Fi qanday aloqa turiga kiradi?","o":["Kesh","Simsiz","Optik disk","Simli"],"a":1,"e":"Wi-Fi radio to‘lqinlari orqali ishlaydi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["LAN butun dunyoni qamrab oladi","Switch internet tezligini oshiradi","Modem rasmni chop etadi","Router ko‘pincha Wi-Fi tarqatadi"],"a":3,"e":"Uy routerlari Wi-Fi tarqatishi mumkin."},{"q":"Maktab kompyuter xonasidagi tarmoq qaysi turga kiradi?","o":["LAN","GPS","BIOS","WAN"],"a":0,"e":"Bu kichik hududdagi mahalliy tarmoq."},{"q":"Vaziyat: uyda internet yo‘q, telefon liniyasi/provayder kabeli bor. Signalni o‘zgartirib beradigan qurilma qaysi?","o":["Karnay","Printer","Joystik","Modem"],"a":3,"e":"Modem provayder bilan aloqani ta’minlaydi."},{"q":"Tarmoqning asosiy foydasi qaysi?","o":["Rasmni rangli qilish","Elektr sarfini nolga tushirish","Ma’lumot va resurslarni birgalikda ishlatish","Kompyuterni tezlashtirish faqat"],"a":2,"e":"Tarmoqda fayl va printer umumiy bo‘ladi."}]},{"t":"13-dars. Brauzerdan foydalanish. Kompyuter tarmoqlari dasturiy jihati.","lesson":"<p><b>Brauzer</b> — veb-sahifalarni ko‘rish uchun dastur. Mashhur brauzerlar: Google Chrome, Mozilla Firefox, Microsoft Edge, Opera, Safari.</p>\n<h4>Brauzer imkoniyatlari</h4>\n<ul><li><b>Manzil satri</b> — saytning URL manzili kiritiladi.</li>\n<li><b>Xatcho‘p (zakladka)</b> — kerakli sahifani saqlab qo‘yadi.</li>\n<li><b>Tarix</b> — ochilgan sahifalar ro‘yxati.</li>\n<li><b>Yangi oyna/varaq</b> — bir vaqtda bir nechta sahifa bilan ishlash.</li></ul>\n<h4>Tarmoqning dasturiy jihati</h4>\n<ul><li><b>Protokol</b> — qurilmalar ma’lumot almashish qoidalari (TCP/IP, HTTP).</li>\n<li><b>IP-manzil</b> — tarmoqdagi qurilma manzili.</li>\n<li><b>DNS</b> — domen nomini (masalan, sayt nomi) IP-manzilga o‘giradi.</li>\n<li><b>HTTPS</b> — ma’lumotlarni shifrlab uzatadigan xavfsizroq protokol.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Manzil satriga sayt nomini yozib Enter bosganingizda brauzer serverga so‘rov yuboradi va sahifani ko‘rsatadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Brauzer — sahifa ko‘rish dasturi; DNS — nomni IP-manzilga aylantiradi.</li></ul>","quiz":[{"q":"Brauzer nima?","o":["Veb-sahifalarni ko‘rish uchun dastur","Qurilma","Fayl formati","Antivirus"],"a":0,"e":"Brauzer saytlarni ochib beradi."},{"q":"Quyidagilardan qaysi biri brauzer?","o":["Router","Windows","Mozilla Firefox","Wi-Fi"],"a":2,"e":"Firefox — brauzer."},{"q":"Sayt manzili brauzerning qaysi qismiga kiritiladi?","o":["Zakladkaga faqat","Tarixga","Holat satriga","Manzil satriga"],"a":3,"e":"URL manzil satriga yoziladi."},{"q":"Keyin qaytib kelish uchun sahifani saqlab qo‘yish qaysi vosita bilan bajariladi?","o":["Xatcho‘p (zakladka)","Printer","Kesh","Skaner"],"a":0,"e":"Xatcho‘p sevimli sahifalarni saqlaydi."},{"q":"DNS ning vazifasi nima?","o":["Faylni arxivlash","Viruslarni o‘chirish","Tasvirni chop etish","Domen nomini IP-manzilga aylantirish"],"a":3,"e":"DNS nomlar tizimidir."},{"q":"Qaysi protokol ma’lumotlarni shifrlab uzatadi?","o":["HTTP","FTP-siz oddiy","HTTPS","BIOS"],"a":2,"e":"HTTPS xavfsiz ulanishni ta’minlaydi."},{"q":"IP-manzil nimani bildiradi?","o":["Tarmoqdagi qurilmaning manzilini","Ekran ruxsatini","Faylning hajmini","Printer tezligini"],"a":0,"e":"IP har bir qurilmani aniqlaydi."},{"q":"Protokol nima?","o":["Xotira qurilmasi","Fayl kengaytmasi","Tarmoqda ma’lumot almashish qoidalari to‘plami","Brauzer turi"],"a":2,"e":"Protokol qurilmalar kelishuvidir."},{"q":"Vaziyat: sayt ochilmayapti, lekin boshqa sayt ochilyapti. Birinchi navbatda nima qilish mumkin?","o":["Klaviaturani tozalash","Kompyuterni sindirish","Monitorni almashtirish","Manzilni to‘g‘ri yozilganini tekshirib, sahifani yangilash"],"a":3,"e":"Avval oddiy sabablar tekshiriladi."},{"q":"Bir vaqtda bir nechta saytni ochish uchun nimadan foydalaniladi?","o":["Skaner","Proyektor","Yangi varaq (vkladka)","Faqat yangi kompyuter"],"a":2,"e":"Brauzerda bir nechta varaq ochish mumkin."}]},{"t":"14-dars. Tarmoq muammolari va kommunikatsiya","lesson":"<p>Kompyuter tarmog‘ida ishlaganda turli muammolar yuzaga kelishi mumkin. Ularni to‘g‘ri aniqlash va bartaraf etish tarmoqdan uzluksiz foydalanish imkonini beradi. Kommunikatsiya — ma’lumot almashish jarayonidir. Muammoni tez topish uchun uni izchil, bosqichma-bosqich tekshirish kerak.</p>\n<h4>Tarmoqdagi odatiy muammolar</h4>\n<ul><li>Internetga ulanishning yo‘qligi yoki tezlikning pastligi.</li>\n<li>Kabel yoki Wi-Fi signalining zaifligi.</li>\n<li>Router yoki modemning noto‘g‘ri sozlanishi.</li>\n<li>Viruslar va ruxsatsiz kirish xavfi.</li>\n<li>Ko‘p foydalanuvchi bir vaqtda ulangani sababli yuklanishning oshishi.</li></ul>\n<h4>Muammoni hal qilish tartibi</h4>\n<ul><li>Kabel va qurilmalar ulanganini tekshirish.</li>\n<li>Routerni qayta yoqish.</li>\n<li>Boshqa qurilmada ishlayotganini sinab ko‘rish.</li>\n<li>Hal bo‘lmasa, provayder yoki mutaxassisga murojaat qilish.</li></ul>\n<h4>Kommunikatsiya vositalari</h4>\n<ul><li>Elektron pochta, messenjerlar, video qo‘ng‘iroqlar va forumlar.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Telefon Wi-Fi ga ulangan, lekin sahifalar ochilmayapti. Avval boshqa qurilma ishlayotganini tekshiring, so‘ng routerni qayta yoqing.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Muammoni avval oddiy sabablardan boshlab tekshiring.</li><li>Tarmoq xavfsizligi ham muhim muammodir.</li></ul>","quiz":[{"q":"Quyidagilardan qaysi biri tarmoq muammosiga misol bo‘ladi?","o":["Wi-Fi signalining zaifligi","Monitor yorqinligining ko‘pligi","Sichqoncha rangi","Klaviatura tugmalari soni"],"a":0,"e":"Signal zaif bo‘lsa, ulanish sekinlashadi."},{"q":"Internet ishlamasa, birinchi navbatda nima qilinadi?","o":["Kompyuter sotiladi","Barcha fayllar o‘chiriladi","Kabel va routerning ulanganligi tekshiriladi","Operatsion tizim o‘chiriladi"],"a":2,"e":"Avval oddiy sabablar tekshiriladi."},{"q":"Routerni qayta yoqish ko‘pincha nimaga yordam beradi?","o":["Vaqtinchalik ulanish nosozligini bartaraf etishga","Fayl hajmini kamaytirishga","Ekran o‘lchamini oshirishga","Tovushni kuchaytirishga"],"a":0,"e":"Qayta yoqish sozlamalarni yangilaydi."},{"q":"Kommunikatsiya nima?","o":["Faqat bosma jarayon","Dasturlash tili","Axborot almashish jarayoni","Xotira turi"],"a":2,"e":"Kommunikatsiya — aloqa va almashinuv."},{"q":"Quyidagilardan qaysi biri kommunikatsiya vositasi?","o":["Elektron pochta","Printer","Ekran","Skaner"],"a":0,"e":"Elektron pochta orqali xat almashiladi."},{"q":"Faqat bitta qurilmada sayt ochilmasa, muammo ko‘proq qayerda bo‘lishi mumkin?","o":["Butun provayderda","Elektr stansiyada","Hamma saytlarda","Shu qurilmaning sozlamalarida"],"a":3,"e":"Boshqalarda ishlasa, muammo shu qurilmada."},{"q":"Ko‘p foydalanuvchi bir vaqtda ulanganda nima yuz berishi mumkin?","o":["Internet tezligi pasayadi","Tarmoq butunlay yo‘qoladi albatta","Tezlik avtomatik oshadi","Fayllar ko‘payadi"],"a":0,"e":"Kanal yuklanishi tezlikni kamaytiradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Muammo doim virus sababli bo‘ladi","Routerga hech qachon tegib bo‘lmaydi","Kabel tarmoqqa ta’sir qilmaydi","Tarmoq muammolarini tartib bilan tekshirish kerak"],"a":3,"e":"Izchil tekshiruv eng samarali."},{"q":"Quyidagi qadamlarning to‘g‘ri tartibi qaysi?","o":["Murojaat, sotish, tekshirish","Ulanishni tekshirish, routerni qayta yoqish, provayderga murojaat","Provayderga murojaat, ulanishni tekshirish, qayta yoqish","Qayta yoqish, kompyuterni sotish, tekshirish"],"a":1,"e":"Oddiydan murakkabga qarab boriladi."},{"q":"Hal bo‘lmagan tarmoq muammosida oxirgi chora qaysi?","o":["Provayder yoki mutaxassisga murojaat qilish","Kabelni kesish","Dasturlarni o‘chirish","Ekranni tozalash"],"a":0,"e":"Mutaxassis chuqur tekshiradi."}]},{"t":"15-dars. Axborot texnologiyasining bandlikka ta‘siri","lesson":"<p>Axborot texnologiyalari (AT) mehnat bozorini tubdan o‘zgartirdi. Ba’zi kasblar avtomatlashtirilganligi sababli kamaydi, yangi kasblar paydo bo‘ldi, ko‘plab ishlarda esa kompyuter bilimi talab qilinadigan bo‘ldi.</p>\n<h4>Ijobiy ta’sirlari</h4>\n<ul><li>Yangi kasblar: dasturchi, veb-dizayner, ma’lumotlar tahlilchisi, kiberxavfsizlik mutaxassisi.</li>\n<li>Masofadan ishlash imkoniyati.</li>\n<li>Ish unumdorligining oshishi.</li>\n<li>Takrorlanuvchi og‘ir ishlarning avtomatlashtirilishi.</li></ul>\n<h4>Salbiy ta’sirlari</h4>\n<ul><li>Ba’zi oddiy kasblarga ehtiyojning kamayishi.</li>\n<li>Doimiy o‘qib-o‘rganish zaruriyati.</li>\n<li>Raqamli bilimi yo‘q kishilarning ish topishi qiyinlashishi.</li></ul>\n<h4>Qanday tayyorlanish kerak</h4>\n<ul><li>Raqamli savodxonlikni oshirish, yangi dasturlarni o‘rganish.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Do‘kon kassirlari o‘rniga o‘z-o‘ziga xizmat kassalari paydo bo‘ldi, lekin ularni sozlovchi va dasturlovchi mutaxassislarga ehtiyoj ortdi.</div>\n<p>Bugungi kunda deyarli har bir sohada — tibbiyot, ta’lim, qurilish, savdo va qishloq xo‘jaligida — axborot texnologiyalaridan foydalaniladi. Shuning uchun maktabda olingan informatika bilimlari kelajakdagi kasb tanlashda katta yordam beradi. Texnologiyalar o‘zgarishi bilan xodimlar o‘z malakasini muntazam oshirib borishi lozim.</p>\n<h4>Eslab qoling</h4>\n<ul><li>AT bandlikka ham ijobiy, ham salbiy ta’sir qiladi.</li><li>Doimiy o‘qish zamonaviy kasblarda muhim.</li></ul>","quiz":[{"q":"AT ning bandlikka ijobiy ta’siri qaysi?","o":["Ish haqining to‘xtashi","Ishning umuman bo‘lmasligi","Barcha kasblarning yo‘qolishi","Yangi kasblarning paydo bo‘lishi"],"a":3,"e":"Dasturchi kabi kasblar paydo bo‘ldi."},{"q":"Quyidagilardan qaysi biri AT bilan bog‘liq yangi kasb?","o":["Qo‘lda yozuvchi kotib-mashinist","Veb-dizayner","Chorvador","Fonar yoquvchi"],"a":1,"e":"Veb-dizayner internet davrida paydo bo‘lgan."},{"q":"Masofadan ishlash nimani anglatadi?","o":["Ishni to‘xtatishni","Ishni ofisga bormay, tarmoq orqali bajarishni","Ishdan bo‘shashni","Faqat qog‘ozda ishlashni"],"a":1,"e":"Internet orqali ishlash mumkin."},{"q":"Avtomatlashtirish nimaga olib kelishi mumkin?","o":["Tarmoqning to‘xtashiga","Barcha ishlarning ko‘payishiga","Ba’zi oddiy ishlarga ehtiyojning kamayishiga","Elektr sarfining yo‘qolishiga"],"a":2,"e":"Mashinalar takroriy ishni bajaradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Bir marta o‘qish butun umrga yetadi","Zamonaviy kasblarda doimiy o‘rganish zarur","Kompyuter bilimi hech qachon kerak bo‘lmaydi","AT faqat o‘yin uchun"],"a":1,"e":"Texnologiyalar tez o‘zgaradi."},{"q":"Raqamli savodxonlik nima uchun muhim?","o":["Faqat o‘yin o‘ynash uchun","Kitob o‘qimaslik uchun","Elektr tejash uchun","Zamonaviy ish bozorida raqobatbardosh bo‘lish uchun"],"a":3,"e":"Ko‘p kasblar kompyuter bilimini talab qiladi."},{"q":"Vaziyat: korxona hisob ishlarini avtomatlashtirdi. Xodim nima qilishi maqsadga muvofiq?","o":["Hisobni qog‘ozda yuritishda davom etishi","Yangi dasturni o‘rganib malakasini oshirishi","Ishni tashlab ketishi","Dasturdan foydalanmasligi"],"a":1,"e":"Malaka oshirish yo‘li to‘g‘ri."},{"q":"Quyidagilardan qaysi biri AT ning salbiy ta’siriga misol?","o":["Ish unumdorligining oshishi","Masofadan ishlash","Ba’zi kasblarning kamayishi","Yangi kasblarning paydo bo‘lishi"],"a":2,"e":"Bu ish o‘rinlari kamayishi bilan bog‘liq."},{"q":"Ma’lumotlar tahlilchisi qanday kasb?","o":["AT bilan bog‘liq zamonaviy kasb","Qishloq xo‘jaligi mashinasi","Faqat qurilish kasbi","Qadimiy hunar"],"a":0,"e":"U ma’lumotlar bilan ishlaydi."},{"q":"AT ish unumdorligiga qanday ta’sir ko‘rsatadi?","o":["Ishlarni tezlashtirib, unumdorlikni oshiradi","Faqat vaqtni cho‘zadi","Unumdorlikni doim pasaytiradi","Hech ta’sir qilmaydi"],"a":0,"e":"Avtomatlashtirish vaqtni tejaydi."}]},{"t":"16-dars. Axborot texnologiyasi (AT) ning tashkilotlar ish uslubiga ta‘siri. Mikroprotsessorli uy qurilmalari","lesson":"<p>Axborot texnologiyalari tashkilotlarning ish uslubini o‘zgartirdi: hujjatlar elektron shaklga o‘tdi, ma’lumot almashish tezlashdi, ko‘plab jarayonlar avtomatlashtirildi. Uyda ham mikroprotsessorli qurilmalar keng tarqaldi.</p>\n<h4>Tashkilotlarda o‘zgarishlar</h4>\n<ul><li>Elektron hujjat aylanishi va elektron pochta.</li>\n<li>Ma’lumotlar bazalarida axborotni saqlash.</li>\n<li>Video konferensiyalar orqali yig‘ilishlar.</li>\n<li>Onlayn to‘lovlar va xizmatlar.</li></ul>\n<h4>Mikroprotsessorli uy qurilmalari</h4>\n<ul><li>Mikroprotsessor — qurilmani boshqaruvchi kichik kompyuter chipi.</li>\n<li>Misollar: kir yuvish mashinasi, mikroto‘lqinli pech, televizor, konditsioner, muzlatgich.</li></ul>\n<h4>Afzalliklari</h4>\n<ul><li>Qulaylik, vaqt va energiyani tejash, sozlamalarni dasturlash imkoniyati.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Kir yuvish mashinasida dastur tanlaganingizda mikroprotsessor suv haroratini va yuvish vaqtini avtomatik boshqaradi.</div>\n<p>Axborot texnologiyalari yordamida tashkilotlar mijozlarga xizmat ko‘rsatishni yaxshiladi: ariza va so‘rovlar masofadan qabul qilinadi, hisob-kitoblar tez bajariladi, xatolar kamayadi. Uyda esa aqlli qurilmalar kundalik ishlarni yengillashtiradi. Biroq har qanday texnika xavfsiz ishlatilishi va unga ehtiyotkorlik bilan munosabatda bo‘lish kerak.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Mikroprotsessor qurilmani boshqaradi.</li><li>AT tashkilotlarda ishni tezlashtiradi.</li></ul>","quiz":[{"q":"Mikroprotsessor nima?","o":["Kabel turi","Faqat ekran","Qurilmani boshqaruvchi chip","Xotira qutisi"],"a":2,"e":"U buyruqlarni bajaradi."},{"q":"Quyidagilardan qaysi biri mikroprotsessorli uy qurilmasi?","o":["Qog‘oz daftar","Mikroto‘lqinli pech","Yog‘och stol","Oddiy qoshiq"],"a":1,"e":"Zamonaviy pech boshqaruv chipiga ega."},{"q":"AT tashkilotlarda hujjatlar bilan ishlashni qanday o‘zgartirdi?","o":["Hujjatlarni butunlay yo‘q qildi","Faqat qo‘lda yozishni majbur qildi","Ularni sekinlashtirdi","Elektron hujjat aylanishiga o‘tkazdi"],"a":3,"e":"Elektron hujjatlar tez almashinadi."},{"q":"Video konferensiya nimaga imkon beradi?","o":["Uzoqdagi kishilar bilan jonli yig‘ilish o‘tkazishga","Ekranni tozalashga","Fayl o‘chirishga","Kabel tortishga"],"a":0,"e":"Video aloqa orqali uchrashiladi."},{"q":"Elektron to‘lovlarning afzalligi nima?","o":["Tezlik va qulaylik","Internet kerak emas deb hisoblanishi","Doimiy navbat","Faqat qog‘oz pul bilan ishlash"],"a":0,"e":"Onlayn to‘lov vaqtni tejaydi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Ular qo‘lda ishlaydi doim","Mikroprotsessor qurilma ish rejimini avtomatik boshqarishi mumkin","Uy qurilmalarida protsessor bo‘lmaydi","Mikroprotsessor faqat kompyuterda bo‘ladi"],"a":1,"e":"Ko‘p maishiy texnikada chip bor."},{"q":"Ma’lumotlar bazasi tashkilotda nima uchun kerak?","o":["Elektr ta’minoti uchun","Tovushni kuchaytirish uchun","Axborotni tartibli saqlash va qidirish uchun","Faqat rasm chizish uchun"],"a":2,"e":"Baza ma’lumotni tartibga soladi."},{"q":"Vaziyat: yig‘ilishga ishtirokchilar turli shaharlarda. Qanday yechim qulay?","o":["Barchasini bir kunda yig‘ish","Xat yuborib kutish yil davomida","Video konferensiya o‘tkazish","Yig‘ilishni bekor qilish"],"a":2,"e":"Video aloqa vaqtni tejaydi."},{"q":"Konditsionerdagi mikroprotsessor nimani boshqaradi?","o":["Derazani","Devor qalinligini","Binoning rangini","Haroratni sozlash rejimini"],"a":3,"e":"U haroratni saqlab turadi."},{"q":"Mikroprotsessorli uy qurilmalarining afzalligi qaysi?","o":["Vaqt va energiyani tejash","Ishlamasligi","Har doim qimmatligi","Faqat murakkabligi"],"a":0,"e":"Avtomatlashtirish qulaylik beradi."}]},{"t":"17-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 2</b> quyidagi darslarni qamrab oladi:</p><ul><li>Kompyuter tarmoqlari qurilmalari</li><li>Brauzerdan foydalanish. Kompyuter tarmoqlari dasturiy jihati.</li><li>Tarmoq muammolari va kommunikatsiya</li><li>Axborot texnologiyasining bandlikka ta‘siri</li><li>Axborot texnologiyasi (AT) ning tashkilotlar ish uslubiga ta‘siri. Mikroprotsessorli uy qurilmalari</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Qaysi protokol ma’lumotlarni shifrlab uzatadi?","o":["HTTP","FTP-siz oddiy","HTTPS","BIOS"],"a":2,"e":"HTTPS xavfsiz ulanishni ta’minlaydi."},{"q":"Quyidagilardan qaysi biri kommunikatsiya vositasi?","o":["Elektron pochta","Printer","Ekran","Skaner"],"a":0,"e":"Elektron pochta orqali xat almashiladi."},{"q":"DNS ning vazifasi nima?","o":["Faylni arxivlash","Viruslarni o‘chirish","Tasvirni chop etish","Domen nomini IP-manzilga aylantirish"],"a":3,"e":"DNS nomlar tizimidir."},{"q":"Ma’lumotlar tahlilchisi qanday kasb?","o":["AT bilan bog‘liq zamonaviy kasb","Qishloq xo‘jaligi mashinasi","Faqat qurilish kasbi","Qadimiy hunar"],"a":0,"e":"U ma’lumotlar bilan ishlaydi."},{"q":"Tarmoqning asosiy foydasi qaysi?","o":["Rasmni rangli qilish","Elektr sarfini nolga tushirish","Ma’lumot va resurslarni birgalikda ishlatish","Kompyuterni tezlashtirish faqat"],"a":2,"e":"Tarmoqda fayl va printer umumiy bo‘ladi."},{"q":"AT tashkilotlarda hujjatlar bilan ishlashni qanday o‘zgartirdi?","o":["Hujjatlarni butunlay yo‘q qildi","Faqat qo‘lda yozishni majbur qildi","Ularni sekinlashtirdi","Elektron hujjat aylanishiga o‘tkazdi"],"a":3,"e":"Elektron hujjatlar tez almashinadi."},{"q":"Ma’lumotlar bazasi tashkilotda nima uchun kerak?","o":["Elektr ta’minoti uchun","Tovushni kuchaytirish uchun","Axborotni tartibli saqlash va qidirish uchun","Faqat rasm chizish uchun"],"a":2,"e":"Baza ma’lumotni tartibga soladi."},{"q":"Maktab kompyuter xonasidagi tarmoq qaysi turga kiradi?","o":["LAN","GPS","BIOS","WAN"],"a":0,"e":"Bu kichik hududdagi mahalliy tarmoq."},{"q":"Protokol nima?","o":["Xotira qurilmasi","Fayl kengaytmasi","Tarmoqda ma’lumot almashish qoidalari to‘plami","Brauzer turi"],"a":2,"e":"Protokol qurilmalar kelishuvidir."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Bir marta o‘qish butun umrga yetadi","Zamonaviy kasblarda doimiy o‘rganish zarur","Kompyuter bilimi hech qachon kerak bo‘lmaydi","AT faqat o‘yin uchun"],"a":1,"e":"Texnologiyalar tez o‘zgaradi."},{"q":"Masofadan ishlash nimani anglatadi?","o":["Ishni to‘xtatishni","Ishni ofisga bormay, tarmoq orqali bajarishni","Ishdan bo‘shashni","Faqat qog‘ozda ishlashni"],"a":1,"e":"Internet orqali ishlash mumkin."},{"q":"Optik tolali kabelning afzalligi nima?","o":["Elektr tokini o‘tkazishi","Faqat qisqa masofada ishlashi","Simsiz bo‘lishi","Ma’lumotni yuqori tezlikda va uzoq masofaga uzatishi"],"a":3,"e":"Optik tola yorug‘lik orqali uzatadi."},{"q":"Avtomatlashtirish nimaga olib kelishi mumkin?","o":["Tarmoqning to‘xtashiga","Barcha ishlarning ko‘payishiga","Ba’zi oddiy ishlarga ehtiyojning kamayishiga","Elektr sarfining yo‘qolishiga"],"a":2,"e":"Mashinalar takroriy ishni bajaradi."},{"q":"Quyidagilardan qaysi biri tarmoq muammosiga misol bo‘ladi?","o":["Wi-Fi signalining zaifligi","Monitor yorqinligining ko‘pligi","Sichqoncha rangi","Klaviatura tugmalari soni"],"a":0,"e":"Signal zaif bo‘lsa, ulanish sekinlashadi."},{"q":"Quyidagi qadamlarning to‘g‘ri tartibi qaysi?","o":["Murojaat, sotish, tekshirish","Ulanishni tekshirish, routerni qayta yoqish, provayderga murojaat","Provayderga murojaat, ulanishni tekshirish, qayta yoqish","Qayta yoqish, kompyuterni sotish, tekshirish"],"a":1,"e":"Oddiydan murakkabga qarab boriladi."},{"q":"Keyin qaytib kelish uchun sahifani saqlab qo‘yish qaysi vosita bilan bajariladi?","o":["Xatcho‘p (zakladka)","Printer","Kesh","Skaner"],"a":0,"e":"Xatcho‘p sevimli sahifalarni saqlaydi."},{"q":"Hal bo‘lmagan tarmoq muammosida oxirgi chora qaysi?","o":["Provayder yoki mutaxassisga murojaat qilish","Kabelni kesish","Dasturlarni o‘chirish","Ekranni tozalash"],"a":0,"e":"Mutaxassis chuqur tekshiradi."},{"q":"Video konferensiya nimaga imkon beradi?","o":["Uzoqdagi kishilar bilan jonli yig‘ilish o‘tkazishga","Ekranni tozalashga","Fayl o‘chirishga","Kabel tortishga"],"a":0,"e":"Video aloqa orqali uchrashiladi."},{"q":"Mikroprotsessorli uy qurilmalarining afzalligi qaysi?","o":["Vaqt va energiyani tejash","Ishlamasligi","Har doim qimmatligi","Faqat murakkabligi"],"a":0,"e":"Avtomatlashtirish qulaylik beradi."},{"q":"Mahalliy tarmoqdagi qurilmalarni ulaydigan qurilma qaysi?","o":["Switch","Monitor","Plotter","Proyektor"],"a":0,"e":"Switch qurilmalarni bir tarmoqqa birlashtiradi."}]},{"t":"18-dars. Axborot texnologiyasi (AT) jihozlaridan uzoq muddat foydalanishning sog‘liqqa ta‘siri","lesson":"<p>Kompyuter, telefon va boshqa AT jihozlaridan uzoq vaqt foydalanish sog‘liqqa ta’sir qilishi mumkin. Shu sababli to‘g‘ri o‘tirish, tanaffus qilish va ish joyini to‘g‘ri tashkil etish muhim.</p>\n<h4>Mumkin bo‘lgan muammolar</h4>\n<ul><li>Ko‘z charchashi va ko‘rish pasayishi.</li>\n<li>Bel va bo‘yin og‘rig‘i, noto‘g‘ri qomat.</li>\n<li>Qo‘l va barmoqlarning charchashi.</li>\n<li>Bosh og‘rig‘i va uyqu buzilishi.</li>\n<li>Harakatsizlik oqibatida umumiy holsizlik.</li></ul>\n<h4>Profilaktika qoidalari</h4>\n<ul><li>Ekran ko‘z darajasida yoki biroz pastroqda bo‘lsin.</li>\n<li>Orqa tayanchli stulda to‘g‘ri o‘tiring.</li>\n<li>Har ma’lum vaqtdan keyin tanaffus qilib, ko‘z mashqlarini bajaring.</li>\n<li>Xona yaxshi yoritilgan va shamollatilgan bo‘lsin.</li>\n<li>Kechqurun ekran qarshisida uzoq o‘tirmang.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Uzoq ishlaganda har birozdan so‘ng ekrandan uzoqqa qarang, turib yuring va qo‘llaringizni cho‘zing.</div>\n<p>Ayniqsa o‘smirlar uchun ekran qarshisida o‘tkaziladigan vaqtni me’yorlash muhim. Kompyuter yoki telefondan foydalanish vaqtini rejalashtirib, dars, dam olish va jismoniy mashqlar uchun ham vaqt ajrating. Toza havoda sayr qilish va sport ko‘zni ham, butun tanani ham mustahkamlaydi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Tanaffus va to‘g‘ri o‘tirish sog‘liqni asraydi.</li><li>Ekranga uzoq tikilish ko‘zni charchatadi.</li></ul>","quiz":[{"q":"Uzoq vaqt kompyuterda ishlashning asosiy xavfi qaysi?","o":["Ko‘z charchashi va qomat buzilishi","Fayl yo‘qolishi","Ekranning yonib ketishi","Dastur eskirishi"],"a":0,"e":"Bu sog‘liqqa ta’siridir."},{"q":"Ekran qanday joylashtirilishi kerak?","o":["Yerga qo‘yilib","Orqa tomonda","Juda yuqorida shiftga yaqin","Ko‘z darajasida yoki biroz pastroqda"],"a":3,"e":"To‘g‘ri joylashuv bo‘yinni asraydi."},{"q":"Ishlash paytida tanaffus nima uchun kerak?","o":["Internetni ulash uchun","Dasturni yangilash uchun","Kompyuterni tezlashtirish uchun","Ko‘z va tanani dam oldirish uchun"],"a":3,"e":"Dam sog‘liq uchun foydali."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Tanaffus umuman kerak emas","Egilib o‘tirish foydali","Ko‘z uchun mashqlar charchoqni kamaytiradi","Qorong‘i xonada ishlash eng yaxshi"],"a":2,"e":"Mashqlar ko‘zni dam oldiradi."},{"q":"Qaysi o‘tirish usuli to‘g‘ri?","o":["Divanda qiyshayib","Orqa tayanchga tiralgan, tik holatda","Stulda yarim yotib","Oyoqni osiltirib doim"],"a":1,"e":"To‘g‘ri qomat bel og‘rig‘ini oldini oladi."},{"q":"Ish xonasiga qanday talab qo‘yiladi?","o":["Qorong‘i va yopiq bo‘lishi","Yaxshi yoritilgan va shamollatilgan bo‘lishi","Nam bo‘lishi","Juda shovqinli bo‘lishi"],"a":1,"e":"Yorug‘lik ko‘zni asraydi."},{"q":"Vaziyat: o‘quvchi uch soat tanaffussiz kompyuterda o‘tirdi, ko‘zi og‘riyapti. Nima qilishi kerak?","o":["Yana uzoq o‘tirishi","Tanaffus qilib, ko‘z mashqlarini bajarishi","Ekranga yanada yaqin o‘tirishi","Yorqinlikni maksimalga qo‘yishi"],"a":1,"e":"Ko‘zga dam kerak."},{"q":"Qo‘l va barmoqlarning charchashi nima bilan bog‘liq?","o":["Fayl hajmi","Klaviatura va sichqoncha bilan uzoq ishlash","Ekranning rangi","Internet tezligi"],"a":1,"e":"Bir xil harakat charchatadi."},{"q":"Harakatsizlik oqibati qaysi?","o":["Ko‘rishning yaxshilanishi","Umumiy holsizlik va vazn ortishi","Kuchning ortishi doim","Tezlikning oshishi"],"a":1,"e":"Harakat yetishmasa, sog‘liq yomonlashadi."},{"q":"Kechqurun ekran oldida uzoq o‘tirish nimaga ta’sir qilishi mumkin?","o":["Internet protokoliga","Fayl kengaytmasiga","Uyquga","Faqat klaviaturaga"],"a":2,"e":"Ekran yorug‘ligi uyquni buzishi mumkin."}]},{"t":"19-dars. Kommunikatsiya dasturlari qamrovi. Ma‘lumotlarni boshqarish dasturlari","lesson":"<p>Kommunikatsiya dasturlari odamlar o‘rtasida axborot almashishga xizmat qiladi. Ma’lumotlarni boshqarish dasturlari esa axborotni to‘plash, saqlash, qidirish va tartiblash imkonini beradi. Ikkala tur ham zamonaviy ish va o‘qishda keng qo‘llaniladi.</p>\n<h4>Kommunikatsiya dasturlari</h4>\n<ul><li>Elektron pochta mijozlari va veb-pochta.</li>\n<li>Messenjerlar va video aloqa dasturlari.</li>\n<li>Forumlar, ijtimoiy tarmoqlar va bloglar.</li>\n<li>Ular matn, rasm, ovoz va video almashish imkonini beradi.</li></ul>\n<h4>Ma’lumotlarni boshqarish dasturlari</h4>\n<ul><li>Ma’lumotlar bazasini boshqarish tizimlari (MBBT).</li>\n<li>Elektron jadvallar: ma’lumotni jadval ko‘rinishida saqlash va hisoblash.</li>\n<li>Ularda saralash, qidirish va filtrlash bajariladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab kutubxonasi kitoblar ro‘yxatini ma’lumotlar bazasida saqlaydi va kerakli kitobni muallif yoki nomi bo‘yicha tez qidiradi.</div>\n<p>Kundalik hayotda bu dasturlardan birgalikda foydalaniladi: masalan, hisobotni elektron jadvalda tayyorlab, elektron pochta orqali yuboramiz. Shuning uchun har ikki tur dasturning imkoniyatlarini bilish vaqtni tejaydi va ishni qulaylashtiradi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Kommunikatsiya dasturlari aloqa uchun, boshqaruv dasturlari ma’lumot bilan ishlash uchun.</li><li>Saralash va qidirish ma’lumot bilan ishlashning asosiy amallari.</li></ul>","quiz":[{"q":"Kommunikatsiya dasturlarining asosiy vazifasi nima?","o":["Rasm chizish","Tovushni yozish","Odamlar o‘rtasida axborot almashish","Faylni arxivlash"],"a":2,"e":"Ular aloqa vositasi."},{"q":"Quyidagilardan qaysi biri kommunikatsiya dasturi?","o":["Elektron jadval","Messenjer","Grafik muharrir","Arxivator"],"a":1,"e":"Messenjer xabar almashadi."},{"q":"Ma’lumotlarni boshqarish dasturlari nima qiladi?","o":["Ekranni o‘chirish","Ma’lumotni saqlash, qidirish va tartiblash","Faqat musiqa chalish","Faqat chop etish"],"a":1,"e":"Axborotni tartibli boshqaradi."},{"q":"MBBT qisqartmasi nimani bildiradi?","o":["Monitor bloki","Matn bilan bog‘liq boshqaruv tizimi","Mikroprotsessorli bloklarni boshqarish tizimi","Ma’lumotlar bazasini boshqarish tizimi"],"a":3,"e":"Ma’lumotlar bazasi bilan ishlaydi."},{"q":"Elektron jadvalning vazifasi qaysi?","o":["Video montaj qilish","Ma’lumotni jadvalda saqlash va hisoblash","Veb sahifa ko‘rish","Antivirus ishlatish"],"a":1,"e":"Excel kabi dasturlar hisoblaydi."},{"q":"Quyidagilardan qaysi biri ma’lumot bilan ishlash amali?","o":["Printerni tozalash","Kabel tortish","Ekranni yoritish","Saralash"],"a":3,"e":"Saralash tartiblaydi."},{"q":"Vaziyat: kutubxonachi minglab kitob orasidan bittasini tez topishi kerak. Qaysi dastur qulay?","o":["Ma’lumotlar bazasi","Taqdimot dasturi","Rasm muharriri","Audio pleyer"],"a":0,"e":"Bazada qidiruv tez."},{"q":"Video aloqa dasturi qaysi turga kiradi?","o":["Operatsion tizim","Ma’lumot bazasi","Kommunikatsiya dasturi","Antivirus"],"a":2,"e":"Aloqa uchun ishlatiladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Elektron pochta faqat rasm chizadi","Elektron jadvalda xat yuborilmaydi hech qachon","Messenjer ma’lumot bazasi hisoblanadi","Elektron pochta orqali fayl yuborish mumkin"],"a":3,"e":"Pochta fayl biriktirib yuboradi."},{"q":"Filtrlash nima?","o":["Ekranni yopish","Barcha ma’lumotni o‘chirish","Shartga mos ma’lumotlarni ajratib ko‘rsatish","Ma’lumotni shifrlash"],"a":2,"e":"Shartga javob berganlari ko‘rsatiladi."}]},{"t":"20-dars. O‘lchov dasturlari. Boshqaruv dasturlaridagi mikroprotsessorlar","lesson":"<p>Dasturlarning yana bir turi — o‘lchov va boshqaruv dasturlari. O‘lchov dasturlari datchiklar yordamida fizik kattaliklarni (harorat, bosim, tezlik, namlik) qayd etadi. Boshqaruv dasturlari esa qurilma yoki jarayonni avtomatik boshqaradi.</p>\n<h4>O‘lchov dasturlari</h4>\n<ul><li>Datchiklardan olingan ma’lumotni qabul qiladi va ko‘rsatadi.</li>\n<li>Natijalarni yozib borib, grafik yoki jadval ko‘rinishida beradi.</li>\n<li>Misol: ob-havo stansiyasi, tibbiy monitoring, laboratoriya o‘lchovlari.</li></ul>\n<h4>Boshqaruv dasturlari va mikroprotsessorlar</h4>\n<ul><li>Mikroprotsessor dasturni bajarib, qurilmani boshqaradi.</li>\n<li>Datchik ma’lumoti asosida qaror qabul qilinadi.</li>\n<li>Misol: svetofor, avtomatik eshik, isitish tizimi, kir yuvish mashinasi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Xonadagi termostat haroratni o‘lchaydi. Harorat belgilangan qiymatdan pasaysa, mikroprotsessor isitgichni yoqadi, yetarli bo‘lsa o‘chiradi.</div>\n<p>Zamonaviy avtomobil, maishiy texnika va sanoat uskunalarida ko‘plab datchiklar va mikroprotsessorlar ishlaydi. Ular odam aralashuvisiz tez va aniq ishlaydi, shuning uchun xatolar kamayadi va xavfli ishlar xavfsizroq bajariladi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>O‘lchov dasturi kattalikni aniqlaydi.</li><li>Boshqaruv dasturi mikroprotsessor yordamida qurilmani boshqaradi.</li></ul>","quiz":[{"q":"O‘lchov dasturlari nimani bajaradi?","o":["Video kesadi","Matn tahrir qiladi","Datchiklar orqali kattaliklarni qayd etadi","Xat yuboradi"],"a":2,"e":"Ular o‘lchaydi."},{"q":"Quyidagilardan qaysi biri o‘lchanadigan kattalik?","o":["Harorat","Klaviatura rangi","Ekran logotipi","Fayl nomi"],"a":0,"e":"Harorat datchik bilan o‘lchanadi."},{"q":"Datchik nima?","o":["Dasturlash tili","Fizik kattalikni o‘lchab signal beruvchi qurilma","Brauzer","Xotira turi"],"a":1,"e":"U ma’lumotni yig‘adi."},{"q":"Boshqaruv dasturlarida mikroprotsessor nima qiladi?","o":["Dastur asosida qurilmani boshqaradi","Faqat tovush chiqaradi","Rasm chizadi","Faqat saqlaydi"],"a":0,"e":"U buyruqlarni bajaradi."},{"q":"Svetofor qaysi turdagi dastur bilan ishlaydi?","o":["Boshqaruv dasturi","Grafik muharrir","Taqdimot dasturi","Kommunikatsiya dasturi"],"a":0,"e":"U signallarni dastur bilan almashtiradi."},{"q":"Termostat misolida qaror qanday qabul qilinadi?","o":["Tasodifiy tanlab","Faqat vaqtga qarab","O‘lchangan haroratni belgilangan qiymat bilan solishtirib","Hech narsaga qaramay"],"a":2,"e":"Solishtirish asosida isitgich yoqiladi."},{"q":"Vaziyat: ob-havo stansiyasi namlikni har soat yozib boradi. Bu qaysi dastur?","o":["O‘yin dasturi","Arxivator","Antivirus","O‘lchov dasturi"],"a":3,"e":"Qiymatni qayd etadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Mikroprotsessor faqat o‘yinda ishlaydi","O‘lchov dasturi qurilmani sotadi","Datchik hech qachon dasturga ulanmaydi","Boshqaruv dasturi datchik ma’lumotidan foydalanishi mumkin"],"a":3,"e":"Datchik va dastur birga ishlaydi."},{"q":"Quyidagilardan qaysi biri avtomatik boshqariladigan qurilma?","o":["Qog‘oz varaq","Yog‘och qalam","Avtomatik eshik","Oddiy tayoq"],"a":2,"e":"U harakatni sezib ochiladi."},{"q":"O‘lchov natijalarini qanday ko‘rsatish mumkin?","o":["Jadval yoki grafik ko‘rinishida","Faqat rasm sifatida arxivlab","Faqat tovush ko‘rinishida","Ko‘rsatib bo‘lmaydi"],"a":0,"e":"Grafik tushunishni osonlashtiradi."}]},{"t":"21-dars. Modellashtirish dasturlari. Boshqaruv, ta‘lim, sog‘liqni saqlash, savdo va autentifikatsiyada kompyuter tizimlari","lesson":"<p>Modellashtirish dasturlari real hodisa yoki jarayonning kompyuterdagi modelini yaratadi. Model yordamida xavfsiz va arzon sinov o‘tkazish mumkin. Kompyuter tizimlari boshqaruv, ta’lim, sog‘liqni saqlash, savdo va autentifikatsiya sohalarida ham keng qo‘llaniladi.</p>\n<h4>Modellashtirish</h4>\n<ul><li>Jarayon kompyuterda tajriba qilib ko‘riladi.</li>\n<li>Misol: bino mustahkamligini, uchish simulyatorini, aholi o‘sishini modellashtirish.</li></ul>\n<h4>Kompyuter tizimlarining qo‘llanilishi</h4>\n<ul><li>Boshqaruv: hujjat, xodimlar va hisob-kitob tizimlari.</li>\n<li>Ta’lim: elektron darsliklar, onlayn kurslar.</li>\n<li>Sog‘liqni saqlash: bemorlar elektron kartasi, tibbiy uskunalar.</li>\n<li>Savdo: onlayn do‘konlar, shtrix-kod va to‘lov tizimlari.</li>\n<li>Autentifikatsiya: foydalanuvchini parol yoki biometrik belgi bilan tasdiqlash.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Telefonni barmoq izi bilan ochganingizda tizim shaxsingizni tekshiradi. Bu autentifikatsiyadir.</div>\n<p>Modellashtirishda real obyektning faqat muhim xususiyatlari olinadi, shuning uchun model sodda va tushunarli bo‘ladi. Kompyuter tizimlari esa ko‘plab ishlarni tezlashtiradi, lekin ularda shaxsiy ma’lumotlarni himoya qilish ham muhim hisoblanadi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Model — real obyektning soddalashtirilgan ko‘rinishi.</li><li>Autentifikatsiya — shaxsni tasdiqlash.</li></ul>","quiz":[{"q":"Modellashtirishning afzalligi nima?","o":["Natija bermasligi","Doim qimmat bo‘lishi","Faqat qog‘ozda ishlashi","Xavfsiz va arzon sinov o‘tkazish"],"a":3,"e":"Real tajribasiz sinab ko‘rish mumkin."},{"q":"Autentifikatsiya nima?","o":["Tarmoqni uzish","Foydalanuvchi shaxsini tasdiqlash","Faylni nusxalash","Ekranni tozalash"],"a":1,"e":"Shaxs tekshiriladi."},{"q":"Quyidagilardan qaysi biri autentifikatsiya usuli?","o":["Printer turi","Ekran o‘lchami","Fayl kengaytmasi","Parol yoki barmoq izi"],"a":3,"e":"Ular shaxsni tasdiqlaydi."},{"q":"Savdoda kompyuter tizimiga misol qaysi?","o":["Qo‘lda yozilgan daftar","Onlayn do‘kon","Oddiy qadoq","Qog‘oz kvitansiya faqat"],"a":1,"e":"Onlayn do‘kon kompyuter tizimi."},{"q":"Sog‘liqni saqlashda kompyuter tizimi nima uchun qo‘llanadi?","o":["Bemor ma’lumotlarini saqlash va tibbiy uskunalarni boshqarish","Faqat o‘yin uchun","Rasm bo‘yash uchun","Musiqa tinglash uchun"],"a":0,"e":"Elektron karta ma’lumotni saqlaydi."},{"q":"Uchish simulyatori qaysi tushunchaga misol?","o":["Modellashtirish","Arxivlash","Autentifikatsiya","Formatlash"],"a":0,"e":"Real uchishni modellaydi."},{"q":"Vaziyat: muhandis ko‘prik qurmay turib, uning mustahkamligini tekshirmoqchi. Nima qiladi?","o":["Darhol quradi","Hech narsa qilmaydi","Kompyuter modelini yaratadi","Ko‘prik rasmini chizadi xolos"],"a":2,"e":"Model oldindan sinaydi."},{"q":"Ta’limda kompyuter tizimiga misol qaysi?","o":["Onlayn kurs","Doska bo‘ri","Kitob javoni","Qalam"],"a":0,"e":"Masofaviy o‘qitish."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Model har doim real obyektning o‘zi","Model real obyektning soddalashtirilgan ko‘rinishidir","Modellashtirish faqat o‘yin","Model sinash uchun yaramaydi"],"a":1,"e":"Model asosiy belgilarni aks ettiradi."},{"q":"Biometrik autentifikatsiyaga qaysi misol bo‘ladi?","o":["Oddiy kalit","Yuz yoki barmoq izi bilan kirish","Ekran yorqinligi","Qog‘oz xat"],"a":1,"e":"Biometrik belgi shaxsga xos."}]},{"t":"22-dars. Tahlil va loyihalash","lesson":"<p>Axborot tizimini yaratish bir necha bosqichdan iborat. Birinchi bosqich — tahlil va loyihalash. Bunda muammo aniqlanadi, foydalanuvchi ehtiyojlari o‘rganiladi va tizim qanday ishlashi rejalashtiriladi. Yaxshi loyiha keyingi xatolarni kamaytiradi.</p>\n<h4>Tahlil</h4>\n<ul><li>Muammoni va maqsadni aniq belgilash.</li>\n<li>Foydalanuvchilar nimani xohlashini so‘rash va o‘rganish.</li>\n<li>Mavjud tizimning kamchiliklarini aniqlash.</li>\n<li>Talablar ro‘yxatini tuzish.</li></ul>\n<h4>Loyihalash</h4>\n<ul><li>Tizim tuzilmasi va qismlarini belgilash.</li>\n<li>Ma’lumotlar qayerda saqlanishi va ekran ko‘rinishini rejalashtirish.</li>\n<li>Kerakli resurslar va muddatni aniqlash.</li>\n<li>Sxema va chizmalar tayyorlash.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab uchun davomat tizimi yaratilmoqda. Avval o‘qituvchilarning ehtiyoji aniqlanadi (tahlil), so‘ng ma’lumotlar jadvali va ekran shakli chiziladi (loyihalash).</div>\n<p>Tahlil va loyihalash bosqichida jamoa a’zolari o‘zaro fikr almashadi, foydalanuvchilar bilan suhbatlashadi va qarorlarni yozib boradi. Bu bosqichda yo‘l qo‘yilgan xatoni tuzatish keyingi bosqichlarga qaraganda ancha arzon va oson bo‘ladi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Tahlil — nima kerakligini aniqlash.</li><li>Loyihalash — qanday qilishni rejalashtirish.</li></ul>","quiz":[{"q":"Tizim yaratishning birinchi bosqichi qaysi?","o":["Tahlil va loyihalash","Texnik xizmat","Hujjatlash faqat","Joriy qilish"],"a":0,"e":"Avval talablar aniqlanadi."},{"q":"Tahlil bosqichida nima qilinadi?","o":["Tizim sotiladi","Ekran bo‘yaladi","Muammo va foydalanuvchi talablari aniqlanadi","Dastur o‘chiriladi"],"a":2,"e":"Tahlil talablarni o‘rganadi."},{"q":"Loyihalash nima?","o":["Tayyor tizimni o‘chirish","Faylni nusxalash","Tizim tuzilmasini rejalashtirish","Virus qidirish"],"a":2,"e":"Reja asosida qurish."},{"q":"Qaysi amal tahlil bosqichiga kiradi?","o":["Foydalanuvchilar ehtiyojini o‘rganish","Xatoni tuzatish","Tizimni o‘chirish","Dasturni foydalanuvchiga topshirish"],"a":0,"e":"Ehtiyoj o‘rganiladi."},{"q":"Qaysi amal loyihalashga kiradi?","o":["Foydalanuvchini o‘qitish","Muammoni sezish","Ma’lumotlar jadvali va ekran shaklini chizish","Dastur sotish"],"a":2,"e":"Chizma tayyorlanadi."},{"q":"Yaxshi loyiha nimaga yordam beradi?","o":["Foydalanuvchini yo‘qotishga","Keyingi xatolarni kamaytirishga","Muddatni cho‘zishga","Xatolarni ko‘paytirishga"],"a":1,"e":"Reja aniq bo‘lsa, xato kam."},{"q":"Vaziyat: jamoa tizim ustida ish boshlamoqda. Nimani birinchi qilishi kerak?","o":["Darhol dasturni topshirish","Hujjat yozish ishini tugatish","Muammoni va talablarni aniqlash","Texnik xizmat ko‘rsatish"],"a":2,"e":"Tahlil birinchi."},{"q":"Talablar ro‘yxati nima?","o":["Foydalanuvchi parollari","Fayl kengaytmalari","Xatolar ro‘yxati","Tizim bajarishi kerak bo‘lgan vazifalar to‘plami"],"a":3,"e":"Tahlil natijasi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Tahlil keraksiz","Tahlilsiz loyihalash xatolarga olib kelishi mumkin","Loyihalash oxirida bajariladi","Foydalanuvchi fikri muhim emas"],"a":1,"e":"Talabni bilmay rejalab bo‘lmaydi."},{"q":"Sxema va chizmalar qaysi bosqichda tayyorlanadi?","o":["Texnik xizmatda","Joriy etishdan keyin","Loyihalashda","Hech qachon"],"a":2,"e":"Loyiha chizmalari reja qismi."}]},{"t":"23-dars. Ishlab chiqish, sinash va joriy qilish","lesson":"<p>Loyihalashdan keyin tizimni ishlab chiqish, sinash va joriy qilish bosqichlari keladi. Ishlab chiqishda loyiha asosida dastur yoziladi. Sinash vaqtida xatolar qidiriladi, joriy qilishda esa tayyor tizim foydalanuvchilarga topshiriladi.</p>\n<h4>Ishlab chiqish</h4>\n<ul><li>Dasturchi loyiha asosida kodni yozadi.</li>\n<li>Tizim qismlari alohida tayyorlanib, so‘ng birlashtiriladi.</li></ul>\n<h4>Sinash</h4>\n<ul><li>Dastur turli ma’lumotlar bilan tekshiriladi.</li>\n<li>Xatolar topilib, tuzatiladi.</li>\n<li>Talabga muvofiqligi baholanadi.</li></ul>\n<h4>Joriy qilish</h4>\n<ul><li>Tizim foydalanuvchi muhitiga o‘rnatiladi.</li>\n<li>Foydalanuvchilar o‘qitiladi.</li>\n<li>Eski tizimdan yangisiga o‘tish rejalashtiriladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Davomat dasturi avval bir sinfda sinaladi, topilgan xatolar tuzatiladi va keyin butun maktabda joriy etiladi.</div>\n<p>Katta tizimlarda ishlab chiqish va sinash ko‘pincha parallel olib boriladi: dasturchi bir qismni yozib bo‘lishi bilan sinovchi uni tekshiradi. Joriy qilishda esa foydalanuvchilarga yordam ko‘rsatish va ularning savollariga javob berish ham muhim.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Ishlab chiqish — yozish, sinash — tekshirish, joriy qilish — foydalanishga topshirish.</li><li>Sinov xatolarni foydalanuvchidan oldin topadi.</li></ul>","quiz":[{"q":"Ishlab chiqish bosqichida nima bajariladi?","o":["Hujjat yo‘q qilinadi","Muammo aniqlanadi faqat","Tizim o‘chiriladi","Dastur kodi yoziladi"],"a":3,"e":"Loyiha asosida yoziladi."},{"q":"Sinashning maqsadi nima?","o":["Kodni o‘chirish","Narxni oshirish","Xatolarni yashirish","Xatolarni topish va tuzatish"],"a":3,"e":"Sifat uchun."},{"q":"Joriy qilish nima?","o":["Muammoni aniqlash","Tizimni yo‘q qilish","Dasturni yozish boshlanishi","Tayyor tizimni foydalanishga topshirish"],"a":3,"e":"Foydalanuvchiga o‘rnatiladi."},{"q":"Bosqichlarning to‘g‘ri tartibi qaysi?","o":["Joriy qilish, ishlab chiqish, sinash","Sinash, joriy qilish, ishlab chiqish","Joriy qilish, sinash, ishlab chiqish","Ishlab chiqish, sinash, joriy qilish"],"a":3,"e":"Avval yoziladi, keyin sinaladi."},{"q":"Foydalanuvchilarni o‘qitish qaysi bosqichda?","o":["Sinashdan oldin","Kod yozishda","Joriy qilishda","Tahlilda"],"a":2,"e":"Ular tizimdan foydalanishni o‘rganadi."},{"q":"Dasturni turli ma’lumotlar bilan tekshirish nima deyiladi?","o":["Loyihalash","Arxivlash","Sinash","Joriy qilish"],"a":2,"e":"Ma’lumotlar bilan sinab ko‘riladi."},{"q":"Vaziyat: dastur sinovda xato berdi. Nima qilinadi?","o":["Xato topilib, tuzatiladi va qayta sinaladi","Foydalanuvchiga xatoli holda topshiriladi","Loyiha tashlanadi","Dastur yashiriladi"],"a":0,"e":"Tuzatib qayta tekshiriladi."},{"q":"Nima uchun avval kichik guruhda sinash foydali?","o":["Hujjat kerak emas","Narx tushadi","Xatolar katta zarar keltirmasdan topiladi","Dastur tezlashadi"],"a":2,"e":"Xavf kamayadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Sinov xatolarni foydalanuvchidan oldin topishga yordam beradi","Kod yozilmasa ham tizim tayyor","Joriy qilish sinashdan oldin bajariladi","Sinovdan o‘tmagan dastur har doim ishonchli"],"a":0,"e":"Sinash sifat kafolati."},{"q":"Eski tizimdan yangisiga o‘tishni qaysi bosqichda rejalashtirish mumkin?","o":["Tahlilda faqat","Hech qachon","Joriy qilishda","Ishlab chiqishda faqat"],"a":2,"e":"Joriy qilishda o‘tish bajariladi."}]},{"t":"24-dars. Hujjatlashtirish, baholash va texnik xizmat ko‘rsatish","lesson":"<p>Tizim joriy qilingandan keyin ham ish tugamaydi. Hujjatlashtirish, baholash va texnik xizmat ko‘rsatish bosqichlari tizimdan uzoq va to‘g‘ri foydalanishni ta’minlaydi.</p>\n<h4>Hujjatlashtirish</h4>\n<ul><li>Foydalanuvchi qo‘llanmasi: tizimdan qanday foydalanish tushuntiriladi.</li>\n<li>Texnik hujjat: tizim qanday tuzilgani yozib boriladi.</li></ul>\n<h4>Baholash</h4>\n<ul><li>Tizim maqsadga erishganini tekshirish.</li>\n<li>Tezlik, qulaylik va ishonchlilikni o‘rganish.</li>\n<li>Foydalanuvchilar fikrini so‘rash.</li></ul>\n<h4>Texnik xizmat ko‘rsatish</h4>\n<ul><li>Topilgan xatolarni tuzatish.</li>\n<li>Yangilash va yangi imkoniyatlar qo‘shish.</li>\n<li>Zaxira nusxa olish va xavfsizlikni kuzatish.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab davomat dasturiga foydalanuvchi qo‘llanmasi yoziladi, o‘qituvchilar fikri so‘raladi va talab bo‘yicha yangilanadi.</div>\n<p>Har bir tizimning umri cheklangan: vaqt o‘tishi bilan talablar o‘zgaradi, texnologiyalar yangilanadi. Shu sababli tizim sifatini muntazam baholab, kerak bo‘lsa yangilash yoki yangisi bilan almashtirish haqida qaror qabul qilinadi. Hujjatlar buni osonlashtiradi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Hujjat — tushuntirish, baholash — tekshirish, xizmat — qo‘llab-quvvatlash.</li><li>Tizimni muntazam yangilab borish kerak.</li></ul>","quiz":[{"q":"Hujjatlashtirishning maqsadi nima?","o":["Dasturni o‘chirish","Ekran bo‘yash","Xato yaratish","Tizimni tushuntiruvchi yozma materiallar tayyorlash"],"a":3,"e":"Qo‘llanma foydalanuvchiga yordam beradi."},{"q":"Foydalanuvchi qo‘llanmasida nima bo‘ladi?","o":["Xatolarni yashirish usuli","Faqat dastur kodi","Parollar ro‘yxati","Tizimdan foydalanish tartibi"],"a":3,"e":"Qanday ishlatish tushuntiriladi."},{"q":"Baholash nima?","o":["Tizimni yozish","Tizim maqsadga erishganini tekshirish","Kod nusxalash","Tizimni tashlash"],"a":1,"e":"Natija baholanadi."},{"q":"Quyidagilardan qaysi biri baholash mezoni?","o":["Klaviatura vazni","Devor qalinligi","Qulaylik va ishonchlilik","Stol rangi"],"a":2,"e":"Tizim sifati shu bilan baholanadi."},{"q":"Texnik xizmat ko‘rsatish nimani o‘z ichiga oladi?","o":["Tizimni yo‘q qilish","Muammoni aniqlash faqat","Xatolarni tuzatish va yangilash","Loyihani boshlash"],"a":2,"e":"Tizim qo‘llab-quvvatlanadi."},{"q":"Zaxira nusxa olishning ahamiyati nima?","o":["Tarmoqni tezlashtiradi","Ma’lumot yo‘qolsa tiklash imkonini beradi","Kodni qisqartiradi","Ekranni tozalaydi"],"a":1,"e":"Nusxadan tiklanadi."},{"q":"Vaziyat: foydalanuvchilar dasturda yangi imkoniyat kerakligini aytdi. Qaysi bosqich bajaradi?","o":["Birinchi loyihalash","Hech biri","Texnik xizmat ko‘rsatish (yangilash)","Tahlil faqat"],"a":2,"e":"Yangilash xizmatga kiradi."},{"q":"Texnik hujjat kimga ko‘proq kerak?","o":["Faqat mehmonlarga","Tizimni qo‘llab-quvvatlovchi mutaxassislarga","Tasodifiy kishilarga","Hech kimga"],"a":1,"e":"U ichki tuzilmani tushuntiradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Joriy qilingandan keyin ham tizimga xizmat ko‘rsatiladi","Baholash faqat boshida bajariladi","Joriy qilingach tizim hech qachon o‘zgarmaydi","Hujjatlashtirish keraksiz"],"a":0,"e":"Xizmat doimiy."},{"q":"Foydalanuvchilar fikrini so‘rash qaysi bosqichga mos?","o":["Faqat joriy qilishdan oldin","Hujjatni o‘chirish","Baholash","Kod yozish"],"a":2,"e":"Fikr baholashga yordam beradi."}]},{"t":"25-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 3</b> quyidagi darslarni qamrab oladi:</p><ul><li>Axborot texnologiyasi (AT) jihozlaridan uzoq muddat foydalanishning sog‘liqqa ta‘siri</li><li>Kommunikatsiya dasturlari qamrovi. Ma‘lumotlarni boshqarish dasturlari</li><li>O‘lchov dasturlari. Boshqaruv dasturlaridagi mikroprotsessorlar</li><li>Modellashtirish dasturlari. Boshqaruv, ta‘lim, sog‘liqni saqlash, savdo va autentifikatsiyada kompyuter tizimlari</li><li>Tahlil va loyihalash</li><li>Ishlab chiqish, sinash va joriy qilish</li><li>Hujjatlashtirish, baholash va texnik xizmat ko‘rsatish</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"To‘g‘ri mulohazani tanlang.","o":["Mikroprotsessor faqat o‘yinda ishlaydi","O‘lchov dasturi qurilmani sotadi","Datchik hech qachon dasturga ulanmaydi","Boshqaruv dasturi datchik ma’lumotidan foydalanishi mumkin"],"a":3,"e":"Datchik va dastur birga ishlaydi."},{"q":"Quyidagilardan qaysi biri ma’lumot bilan ishlash amali?","o":["Printerni tozalash","Kabel tortish","Ekranni yoritish","Saralash"],"a":3,"e":"Saralash tartiblaydi."},{"q":"Termostat misolida qaror qanday qabul qilinadi?","o":["Tasodifiy tanlab","Faqat vaqtga qarab","O‘lchangan haroratni belgilangan qiymat bilan solishtirib","Hech narsaga qaramay"],"a":2,"e":"Solishtirish asosida isitgich yoqiladi."},{"q":"Vaziyat: dastur sinovda xato berdi. Nima qilinadi?","o":["Xato topilib, tuzatiladi va qayta sinaladi","Foydalanuvchiga xatoli holda topshiriladi","Loyiha tashlanadi","Dastur yashiriladi"],"a":0,"e":"Tuzatib qayta tekshiriladi."},{"q":"Quyidagilardan qaysi biri baholash mezoni?","o":["Klaviatura vazni","Devor qalinligi","Qulaylik va ishonchlilik","Stol rangi"],"a":2,"e":"Tizim sifati shu bilan baholanadi."},{"q":"Zaxira nusxa olishning ahamiyati nima?","o":["Tarmoqni tezlashtiradi","Ma’lumot yo‘qolsa tiklash imkonini beradi","Kodni qisqartiradi","Ekranni tozalaydi"],"a":1,"e":"Nusxadan tiklanadi."},{"q":"Uchish simulyatori qaysi tushunchaga misol?","o":["Modellashtirish","Arxivlash","Autentifikatsiya","Formatlash"],"a":0,"e":"Real uchishni modellaydi."},{"q":"Ishlab chiqish bosqichida nima bajariladi?","o":["Hujjat yo‘q qilinadi","Muammo aniqlanadi faqat","Tizim o‘chiriladi","Dastur kodi yoziladi"],"a":3,"e":"Loyiha asosida yoziladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Tahlil keraksiz","Tahlilsiz loyihalash xatolarga olib kelishi mumkin","Loyihalash oxirida bajariladi","Foydalanuvchi fikri muhim emas"],"a":1,"e":"Talabni bilmay rejalab bo‘lmaydi."},{"q":"Qaysi o‘tirish usuli to‘g‘ri?","o":["Divanda qiyshayib","Orqa tayanchga tiralgan, tik holatda","Stulda yarim yotib","Oyoqni osiltirib doim"],"a":1,"e":"To‘g‘ri qomat bel og‘rig‘ini oldini oladi."},{"q":"Vaziyat: o‘quvchi uch soat tanaffussiz kompyuterda o‘tirdi, ko‘zi og‘riyapti. Nima qilishi kerak?","o":["Yana uzoq o‘tirishi","Tanaffus qilib, ko‘z mashqlarini bajarishi","Ekranga yanada yaqin o‘tirishi","Yorqinlikni maksimalga qo‘yishi"],"a":1,"e":"Ko‘zga dam kerak."},{"q":"Loyihalash nima?","o":["Tayyor tizimni o‘chirish","Faylni nusxalash","Tizim tuzilmasini rejalashtirish","Virus qidirish"],"a":2,"e":"Reja asosida qurish."},{"q":"Sog‘liqni saqlashda kompyuter tizimi nima uchun qo‘llanadi?","o":["Bemor ma’lumotlarini saqlash va tibbiy uskunalarni boshqarish","Faqat o‘yin uchun","Rasm bo‘yash uchun","Musiqa tinglash uchun"],"a":0,"e":"Elektron karta ma’lumotni saqlaydi."},{"q":"Hujjatlashtirishning maqsadi nima?","o":["Dasturni o‘chirish","Ekran bo‘yash","Xato yaratish","Tizimni tushuntiruvchi yozma materiallar tayyorlash"],"a":3,"e":"Qo‘llanma foydalanuvchiga yordam beradi."},{"q":"Quyidagilardan qaysi biri o‘lchanadigan kattalik?","o":["Harorat","Klaviatura rangi","Ekran logotipi","Fayl nomi"],"a":0,"e":"Harorat datchik bilan o‘lchanadi."},{"q":"Dasturni turli ma’lumotlar bilan tekshirish nima deyiladi?","o":["Loyihalash","Arxivlash","Sinash","Joriy qilish"],"a":2,"e":"Ma’lumotlar bilan sinab ko‘riladi."},{"q":"Qaysi amal tahlil bosqichiga kiradi?","o":["Foydalanuvchilar ehtiyojini o‘rganish","Xatoni tuzatish","Tizimni o‘chirish","Dasturni foydalanuvchiga topshirish"],"a":0,"e":"Ehtiyoj o‘rganiladi."},{"q":"Filtrlash nima?","o":["Ekranni yopish","Barcha ma’lumotni o‘chirish","Shartga mos ma’lumotlarni ajratib ko‘rsatish","Ma’lumotni shifrlash"],"a":2,"e":"Shartga javob berganlari ko‘rsatiladi."},{"q":"Ma’lumotlarni boshqarish dasturlari nima qiladi?","o":["Ekranni o‘chirish","Ma’lumotni saqlash, qidirish va tartiblash","Faqat musiqa chalish","Faqat chop etish"],"a":1,"e":"Axborotni tartibli boshqaradi."},{"q":"Ish xonasiga qanday talab qo‘yiladi?","o":["Qorong‘i va yopiq bo‘lishi","Yaxshi yoritilgan va shamollatilgan bo‘lishi","Nam bo‘lishi","Juda shovqinli bo‘lishi"],"a":1,"e":"Yorug‘lik ko‘zni asraydi."}]},{"t":"26-dars. Xavfsizlik muammolari. Elektron xavfsizlik. Ma‘lumotlar xavfsizligi","lesson":"<p>Kompyuter va tarmoqlardan foydalanishda xavfsizlik muhim masala. Elektron xavfsizlik qurilmalarni, dasturlarni va ma’lumotlarni ruxsatsiz kirish, o‘g‘irlash, buzish va yo‘qolishdan himoya qilishni anglatadi. Bugun ko‘plab shaxsiy va tashkilot ma’lumotlari elektron shaklda saqlanadi, shuning uchun ularni asrash zarur.</p>\n<h4>Xavfsizlik muammolari</h4>\n<ul><li>Viruslar va zararli dasturlar.</li>\n<li>Ruxsatsiz kirish va parolning o‘g‘irlanishi.</li>\n<li>Firibgarlik (fishing) xabarlari.</li>\n<li>Ma’lumotning tasodifan o‘chib ketishi yoki qurilma buzilishi.</li></ul>\n<h4>Ma’lumotlar xavfsizligi choralari</h4>\n<ul><li>Kuchli parol ishlatish: harf, raqam va belgilar aralashmasi.</li>\n<li>Muntazam zaxira nusxa olish.</li>\n<li>Antivirusni yangilab turish.</li>\n<li>Notanish havola va fayllarni ochmaslik.</li>\n<li>Shaxsiy ma’lumotni begonalarga bermaslik.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Noma’lum yuboruvchidan kelgan xatda “yutuq oldingiz” deb havola berilgan. Havolani ochmang va parolingizni kiritmang — bu fishing bo‘lishi mumkin.</div>\n<p>Xavfsizlik faqat dasturlarga emas, foydalanuvchining o‘ziga ham bog‘liq: ehtiyotkor bo‘lish va qoidalarga rioya qilish ko‘p xatarning oldini oladi. Umumiy kompyuterda ishlagach, hisobingizdan albatta chiqib keting.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Elektron xavfsizlik qurilma va ma’lumotni himoya qiladi.</li><li>Kuchli parol va zaxira nusxa asosiy choralar.</li></ul>","quiz":[{"q":"Elektron xavfsizlik nima?","o":["Qurilma va ma’lumotni ruxsatsiz kirish va zarardan himoya qilish","Fayllarni ko‘paytirish","Faqat kompyuterni tozalash","Ekranni yorqinlashtirish"],"a":0,"e":"U himoyaga qaratilgan."},{"q":"Qaysi parol kuchliroq?","o":["Ismingiz","Harf, raqam va belgilar aralash uzun parol","12345","Tug‘ilgan yilingiz"],"a":1,"e":"Murakkab parolni topish qiyin."},{"q":"Fishing nima?","o":["Antivirus turi","Parol va ma’lumotni aldab olishga qaratilgan soxta xabar","Fayl formati","Tarmoq kabeli"],"a":1,"e":"Firibgarlik usuli."},{"q":"Zaxira nusxa olishning maqsadi nima?","o":["Ma’lumot yo‘qolsa tiklash","Faylni o‘chirish","Internetni tezlashtirish","Ekranni tozalash"],"a":0,"e":"Nusxadan tiklash mumkin."},{"q":"Notanish havola kelsa, nima qilish to‘g‘ri?","o":["Antivirusni o‘chirish","Ochmaslik","Darhol ochib parol kiritish","Hammaga yuborish"],"a":1,"e":"Havola zararli bo‘lishi mumkin."},{"q":"Quyidagilardan qaysi biri xavfsizlik tahdidi?","o":["Yangi klaviatura","Zararli dastur","Yorug‘ xona","Toza ekran"],"a":1,"e":"Virus ma’lumotga zarar beradi."},{"q":"Vaziyat: do‘stingiz parolni so‘radi. Eng to‘g‘ri harakat qaysi?","o":["Parolni hammaga aytish","Barcha saytlarda bir xil parol qo‘yish","Parolni xatda yuborish","Parolni hech kimga bermaslik"],"a":3,"e":"Parol maxfiy saqlanadi."},{"q":"Bir xil parolni barcha saytlarda ishlatish nima uchun xavfli?","o":["Parol eskirib ketadi","Bittasi buzilsa, boshqalari ham ochilib qoladi","Antivirus ishlamaydi","Internet sekinlashadi"],"a":1,"e":"Zanjir ta’siri xavf."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Viruslar faqat televizorda bo‘ladi","Antivirusni muntazam yangilash kerak","Antivirus bir marta o‘rnatilsa yetadi","Yangilash tizimni buzadi"],"a":1,"e":"Yangi viruslarga qarshi bazalar yangilanadi."},{"q":"Ma’lumot tasodifan o‘chib ketishiga qarshi qaysi chora yordam beradi?","o":["Muntazam zaxira nusxa olish","Parolni oddiy qilish","Antivirusni olib tashlash","Faylni nomsiz qoldirish"],"a":0,"e":"Zaxira nusxa saqlaydi."}]},{"t":"27-dars. Axborot himoyasi protokoli. Antiviruslar va fayervol","lesson":"<p>Axborot himoyasi bir necha vosita va qoidalarga tayanadi. Himoya protokollari tarmoqda ma’lumot xavfsiz uzatilishini ta’minlaydi. Antiviruslar zararli dasturlarni topib, yo‘q qiladi, fayervol esa tarmoq trafigini nazorat qiladi.</p>\n<h4>Himoya protokollari</h4>\n<ul><li>Protokol — ma’lumot almashish qoidalari to‘plami.</li>\n<li>HTTPS ma’lumotni shifrlab uzatadi, shuning uchun parol va to‘lov ma’lumotlari himoyalanadi.</li>\n<li>Shifrlash ma’lumotni faqat kaliti borlar o‘qiy oladigan ko‘rinishga keltiradi.</li></ul>\n<h4>Antiviruslar</h4>\n<ul><li>Fayl va dasturlarni zararli kodga tekshiradi.</li>\n<li>Topilgan virusni davolaydi, karantinga oladi yoki o‘chiradi.</li>\n<li>Virus bazasi muntazam yangilanishi kerak.</li></ul>\n<h4>Fayervol (brandmauer)</h4>\n<ul><li>Kiruvchi va chiquvchi tarmoq ulanishlarini belgilangan qoidalar bo‘yicha filtrlaydi.</li>\n<li>Ruxsatsiz ulanishlarning oldini oladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Internet-do‘konda to‘lov qilayotganda manzil HTTPS bilan boshlanishiga e’tibor bering. Bu ulanish shifrlanganini bildiradi.</div>\n<p>Himoya vositalari birgalikda eng yaxshi natija beradi: antivirus, fayervol va to‘g‘ri sozlangan parollar bir-birini to‘ldiradi. Operatsion tizim va dasturlarni yangilab turish ham xavfsizlik kamchiliklarini bartaraf etadi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Antivirus virusni topadi, fayervol tarmoq ulanishini nazorat qiladi.</li><li>HTTPS xavfsizroq, chunki ma’lumotni shifrlaydi.</li></ul>","quiz":[{"q":"Fayervolning vazifasi nima?","o":["Tarmoq ulanishlarini qoidalar asosida nazorat qilish","Rasm tahrirlash","Hujjat bosib chiqarish","Fayl arxivlash"],"a":0,"e":"U trafikni filtrlaydi."},{"q":"Antivirus nima qiladi?","o":["Internet kabelini tortadi","Matn yozadi","Ekranni bo‘yaydi","Zararli dasturlarni topib, yo‘q qiladi"],"a":3,"e":"Himoya dasturi."},{"q":"HTTPS ning HTTP dan afzalligi nima?","o":["Tezroq chop etishi","Faylni arxivlashi","Ma’lumotni shifrlab uzatishi","Rasmlarni kattalashtirishi"],"a":2,"e":"Shifrlash xavfsizlik beradi."},{"q":"Shifrlash nima?","o":["Faylni nomlash","Ma’lumotni nusxalash","Ma’lumotni o‘chirish","Ma’lumotni faqat kaliti borlar o‘qiy oladigan ko‘rinishga keltirish"],"a":3,"e":"Maxfiylikni ta’minlaydi."},{"q":"Antivirus bazasini yangilash nima uchun kerak?","o":["Fayl nomini o‘zgartirish uchun","Tarmoq tezligini oshirish uchun","Yangi viruslarni ham aniqlash uchun","Ekran rangini o‘zgartirish uchun"],"a":2,"e":"Yangi tahdidlar paydo bo‘ladi."},{"q":"Protokol nima?","o":["Virus turi","Ma’lumot almashish qoidalari to‘plami","Xotira qurilmasi","Dasturlash muhiti"],"a":1,"e":"Qurilmalar kelishuvi."},{"q":"Vaziyat: sayt manzili HTTPS bilan boshlanmaydi, uni orqali bank kartasi kiritish so‘ralmoqda. Nima qilish kerak?","o":["Antivirusni o‘chirish","Karta raqamini kiritish","Ma’lumot kiritishdan saqlanish","Parolni ham yozish"],"a":2,"e":"Himoyasiz ulanish xavfli."},{"q":"Virus topilsa, antivirus nima qilishi mumkin?","o":["Davolash, karantinga olish yoki o‘chirish","Tarmoqni ochish","Faylni ko‘paytirish","Virusni tarqatish"],"a":0,"e":"Himoya vazifasi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Fayervol faqat musiqa uchun","Fayervol viruslarni yaratadi","Fayervol parolni o‘chiradi","Fayervol ruxsatsiz kirish xavfini kamaytiradi"],"a":3,"e":"Nazorat qiladi."},{"q":"Karantin nima?","o":["Faylni tezlashtirish","Shubhali faylni ajratib, zarar keltirmaydigan joyda saqlash","Faylni nusxalash","Faylni ochish"],"a":1,"e":"Fayl alohida saqlanadi."}]},{"t":"28-dars. Auditoriyani huquqiy, ma‘naviy, axloqiy va madaniy jihatdan baho berish","lesson":"<p>Axborot texnologiyalaridan foydalanishda auditoriya, ya’ni mahsulot yoki ma’lumot mo‘ljallangan kishilar doirasini hisobga olish kerak. Bunda ma’lumotning huquqiy, ma’naviy, axloqiy va madaniy jihatlari baholanadi.</p>\n<h4>Baholash jihatlari</h4>\n<ul><li>Huquqiy: qonunlarga, mualliflik huquqiga va shaxsiy ma’lumotlar himoyasiga mos kelishi.</li>\n<li>Ma’naviy: ma’naviy qadriyatlarga zid bo‘lmasligi.</li>\n<li>Axloqiy: kimgadir zarar yetkazmasligi, haqoratlamasligi, yolg‘on tarqatmasligi.</li>\n<li>Madaniy: milliy va madaniy an’analarga, tilga hurmat.</li></ul>\n<h4>Amalda</h4>\n<ul><li>Material yoshga mosmi, tushunarlimi — tekshiring.</li>\n<li>Boshqalar fikriga hurmat bilan yondashing.</li>\n<li>Shubhali yoki zararli kontentni tarqatmang.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab uchun taqdimot tayyorlayotib, boshqa muallif rasmini manba ko‘rsatmay olish huquqiy va axloqiy jihatdan noto‘g‘ri bo‘ladi.</div>\n<p>Internetda tarqatilgan axborot juda tez ko‘p kishiga yetib boradi. Shu sababli har bir foydalanuvchi nimani yozayotgani, qaysi rasm yoki videoni ulashayotgani uchun mas’uliyatli bo‘lishi kerak. Ishonchsiz xabarni tarqatishdan oldin manbasini tekshirib ko‘ring.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Auditoriyaga mos va hurmatli axborot tayyorlang.</li><li>Qonun va axloq me’yorlariga rioya qiling.</li></ul>","quiz":[{"q":"Auditoriya nima?","o":["Axborot mo‘ljallangan kishilar doirasi","Dastur turi","Fayl formati","Xotira hajmi"],"a":0,"e":"Kimlar uchun ekani."},{"q":"Huquqiy jihat nimani tekshiradi?","o":["Rangning chiroyini","Tezlikni","Fayl hajmini","Qonunlarga mosligini"],"a":3,"e":"Qonuniylik."},{"q":"Axloqiy jihatga qaysi misol mos keladi?","o":["Printer tanlash","Boshqalarni haqorat qilmaslik","Fayl nomini o‘zgartirish","Ekran o‘lchami"],"a":1,"e":"Hurmat axloqqa kiradi."},{"q":"Madaniy jihat nimani anglatadi?","o":["Dasturlash tilini tanlash","Milliy va madaniy qadriyatlarga hurmat","Kabel uzunligi","Tarmoq tezligi"],"a":1,"e":"Madaniyat hurmat qilinadi."},{"q":"Manba ko‘rsatmay boshqa kishi rasmini olish qaysi jihatdan noto‘g‘ri?","o":["Huquqiy va axloqiy","Faqat texnik","Hech qaysi","Faqat rangli"],"a":0,"e":"Mualliflik huquqiga zid."},{"q":"Vaziyat: kichik sinf o‘quvchilariga murakkab ilmiy atamalar to‘la material tayyorlandi. Bu nimani buzadi?","o":["Fayl formatini","Auditoriyaga mosligini","Printerni","Monitorni"],"a":1,"e":"Material yoshga mos emas."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Yolg‘on xabar zararsiz","Qonun internetda amal qilmaydi","Hamma narsani tekshirmay tarqatish mumkin","Axborot tarqatishdan oldin uning zararsizligini tekshirish kerak"],"a":3,"e":"Mas’uliyat zarur."},{"q":"Yolg‘on xabar tarqatish nimaga kiradi?","o":["Odatiy fayl nusxalash","Maqtovga loyiq ish","Antivirus ishlashi","Axloqsiz va zararli xatti-harakat"],"a":3,"e":"Odamlarni chalg‘itadi."},{"q":"Qaysi biri ma’naviy jihatni baholashga misol?","o":["Rasm piksellarini sanash","Klaviaturani almashtirish","Material qadriyatlarga zid emasligini tekshirish","Fayl hajmini o‘lchash"],"a":2,"e":"Ma’naviyatga mosligi."},{"q":"Materialni yoshga mosligini baholash nima uchun kerak?","o":["Dastur tezligini oshirish uchun","O‘quvchiga tushunarli va zararsiz bo‘lishi uchun","Faylni kichraytirish uchun","Parol uchun"],"a":1,"e":"Auditoriyaga moslik."}]},{"t":"29-dars. Mualliflik huquqi va uning turlari. Mualliflik huquqi himoyasi","lesson":"<p>Mualliflik huquqi — ijodiy asar muallifining o‘z asariga bo‘lgan huquqlari. Asarlarga kitob, musiqa, rasm, fotosurat, film va kompyuter dasturlari kiradi. Muallif asarni kim foydalanishi, nusxalashi va tarqatishi mumkinligini hal qiladi.</p>\n<h4>Mualliflik huquqi turlari</h4>\n<ul><li>Shaxsiy nomulkiy huquqlar: muallif deb tan olinish, nomini ko‘rsatish.</li>\n<li>Mulkiy huquqlar: asardan foydalanish va undan daromad olish.</li>\n<li>Mulkiy huquqlar muallifga yoki u ruxsat bergan shaxsga tegishli.</li></ul>\n<h4>Himoya qilish</h4>\n<ul><li>Ruxsatsiz nusxalash va tarqatish — huquqbuzarlik (piratlik).</li>\n<li>Asarni ishlatganda muallif va manbani ko‘rsatish.</li>\n<li>Litsenziyali dasturlardan foydalanish.</li>\n<li>Ba’zi asarlar ochiq litsenziya bilan erkin tarqatiladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Referatga internetdagi maqolani o‘zgartirmay ko‘chirib, o‘zingiznikidek ko‘rsatish plagiat hisoblanadi. To‘g‘risi — manbani ko‘rsatish.</div>\n<p>Mualliflik huquqi muallifni rag‘batlantiradi va ijodni qo‘llab-quvvatlaydi. Dasturlarning litsenziyasi, kitob va musiqaning nusxasini qonuniy yo‘l bilan olish muallifga hurmat belgisidir. Foydalanishdan oldin asar shartlarini o‘qib chiqish foydali.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Muallif huquqlari qonun bilan himoyalanadi.</li><li>Piratlik va plagiatdan saqlaning, manbani ko‘rsating.</li></ul>","quiz":[{"q":"Mualliflik huquqi nima?","o":["Muallifning o‘z asariga bo‘lgan huquqlari","Dastur tezligi","Fayl kengaytmasi","Tarmoq protokoli"],"a":0,"e":"Muallif huquqi."},{"q":"Quyidagilardan qaysi biri mualliflik huquqi obyekti?","o":["Musiqa asari","Toza havo","Elektr rozetka","Stul"],"a":0,"e":"Ijodiy asarlar."},{"q":"Piratlik nima?","o":["Muallifga to‘lov","Asarni ruxsatsiz nusxalash va tarqatish","Qonuniy sotib olish","Litsenziya olish"],"a":1,"e":"Huquqbuzarlik."},{"q":"Plagiat nima?","o":["Faylni arxivlash","Asar yaratish","Boshqa muallif asarini o‘zinikidek ko‘rsatish","Manba ko‘rsatib iqtibos keltirish"],"a":2,"e":"Mualliflikni o‘zlashtirish."},{"q":"Mulkiy huquqlar nimani beradi?","o":["Printer tanlashni","Faylni o‘chirishni","Faqat nom berishni","Asardan foydalanish va daromad olish imkonini"],"a":3,"e":"Moddiy jihat."},{"q":"Vaziyat: o‘quvchi referatda boshqa muallif fikrini ishlatmoqchi. Qanday to‘g‘ri?","o":["Muallif nomini o‘chirish","Ruxsatsiz sotish","Manbani ko‘rsatish","Ko‘chirib, o‘zinikidek yozish"],"a":2,"e":"Iqtibosda manba aytiladi."},{"q":"Litsenziyali dasturdan foydalanish nimani anglatadi?","o":["Parolni buzib ishlatish","Dasturni nusxalab sotish","Dasturni yashirish","Dastur muallifi bergan huquq asosida ishlatish"],"a":3,"e":"Qonuniy foydalanish."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Mualliflik huquqi faqat kitobga tegishli","Piratlik ruxsat etilgan","Internetdagi hamma narsa erkin ko‘chiriladi","Ruxsatsiz nusxalash qonunbuzarlik hisoblanadi"],"a":3,"e":"Qonun himoya qiladi."},{"q":"Shaxsiy nomulkiy huquqqa nima kiradi?","o":["Daromad olish","Sotib yuborish","Muallif deb tan olinish","Nusxa sotish"],"a":2,"e":"Muallifning nomi."},{"q":"Ochiq litsenziya nima?","o":["Dasturni o‘chirish","Foydalanishni taqiqlash","Asardan belgilangan shartlarda erkin foydalanishga ruxsat","Faylni shifrlash"],"a":2,"e":"Muallif ruxsati."}]},{"t":"30-dars. AKT foydalanuvchisi bilan elektron xat orqali muloqot qilish. Spam tushunchasi","lesson":"<p>Elektron xat orqali muloqot zamonaviy aloqaning asosiy shakllaridan biri. Xat yozishda odob qoidalariga rioya qilish va foydalanuvchi bilan aniq, hurmatli muloqot qilish kerak. Shuningdek, keraksiz xatlar — spamdan ehtiyot bo‘lish muhim.</p>\n<h4>Elektron xat yozish qoidalari</h4>\n<ul><li>Mavzu (subject) maydoniga xat mazmunini qisqa yozing.</li>\n<li>Murojaat va xayrlashuv so‘zlarini unutmang.</li>\n<li>Qisqa, aniq va xatosiz yozing.</li>\n<li>Fayl biriktirganingizni tekshiring.</li>\n<li>Yuborishdan oldin xatni qayta o‘qing.</li></ul>\n<h4>Spam</h4>\n<ul><li>Spam — so‘ralmagan, ommaviy tarqatiladigan keraksiz xatlar.</li>\n<li>Ko‘pincha reklama yoki firibgarlik maqsadida yuboriladi.</li>\n<li>Spamga javob bermang, havolalarini ochmang.</li>\n<li>Pochta xizmatidagi spam filtri va “spam deb belgilash” imkoniyatidan foydalaning.</li></ul>\n<div class=\"ex\"><b>Misol.</b> “Siz million yutdingiz, bu havolaga o‘ting” degan notanish xat — odatda spam yoki firibgarlik. Uni ochmasdan o‘chiring.</div>\n<p>Elektron xatda shaxsiy ma’lumotlarni, masalan, parol yoki karta raqamini yozish xavfsiz emas. Rasmiy xatlarda ismingiz va aloqa ma’lumotlaringizni ko‘rsating, lekin begona kishiga maxfiy ma’lumot yubormang.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Xatda mavzu va odob muhim.</li><li>Spamga javob bermang va havolalarni ochmang.</li></ul>","quiz":[{"q":"Spam nima?","o":["So‘ralmagan keraksiz ommaviy xat","Parol","Muhim hujjat","Antivirus"],"a":0,"e":"Keraksiz xat."},{"q":"Elektron xatda mavzu maydoni nima uchun kerak?","o":["Rasm joylashtirish uchun","Parol yozish uchun","Xat mazmunini qisqa bildirish uchun","Faylni arxivlash uchun"],"a":2,"e":"Qabul qiluvchi mazmunni ko‘radi."},{"q":"Spam xatga nima qilish kerak?","o":["Ma’lumotlarini kiritish","Ochmay, spam deb belgilash yoki o‘chirish","Boshqalarga yuborish","Havolasini ochish"],"a":1,"e":"Xavfsizlik uchun."},{"q":"Elektron xat yozishda qaysi qoida to‘g‘ri?","o":["Faqat katta harflarda yozish","Mavzusiz yuborish","Hurmatli murojaat va aniq mazmun","Ko‘p emoji bilan to‘ldirish"],"a":2,"e":"Odob qoidasi."},{"q":"Fayl biriktirish nima uchun tekshiriladi?","o":["Xat tezlashishi uchun","Qabul qiluvchi kerakli faylni olishi uchun","Parol uchun","Spam uchun"],"a":1,"e":"Biriktirmay yuborish xatosi."},{"q":"Quyidagilardan qaysi biri spam belgisi?","o":["Do‘stingizning darsga oid xati","Notanish manbadan keluvchi “yutuq” haqida xabar","O‘qituvchi topshirig‘i","Ma’lum kontaktdan salom xati"],"a":1,"e":"Yutuq vasvasasi."},{"q":"Vaziyat: noma’lum manzildan “parolingizni yangilang” degan havola keldi. Nima qilasiz?","o":["Xatga javob yozasiz","Havolani ochmay, rasmiy saytga o‘zingiz kirasiz","Havolani ochib parol kiritasiz","Do‘stlarga yuborasiz"],"a":1,"e":"Fishing bo‘lishi mumkin."},{"q":"Spam filtrining vazifasi nima?","o":["Rasm chizish","Keraksiz xatlarni ajratish","Faylni o‘chirish","Xat yozish"],"a":1,"e":"Avtomatik ajratadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Mavzu kerak emas","Xatni o‘qimay yuborish yaxshi","Xatoli yozish odob","Yuborishdan oldin xatni qayta o‘qib chiqish foydali"],"a":3,"e":"Xatolar oldi olinadi."},{"q":"Spamga javob yozish nima uchun noto‘g‘ri?","o":["Xat yo‘qolib qoladi","Manzilingiz faol ekani tasdiqlanib, ko‘proq spam kelishi mumkin","Fayl hajmi ortadi","Internet o‘chadi"],"a":1,"e":"Aloqa qilish xavfli."}]},{"t":"31-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 4</b> quyidagi darslarni qamrab oladi:</p><ul><li>Xavfsizlik muammolari. Elektron xavfsizlik. Ma‘lumotlar xavfsizligi</li><li>Axborot himoyasi protokoli. Antiviruslar va fayervol</li><li>Auditoriyani huquqiy, ma‘naviy, axloqiy va madaniy jihatdan baho berish</li><li>Mualliflik huquqi va uning turlari. Mualliflik huquqi himoyasi</li><li>AKT foydalanuvchisi bilan elektron xat orqali muloqot qilish. Spam tushunchasi</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Vaziyat: o‘quvchi referatda boshqa muallif fikrini ishlatmoqchi. Qanday to‘g‘ri?","o":["Muallif nomini o‘chirish","Ruxsatsiz sotish","Manbani ko‘rsatish","Ko‘chirib, o‘zinikidek yozish"],"a":2,"e":"Iqtibosda manba aytiladi."},{"q":"Vaziyat: sayt manzili HTTPS bilan boshlanmaydi, uni orqali bank kartasi kiritish so‘ralmoqda. Nima qilish kerak?","o":["Antivirusni o‘chirish","Karta raqamini kiritish","Ma’lumot kiritishdan saqlanish","Parolni ham yozish"],"a":2,"e":"Himoyasiz ulanish xavfli."},{"q":"Qaysi parol kuchliroq?","o":["Ismingiz","Harf, raqam va belgilar aralash uzun parol","12345","Tug‘ilgan yilingiz"],"a":1,"e":"Murakkab parolni topish qiyin."},{"q":"Fayl biriktirish nima uchun tekshiriladi?","o":["Xat tezlashishi uchun","Qabul qiluvchi kerakli faylni olishi uchun","Parol uchun","Spam uchun"],"a":1,"e":"Biriktirmay yuborish xatosi."},{"q":"Bir xil parolni barcha saytlarda ishlatish nima uchun xavfli?","o":["Parol eskirib ketadi","Bittasi buzilsa, boshqalari ham ochilib qoladi","Antivirus ishlamaydi","Internet sekinlashadi"],"a":1,"e":"Zanjir ta’siri xavf."},{"q":"Elektron xat yozishda qaysi qoida to‘g‘ri?","o":["Faqat katta harflarda yozish","Mavzusiz yuborish","Hurmatli murojaat va aniq mazmun","Ko‘p emoji bilan to‘ldirish"],"a":2,"e":"Odob qoidasi."},{"q":"Qaysi biri ma’naviy jihatni baholashga misol?","o":["Rasm piksellarini sanash","Klaviaturani almashtirish","Material qadriyatlarga zid emasligini tekshirish","Fayl hajmini o‘lchash"],"a":2,"e":"Ma’naviyatga mosligi."},{"q":"Mulkiy huquqlar nimani beradi?","o":["Printer tanlashni","Faylni o‘chirishni","Faqat nom berishni","Asardan foydalanish va daromad olish imkonini"],"a":3,"e":"Moddiy jihat."},{"q":"Yolg‘on xabar tarqatish nimaga kiradi?","o":["Odatiy fayl nusxalash","Maqtovga loyiq ish","Antivirus ishlashi","Axloqsiz va zararli xatti-harakat"],"a":3,"e":"Odamlarni chalg‘itadi."},{"q":"Materialni yoshga mosligini baholash nima uchun kerak?","o":["Dastur tezligini oshirish uchun","O‘quvchiga tushunarli va zararsiz bo‘lishi uchun","Faylni kichraytirish uchun","Parol uchun"],"a":1,"e":"Auditoriyaga moslik."},{"q":"Antivirus nima qiladi?","o":["Internet kabelini tortadi","Matn yozadi","Ekranni bo‘yaydi","Zararli dasturlarni topib, yo‘q qiladi"],"a":3,"e":"Himoya dasturi."},{"q":"Notanish havola kelsa, nima qilish to‘g‘ri?","o":["Antivirusni o‘chirish","Ochmaslik","Darhol ochib parol kiritish","Hammaga yuborish"],"a":1,"e":"Havola zararli bo‘lishi mumkin."},{"q":"Karantin nima?","o":["Faylni tezlashtirish","Shubhali faylni ajratib, zarar keltirmaydigan joyda saqlash","Faylni nusxalash","Faylni ochish"],"a":1,"e":"Fayl alohida saqlanadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Mualliflik huquqi faqat kitobga tegishli","Piratlik ruxsat etilgan","Internetdagi hamma narsa erkin ko‘chiriladi","Ruxsatsiz nusxalash qonunbuzarlik hisoblanadi"],"a":3,"e":"Qonun himoya qiladi."},{"q":"Protokol nima?","o":["Virus turi","Ma’lumot almashish qoidalari to‘plami","Xotira qurilmasi","Dasturlash muhiti"],"a":1,"e":"Qurilmalar kelishuvi."},{"q":"Spam filtrining vazifasi nima?","o":["Rasm chizish","Keraksiz xatlarni ajratish","Faylni o‘chirish","Xat yozish"],"a":1,"e":"Avtomatik ajratadi."},{"q":"Vaziyat: noma’lum manzildan “parolingizni yangilang” degan havola keldi. Nima qilasiz?","o":["Xatga javob yozasiz","Havolani ochmay, rasmiy saytga o‘zingiz kirasiz","Havolani ochib parol kiritasiz","Do‘stlarga yuborasiz"],"a":1,"e":"Fishing bo‘lishi mumkin."},{"q":"Elektron xavfsizlik nima?","o":["Qurilma va ma’lumotni ruxsatsiz kirish va zarardan himoya qilish","Fayllarni ko‘paytirish","Faqat kompyuterni tozalash","Ekranni yorqinlashtirish"],"a":0,"e":"U himoyaga qaratilgan."},{"q":"Madaniy jihat nimani anglatadi?","o":["Dasturlash tilini tanlash","Milliy va madaniy qadriyatlarga hurmat","Kabel uzunligi","Tarmoq tezligi"],"a":1,"e":"Madaniyat hurmat qilinadi."},{"q":"Piratlik nima?","o":["Muallifga to‘lov","Asarni ruxsatsiz nusxalash va tarqatish","Qonuniy sotib olish","Litsenziya olish"],"a":1,"e":"Huquqbuzarlik."}]},{"t":"32-dars. Internetdan samarali foydalanish. Internetdan topilgan axborotning ishonchliligini baholash","lesson":"<p>Internet — axborotning ulkan manbai, lekin undagi ma’lumotning hammasi ham to‘g‘ri emas. Samarali foydalanish uchun kerakli ma’lumotni tez topish va uning ishonchliligini baholash kerak. Bu ayniqsa o‘qish va tadqiqot ishlarida zarur, chunki noto‘g‘ri manba xato xulosaga olib keladi.</p>\n<h4>Samarali qidirish</h4>\n<ul><li>Aniq kalit so‘zlardan foydalaning.</li>\n<li>Qidiruv tizimida tirnoq yoki qo‘shimcha so‘zlar bilan natijani toraytiring.</li>\n<li>Bir nechta natijani ko‘rib chiqing, faqat birinchisiga ishonmang.</li>\n<li>Kerakli sahifani xatcho‘pga saqlang.</li></ul>\n<h4>Ishonchlilikni baholash</h4>\n<ul><li>Muallif kim va u mutaxassismi?</li>\n<li>Sayt rasmiy yoki obro‘li tashkilotga tegishlimi?</li>\n<li>Ma’lumot qachon yangilangan?</li>\n<li>Boshqa manbalar bilan mos keladimi?</li>\n<li>Manbalar ko‘rsatilganmi?</li>\n<li>Reklama va bir tomonlama fikrga ehtiyot bo‘ling.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Tarixiy sana haqida bitta noma’lum saytdagi ma’lumotga ishonmay, uni darslik va ensiklopediya bilan solishtirib tekshiring.</div>\n<p>Ijtimoiy tarmoqlarda tarqalgan xabarlarni ham shu tarzda tekshiring. Rasm va videolar o‘zgartirilgan bo‘lishi mumkin, shuning uchun ularning asl manbasini qidirib toping. Tanqidiy fikrlash internetdan to‘g‘ri foydalanishning asosidir.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Ma’lumotni bir nechta manbada tekshiring.</li><li>Muallif, sana va manbaga e’tibor bering.</li></ul>","quiz":[{"q":"Internetdan topilgan axborotni nima uchun baholash kerak?","o":["Baholash internetni tezlashtiradi","U doim to‘g‘ri bo‘ladi","Hamma ma’lumot ham to‘g‘ri bo‘lmasligi mumkin","Baholash shart emas"],"a":2,"e":"Ishonchlilik tekshiriladi."},{"q":"Ishonchli manba belgisi qaysi?","o":["Muallif noma’lum, manba yo‘q","Faqat reklama ko‘p","Sana ko‘rsatilmagan","Muallif va manbalar ko‘rsatilgan, ma’lumot yangilangan"],"a":3,"e":"Aniq manba ishonch beradi."},{"q":"Qidiruvda natijani toraytirish uchun nima qilinadi?","o":["Bitta harf yoziladi","Aniq kalit so‘zlar ishlatiladi","Faqat rasm qidiriladi","Qidiruv o‘chiriladi"],"a":1,"e":"Aniq so‘z tor natija beradi."},{"q":"Ma’lumotni bir nechta manba bilan solishtirish nima uchun foydali?","o":["Ekran uchun","Tezlikni oshirish uchun","Faylni kattalashtirish uchun","To‘g‘riligini tasdiqlash uchun"],"a":3,"e":"Tekshirish usuli."},{"q":"Vaziyat: noma’lum saytda sensatsion xabar o‘qidingiz. Dastlab nima qilasiz?","o":["Saytga parol kiritasiz","Ishonib qabul qilasiz","Darhol hammaga yuborasiz","Boshqa ishonchli manbalarda tekshirasiz"],"a":3,"e":"Tekshirmay tarqatmang."},{"q":"Ma’lumot sanasi nima uchun muhim?","o":["Sana fayl hajmini aniqlaydi","Ma’lumot eskirgan bo‘lishi mumkin","Sana ahamiyatsiz","Sana ranglarni belgilaydi"],"a":1,"e":"Yangilik dolzarbligi."},{"q":"Quyidagilardan qaysi biri ishonchlilikka shubha uyg‘otadi?","o":["Ensiklopediya maqolasi","Rasmiy tashkilot sayti","Manbasiz va muallifsiz sensatsion da’vo","Ilmiy maqola manbalar bilan"],"a":2,"e":"Asossiz da’vo."},{"q":"Qidiruv tizimida birinchi chiqqan natija doim to‘g‘rimi?","o":["Ha, doim","Faqat rasmlisi","Ha, chunki u birinchi","Yo‘q, uni ham tekshirish kerak"],"a":3,"e":"Tartib to‘g‘rilikni bildirmaydi."},{"q":"Xatcho‘pga saqlash nima uchun kerak?","o":["Parol uchun","Sahifani shifrlash uchun","Sahifani o‘chirish uchun","Keyin kerakli sahifaga tez qaytish uchun"],"a":3,"e":"Tez topish."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Muallif ahamiyatsiz","Ma’lumot sanasi hech qachon kerak emas","Muallifning malakasi manba ishonchliligiga ta’sir qiladi","Reklamasi ko‘p sayt eng ishonchli"],"a":2,"e":"Mutaxassis ishonchliroq."}]},{"t":"33-dars. Fayl kengaytmasi va ularni samarali boshqarish","lesson":"<p>Fayl nomi odatda nuqta bilan ajratilgan ikki qismdan iborat: nom va kengaytma. Kengaytma fayl turini bildiradi va uni qaysi dastur ochishini aniqlaydi. Fayllarni to‘g‘ri nomlash va tartibli boshqarish ishni osonlashtiradi, kerakli faylni tez topishga yordam beradi.</p>\n<h4>Mashhur kengaytmalar</h4>\n<ul><li><b>.docx</b> — matnli hujjat.</li>\n<li><b>.xlsx</b> — elektron jadval.</li>\n<li><b>.pptx</b> — taqdimot.</li>\n<li><b>.jpg, .png</b> — tasvir.</li>\n<li><b>.mp3</b> — audio, <b>.mp4</b> — video.</li>\n<li><b>.pdf</b> — ko‘chirish va o‘qish uchun qulay hujjat.</li></ul>\n<h4>Samarali boshqarish</h4>\n<ul><li>Mazmunga mos, tushunarli nom bering.</li>\n<li>Fayllarni papkalarga guruhlang.</li>\n<li>Kengaytmani o‘zboshimchalik bilan o‘zgartirmang: fayl ochilmay qolishi mumkin.</li>\n<li>Keraksiz fayllarni o‘chiring va zaxira nusxa saqlang.</li></ul>\n<div class=\"ex\"><b>Misol.</b> <b>hisobot_9A.docx</b> faylida nom — hisobot_9A, kengaytma — docx, ya’ni Word hujjati.</div>\n<p>Fayl nomida ba’zi belgilarni (masalan, / \\ : * ? \" < > |) ishlatib bo‘lmaydi. Ko‘p fayllar bilan ishlaganda ularni sana yoki mavzu bo‘yicha nomlash, eski nusxalarni arxiv papkaga ko‘chirish va ishchi stolni tartibli saqlash foydali odatdir.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Kengaytma fayl turini bildiradi.</li><li>Fayl va papkalarni tartibli nomlang.</li></ul>","quiz":[{"q":"Fayl kengaytmasi nimani bildiradi?","o":["Faylning parolini","Faylning rangini","Fayl turini","Fayl joylashgan diskni"],"a":2,"e":"Turini aniqlaydi."},{"q":"Quyidagilardan qaysi biri elektron jadval kengaytmasi?","o":["jpg","docx","xlsx","mp3"],"a":2,"e":"xlsx — jadval."},{"q":"Qaysi kengaytma tasvirga tegishli?","o":["txt","pptx","mp3","png"],"a":3,"e":"png — tasvir."},{"q":"Quyidagilardan qaysi biri audio fayl?","o":["docx","mp3","jpg","xlsx"],"a":1,"e":"mp3 — audio."},{"q":"Kengaytmani o‘zboshimchalik bilan o‘zgartirsangiz nima bo‘lishi mumkin?","o":["Fayl kichrayadi","Hech narsa o‘zgarmaydi doim","Fayl tezlashadi","Fayl ochilmay qolishi mumkin"],"a":3,"e":"Dastur tanimay qolishi mumkin."},{"q":"Fayllarni nima uchun papkalarga guruhlanadi?","o":["Faylni yashirish uchun","Ko‘proq joy egallash uchun","Virus uchun","Kerakli faylni tez topish uchun"],"a":3,"e":"Tartib uchun."},{"q":"Fayl nomi hisobot.docx da kengaytma qaysi?","o":["hisobot","hisobot.docx","nuqta","docx"],"a":3,"e":"Nuqtadan keyingi qism."},{"q":"Vaziyat: nomi “yangi1” kabi fayllar ko‘payib ketdi. Nima qilish kerak?","o":["Hammasini o‘chirish","Hammasini bir papkaga tashlab qo‘yish","Mazmunga mos tushunarli nom berish","Kengaytmasini o‘chirish"],"a":2,"e":"Mazmunli nom topishni osonlashtiradi."},{"q":"Taqdimot fayli kengaytmasi qaysi?","o":["docx","png","mp3","pptx"],"a":3,"e":"pptx — slayd."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Fayl nomi ahamiyatsiz","Papka tuzish kerak emas","Zaxira nusxa fayllarni buzadi","Zaxira nusxa saqlash fayl yo‘qolishiga qarshi himoya"],"a":3,"e":"Himoya."}]},{"t":"34-dars. Saqlash yoki uzatish uchun fayl hajmini kamaytirish","lesson":"<p>Fayl hajmi juda katta bo‘lsa, uni saqlash joyini ko‘p egallaydi va internet orqali uzatish uzoq davom etadi. Shuning uchun fayl hajmini kamaytirish usullaridan foydalaniladi. Elektron pochtada ham yuboriladigan fayl hajmi ko‘pincha cheklangan bo‘ladi.</p>\n<h4>Hajmni kamaytirish usullari</h4>\n<ul><li><b>Arxivlash</b> — fayllarni siqib, bitta arxiv faylga joylash (ZIP, RAR).</li>\n<li>Tasvir o‘lchamini yoki sifatini kamaytirish.</li>\n<li>Videoni siqilgan formatga o‘tkazish.</li>\n<li>Hujjatdagi keraksiz rasmlarni olib tashlash.</li>\n<li>Audio va videoni past bitreytda saqlash.</li></ul>\n<h4>Siqishning ikki turi</h4>\n<ul><li>Yo‘qotishsiz: arxivdan chiqarganda asl fayl to‘liq tiklanadi.</li>\n<li>Yo‘qotishli: hajm ko‘proq kamayadi, ammo sifat biroz pasayadi (masalan, JPEG, MP3).</li></ul>\n<div class=\"ex\"><b>Misol.</b> Bir nechta hujjatni ZIP arxivga joylab, pochta orqali bitta fayl sifatida yuborish mumkin. Qabul qiluvchi uni arxivdan chiqaradi.</div>\n<p>Arxivlangan fayllarni ishlatish uchun avval ularni arxivdan chiqarish kerak. Arxivga parol qo‘yish ham mumkin, shunda faqat parolni biluvchi uni ocha oladi. Katta fayllarni bulutli xotirada saqlash ham joyni tejaydi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Arxivlash fayl hajmini kamaytiradi.</li><li>Yo‘qotishli siqishda sifat pasayishi mumkin.</li></ul>","quiz":[{"q":"Arxivlash nima?","o":["Faylni shifrlash faqat","Faylni bosib chiqarish","Fayllarni siqib, bitta arxiv faylga joylash","Faylni o‘chirish"],"a":2,"e":"Hajm kamayadi."},{"q":"Quyidagilardan qaysi biri arxiv formati?","o":["DOCX","PNG","MP3","ZIP"],"a":3,"e":"ZIP — arxiv."},{"q":"Arxivdan chiqarish nima deyiladi?","o":["Faylni yashirish","Fayllarni asl holiga qaytarish (ochish)","Faylni o‘chirish","Faylni siqish"],"a":1,"e":"Ekstraksiya."},{"q":"Yo‘qotishsiz siqish nimani anglatadi?","o":["Hajm oshadi","Sifat pasayadi","Fayl o‘chadi","Asl fayl to‘liq tiklanadi"],"a":3,"e":"Ma’lumot saqlanadi."},{"q":"Yo‘qotishli siqishga misol qaysi?","o":["Papka yaratish","Matnli fayl nusxasi","ZIP","JPEG"],"a":3,"e":"Sifat biroz kamayadi."},{"q":"Vaziyat: pochtada fayl hajmi cheklangan, siz esa katta papka yubormoqchisiz. Nima qilasiz?","o":["Faylni o‘chirasiz","Hech narsa qilmaysiz","Kengaytmasini o‘chirasiz","Papkani arxivlab hajmini kamaytirasiz"],"a":3,"e":"Arxiv hajmni kamaytiradi."},{"q":"Fayl hajmini kamaytirish nima uchun kerak?","o":["Kompyuterni sekinlashtirish uchun","Fayl sifatini oshirish uchun","Viruslarni ko‘paytirish uchun","Joyni tejash va uzatishni tezlashtirish uchun"],"a":3,"e":"Tejash."},{"q":"Tasvir hajmini kamaytirish usuli qaysi?","o":["Rangini oshirish","Uni kattalashtirish","Nusxasini ko‘paytirish","O‘lchamini yoki sifatini kamaytirish"],"a":3,"e":"Piksellar kamayadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Arxivlash hajmni doim oshiradi","Arxivdan chiqarib bo‘lmaydi","Arxiv faylni virusga aylantiradi","Arxivlash ko‘p fayllarni bitta faylga jamlashga ham yordam beradi"],"a":3,"e":"Qulay uzatish."},{"q":"Hujjatda hajmni kamaytirish uchun nima qilish mumkin?","o":["Shriftni kattalashtirish","Sahifa sonini ko‘paytirish","Rasmlar sonini oshirish","Keraksiz katta rasmlarni olib tashlash yoki kichraytirish"],"a":3,"e":"Rasmlar hajmni oshiradi."}]},{"t":"35-dars. Tasvirlarni joylashtirish va tahrirlash uchun dastur uskunalaridan foydalanish","lesson":"<p>Rastrli tasvirlar bilan ishlashda grafik muharrirning <b>uskunalar paneli</b> asosiy vosita hisoblanadi. Unda belgilash (selection), qirqish, rang tanlash, to‘ldirish, mo‘yqalam, o‘chirgich, matn qo‘shish kabi uskunalar bo‘ladi.</p>\n<h4>Asosiy imkoniyatlar</h4>\n<ul><li><b>Belgilash uskunasi</b> — tasvirning kerakli qismini ajratib olish.</li><li><b>Qatlamlar</b> — tasvirning qismlarini bir-biriga xalaqit bermay tahrirlash imkoni.</li><li><b>Joylashtirish</b> — rasmni hujjat yoki slaydga qo‘yish, o‘lchamini sozlash.</li><li><b>Bekor qilish (Undo)</b> — oxirgi amalni qaytarish.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Fotosuratdagi faqat bitta odamni boshqa hujjatga ko‘chirish uchun avval belgilash uskunasi bilan uni ajratamiz, nusxa olamiz va yangi hujjatga joylaymiz.</div>\n<h4>Eslab qoling</h4><ul><li>Tahrirdan oldin asl faylning nusxasini saqlang.</li><li>Har bir uskunaning o‘z sozlamalari bor (qalinlik, rang, yumshoqlik).</li><li>Noto‘g‘ri amalni Undo bilan qaytarish mumkin.</li></ul>","quiz":[{"q":"Tasvirning kerakli qismini ajratib olish uchun qaysi uskunadan foydalaniladi?","o":["O‘chirgich","Belgilash (selection) uskunasi","Matn uskunasi","To‘ldirish (bo‘yoq quyish) uskunasi"],"a":1,"e":"Belgilash uskunasi tasvirning kerakli qismini ajratib oladi."},{"q":"Grafik muharrirda qatlamlarning asosiy foydasi nima?","o":["Faylni avtomatik nomlash","Tasvir qismlarini bir-biriga xalaqit bermay tahrirlash","Fayl hajmini albatta kamaytirish","Tasvirni faqat qora-oq qilish"],"a":1,"e":"Har bir qatlam alohida tahrirlanadi, qolganlari o‘zgarmaydi."},{"q":"Noto‘g‘ri bajarilgan oxirgi amalni qaytarish uchun nima ishlatiladi?","o":["Undo (bekor qilish)","Print","Paste","Save"],"a":0,"e":"Undo oxirgi amalni bekor qiladi."},{"q":"Tahrirlashni boshlashdan oldin nima qilish tavsiya etiladi?","o":["Asl faylning zaxira nusxasini saqlash","Asl faylni o‘chirib yuborish","Kompyuterni qayta yoqish","Fayl kengaytmasini o‘zgartirish"],"a":0,"e":"Asl rasm yo‘qolib qolmasligi uchun nusxa saqlanadi."},{"q":"Mo‘yqalam uskunasining vazifasi qaysi?","o":["Faylni arxivlash","Ekranni yozib olish","Rasmni chop etish","Tasvirga erkin chiziq va bo‘yoq tushirish"],"a":3,"e":"Mo‘yqalam bilan erkin chizish va bo‘yash mumkin."},{"q":"Quyidagilardan qaysi biri uskunalar panelida bo‘lmaydi?","o":["Antivirus skaneri","Matn qo‘shish","O‘chirgich","Rang tanlash"],"a":0,"e":"Antivirus skaneri grafik muharrir uskunasi emas."},{"q":"Fotosuratdagi bitta odamni boshqa hujjatga ko‘chirish uchun to‘g‘ri tartibni tanlang.","o":["Belgilash, nusxa olish, yangi hujjatga joylash","Joylash, belgilash, nusxa olish","Saqlash, belgilash, chop etish","Nusxa olish, o‘chirish, saqlash"],"a":0,"e":"Avval ajratiladi, so‘ng nusxalanadi va joylanadi."},{"q":"“Uskunaning sozlamalari” deganda nimani tushunamiz?","o":["Fayl nomini","Qalinlik, rang, yumshoqlik kabi parametrlarni","Internet tarmog‘ini","Kompyuter tezligini"],"a":1,"e":"Har bir uskuna uchun parametrlar sozlanadi."},{"q":"Rastrli tasvir nimalardan tashkil topadi?","o":["Tovush to‘lqinlaridan","Piksellardan","Faqat matndan","Faqat chiziqlardan"],"a":1,"e":"Rastrli tasvir pikselli to‘r ko‘rinishida bo‘ladi."},{"q":"Rasmni hujjatga qo‘yishdan keyin uning o‘lchamini o‘zgartirish mumkinmi?","o":["Faqat chop etilgandan keyin","Ha, o‘lcham sozlanadi","Yo‘q, faqat asl o‘lchamda qoladi","Faqat qora-oq rejimda"],"a":1,"e":"Joylashtirilgan tasvirning o‘lchamini sozlash mumkin."}]},{"t":"36-dars. Tasvirni aniq joylashtirish. Tasvirning tomonlar nisbatini o‘zgartirish","lesson":"<p>Tasvirni hujjatga aniq joylashtirish va tomonlar nisbatini to‘g‘ri saqlash professional ko‘rinish uchun muhim. <b>Tomonlar nisbati</b> — tasvir eni va bo‘yining nisbati (masalan, 4 : 3 yoki 16 : 9).</p>\n<h4>Asosiy qoidalar</h4>\n<ul><li>O‘lchamni o‘zgartirganda burchakdagi tutqichdan foydalansangiz, nisbat saqlanadi.</li><li>Eni va bo‘yini alohida o‘zgartirsangiz, tasvir <b>cho‘zilib yoki siqilib</b> ketadi (deformatsiya).</li><li>Aniq joylashtirish uchun yo‘naltiruvchi chiziqlar, to‘r (grid) va tekislash vositalaridan foydalaniladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Eni 800, bo‘yi 400 piksel bo‘lgan rasm nisbati 2 : 1. Eni 400 ga kamaytirilsa, nisbat saqlanishi uchun bo‘yi 200 bo‘lishi kerak.</div>\n<h4>Eslab qoling</h4><ul><li>Nisbatni saqlash — deformatsiyadan himoya.</li><li>Tekislash vositalari tasvirlarni bir chiziqda joylashtiradi.</li></ul>","quiz":[{"q":"Tasvirning tomonlar nisbati nimani bildiradi?","o":["Fayl hajmini","Eni va bo‘yining nisbatini","Tasvir nomini","Rang sonini"],"a":1,"e":"Tomonlar nisbati eni va bo‘yining nisbati."},{"q":"Eni 800, bo‘yi 400 piksel bo‘lgan rasmning tomonlar nisbati qanday?","o":["2 : 1","1 : 2","4 : 3","16 : 9"],"a":0,"e":"800 : 400 = 2 : 1."},{"q":"Eni 600 piksel, bo‘yi 300 piksel rasm eni 300 ga kamaytirildi. Nisbat saqlansa, bo‘yi nechaga teng bo‘ladi?","o":["600","300","150","100"],"a":2,"e":"Nisbat 2 : 1, shuning uchun bo‘yi 150."},{"q":"Eni va bo‘yini nisbatga qaramay alohida o‘zgartirsak, nima sodir bo‘ladi?","o":["Fayl nomi o‘zgaradi","Tasvir cho‘ziladi yoki siqiladi","Tasvir o‘chib ketadi","Tasvir rangi o‘zgaradi"],"a":1,"e":"Bu holatda tasvir deformatsiyalanadi."},{"q":"Burchakdagi tutqichdan tortib o‘lchamni o‘zgartirish odatda nimani ta’minlaydi?","o":["Rangning o‘zgarishini","Nisbatning saqlanishini","Qatlamlarning birlashishini","Faylning o‘chishini"],"a":1,"e":"Burchak tutqichi nisbatni saqlab o‘lchamni o‘zgartiradi."},{"q":"Obyektlarni aniq joylashtirishda qaysi vosita yordam beradi?","o":["Brauzer tarixi","Yo‘naltiruvchi chiziqlar va to‘r (grid)","Spam filtri","Antivirus"],"a":1,"e":"Grid va yo‘naltiruvchi chiziqlar aniq joylashtiradi."},{"q":"Tomonlar nisbati 16 : 9 bo‘lgan tasvir qaysi ko‘rinishga ega?","o":["Doira shaklida","Tik uzun","Kvadrat","Keng, gorizontal ko‘rinishli"],"a":3,"e":"16 : 9 keng ekranli format."},{"q":"Kvadrat tasvirning tomonlar nisbati qanday bo‘ladi?","o":["1 : 1","2 : 1","16 : 9","4 : 3"],"a":0,"e":"Kvadratning tomonlari teng."},{"q":"Deformatsiya nima?","o":["Fayl nusxasi","Rang kodi","Tasvir shaklining buzilishi","Rasmning saqlanishi"],"a":2,"e":"Notekis o‘zgartirishdan tasvir shakli buziladi."},{"q":"Bir nechta rasmni bir chiziqda tekis joylashtirish uchun nima qilinadi?","o":["Har birini o‘chirib qayta yuklash","Faylni arxivlash","Rangni o‘zgartirish","Tekislash (align) vositasidan foydalaniladi"],"a":3,"e":"Tekislash vositasi obyektlarni bir chiziqqa keltiradi."}]},{"t":"37-dars. Tasvirni qirqish va aylantirish","lesson":"<p>Tasvirni <b>qirqish (crop)</b> — keraksiz chekka qismlarini olib tashlash. Bunda tasvir o‘lchami kamayadi, asosiy mazmun esa saqlanadi. <b>Aylantirish (rotate)</b> — tasvirni ma’lum burchakka burish yoki ag‘darish (flip).</p>\n<h4>Farqlar</h4>\n<ul><li><b>Qirqish</b> — tasvirning bir qismi qoladi, qolgani olib tashlanadi.</li><li><b>Aylantirish</b> — butun tasvir saqlanadi, faqat yo‘nalishi o‘zgaradi.</li><li><b>Ag‘darish</b> — tasvirning ko‘zgudagi aksi kabi bo‘lishi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Telefon bilan yon tomonga yotqizib olingan surat 90 gradusga aylantiriladi. Suratdagi ortiqcha osmon qismi esa qirqish bilan olib tashlanadi.</div>\n<h4>Eslab qoling</h4><ul><li>Qirqish tasvir kompozitsiyasini yaxshilaydi.</li><li>Qirqilgan qism saqlanmasa, uni tiklab bo‘lmasligi mumkin — nusxa saqlang.</li></ul>","quiz":[{"q":"Tasvirni qirqish (crop) nima uchun qo‘llaniladi?","o":["Tasvirni chop etish uchun","Keraksiz chekka qismlarni olib tashlash uchun","Tasvir rangini o‘zgartirish uchun","Faylni arxivlash uchun"],"a":1,"e":"Qirqish keraksiz qismlarni olib tashlaydi."},{"q":"Aylantirish (rotate) amali natijasida nima o‘zgaradi?","o":["Fayl nomi","Tasvirning yo‘nalishi","Tasvirning mazmuni butunlay","Fayl kengaytmasi"],"a":1,"e":"Faqat yo‘nalish o‘zgaradi."},{"q":"Yon tomonga yotib qolgan suratni to‘g‘rilash uchun nima qilinadi?","o":["Rangi o‘zgartiriladi","Qirqiladi","90 gradusga aylantiriladi","Arxivlanadi"],"a":2,"e":"Burish orqali to‘g‘rilanadi."},{"q":"Ag‘darish (flip) natijasi qanday bo‘ladi?","o":["Tasvir kichrayadi","Tasvir qora-oq bo‘ladi","Tasvir o‘chadi","Tasvirning ko‘zgudagi aksi kabi"],"a":3,"e":"Flip tasvirni aks ettiradi."},{"q":"Qirqishdan keyin tasvir o‘lchami odatda qanday bo‘ladi?","o":["Kichrayadi","O‘zgarmaydi","Bir necha barobar kattalashadi","Nolga teng bo‘ladi"],"a":0,"e":"Qirqilgan qism olib tashlangani uchun kichrayadi."},{"q":"Qirqilgan qismni keyin tiklay olish uchun nima qilish kerak?","o":["Kompyuterni o‘chirish","Faylni qayta nomlash","Asl fayl nusxasini saqlab qo‘yish","Rangni o‘zgartirish"],"a":2,"e":"Asl nusxa bo‘lsa, kerak bo‘lganda tiklash mumkin."},{"q":"Quyidagilardan qaysi biri qirqishga misol?","o":["Suratni 180 gradusga burish","Suratdagi ortiqcha osmon qismini olib tashlash","Suratni boshqa papkaga ko‘chirish","Suratni ko‘zguli aksga keltirish"],"a":1,"e":"Qismni olib tashlash — qirqish."},{"q":"Quyidagilardan qaysi biri aylantirishga misol?","o":["Tasvirni soat strelkasi bo‘yicha 90 gradusga burish","Chekkalarini kesish","Matn qo‘shish","Rangini o‘chirish"],"a":0,"e":"Burish — aylantirish."},{"q":"Qirqish kompozitsiyaga qanday ta’sir qiladi?","o":["Ovozni qo‘shadi","Faylni zararlaydi","Asosiy obyektga e’tiborni kuchaytiradi","Hech qanday ta’sir qilmaydi"],"a":2,"e":"Keraksiz qismlar olib tashlansa, asosiy obyekt ajralib turadi."},{"q":"Tasvirni 360 gradusga aylantirsak, natija qanday bo‘ladi?","o":["Teskari bo‘lib qoladi","Asl holatiga qaytadi","Kichrayadi","Qora-oq bo‘ladi"],"a":1,"e":"To‘liq aylanish asl holatni beradi."}]},{"t":"38-dars. Tasvir rangi, yorqinligi, kontrasti va aniqligi boshqarish","lesson":"<p>Tasvirning ko‘rinishi to‘rt asosiy xususiyatga bog‘liq: <b>rang</b>, <b>yorqinlik</b>, <b>kontrast</b> va <b>aniqlik</b>.</p>\n<ul><li><b>Yorqinlik (brightness)</b> — tasvirning umumiy yorug‘ligi.</li><li><b>Kontrast</b> — eng yorug‘ va eng qorong‘i joylar orasidagi farq.</li><li><b>Aniqlik (sharpness)</b> — chekkalarning ravshanligi.</li><li><b>To‘yinganlik</b> — ranglarning jonliligi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Qorong‘i tushgan surat yorqinlik oshirilsa, yorug‘roq bo‘ladi. Xira ko‘ringan surat esa kontrast va aniqlik oshirilganda ravshanlashadi.</div>\n<h4>Eslab qoling</h4><ul><li>Haddan tashqari oshirish tasvirni buzishi mumkin.</li><li>O‘zgarishlarni asl nusxaga emas, nusxaga qo‘llang.</li></ul>","quiz":[{"q":"Tasvirning umumiy yorug‘ligi qaysi xususiyat bilan boshqariladi?","o":["Kontrast","Kengaytma","Aniqlik","Yorqinlik"],"a":3,"e":"Brightness — umumiy yorug‘lik."},{"q":"Eng yorug‘ va eng qorong‘i joylar orasidagi farq nima deyiladi?","o":["Masshtab","Kontrast","Piksel","Yorqinlik"],"a":1,"e":"Kontrast — yorug‘ va qorong‘i orasidagi farq."},{"q":"Chekka chiziqlarning ravshanligi qaysi xususiyatga bog‘liq?","o":["Fayl nomi","Yorqinlik","Hajm","Aniqlik"],"a":3,"e":"Sharpness chekkalarni ravshan qiladi."},{"q":"Qorong‘i tushgan suratni yorug‘roq qilish uchun nima oshiriladi?","o":["Fayl hajmi","Papkalar soni","Kengaytma uzunligi","Yorqinlik"],"a":3,"e":"Yorqinlik oshirilsa, tasvir yorug‘lashadi."},{"q":"Xira ko‘ringan, “yassi” suratni jonlantirish uchun nima oshiriladi?","o":["Ekran o‘lchami","Papka hajmi","Fayl nomi","Kontrast"],"a":3,"e":"Kontrast oshirilganda tasvir ravshanroq bo‘ladi."},{"q":"To‘yinganlik nimani ifodalaydi?","o":["Tasvir enini","Piksellar sonini","Fayl hajmini","Ranglarning jonliligini"],"a":3,"e":"Saturation ranglarning to‘qligini bildiradi."},{"q":"Sozlamalarni haddan tashqari oshirsak, nima bo‘lishi mumkin?","o":["Hech narsa o‘zgarmaydi","Tasvir buzilishi mumkin","Fayl avtomatik arxivlanadi","Tasvir sifati albatta yaxshilanadi"],"a":1,"e":"Ortiqcha sozlash tasvirni buzishi mumkin."},{"q":"Tahrirni qaysi faylga qo‘llash maqsadga muvofiq?","o":["Faqat asl faylga, nusxa saqlamasdan","Tizim fayllariga","Asl fayl nusxasiga","Tasodifiy faylga"],"a":2,"e":"Asl nusxa saqlanib qoladi."},{"q":"Quyidagilardan qaysi biri tasvirni sozlash xususiyati emas?","o":["Yorqinlik","Aniqlik","Kontrast","Antivirus bazasi"],"a":3,"e":"Antivirus bazasi tasvir xususiyati emas."},{"q":"Kontrast juda past bo‘lsa, tasvir qanday ko‘rinadi?","o":["Ikki baravar katta","Juda ravshan","Xira, “yassi”","Qora-oq"],"a":2,"e":"Past kontrastda tasvir xira bo‘ladi."}]},{"t":"39-dars. Sahifa maketi. Maqsad va auditoriyaga mos hujjat yaratish uchun dasturiy uskunalardan foydalanish","lesson":"<p><b>Sahifa maketi</b> — hujjat sahifasidagi matn, rasm, jadval va boshqa obyektlarning joylashuvi. Maket hujjatning <b>maqsadi</b> va <b>auditoriyasiga</b> mos bo‘lishi kerak: bolalar uchun ravshan va rangli, rasmiy hujjat uchun esa jiddiy va soddalashtirilgan.</p>\n<h4>Maket elementlari</h4>\n<ul><li><b>Sahifa yo‘nalishi</b> — tik (portret) yoki yotiq (landshaft).</li><li><b>Hoshiyalar (margins)</b> — sahifa chetidan bo‘sh joy.</li><li><b>Ustunlar</b> — matnni bir necha ustunga joylash.</li><li><b>Qog‘oz o‘lchami</b> — masalan, A4.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Gazeta sahifasi ko‘p ustunli bo‘ladi, rasmiy xat esa odatda bitta ustunli va keng hoshiyali.</div>\n<h4>Eslab qoling</h4><ul><li>Avval maqsad va auditoriyani aniqlang, so‘ng maketni tanlang.</li><li>Bir hujjatda uslub izchil bo‘lsin.</li></ul>","quiz":[{"q":"Sahifa maketi nima?","o":["Hujjat sahifasidagi obyektlarning joylashuvi","Faqat rasm hajmi","Kompyuter modeli","Faqat matn shrifti"],"a":0,"e":"Maket obyektlar joylashuvini bildiradi."},{"q":"Hujjat maketini tanlashda birinchi navbatda nimani hisobga olish kerak?","o":["Hujjat maqsadi va auditoriyasini","Kompyuter rangini","Klaviatura turini","Internet tezligini"],"a":0,"e":"Maket maqsad va auditoriyaga mos bo‘lishi kerak."},{"q":"Sahifaning tik joylashuvi qanday nomlanadi?","o":["Portret","Maket","Landshaft","Kollaj"],"a":0,"e":"Portret — tik yo‘nalish."},{"q":"Yotiq sahifa yo‘nalishi qanday nomlanadi?","o":["Ustun","Landshaft","Portret","Hoshiya"],"a":1,"e":"Landshaft — yotiq yo‘nalish."},{"q":"Sahifa chetidan qoldiriladigan bo‘sh joy nima deyiladi?","o":["Sarlavha","Hoshiya (margin)","Ustun","Yorliq"],"a":1,"e":"Margin — sahifa chetidagi bo‘sh joy."},{"q":"Gazeta sahifalari odatda qanday maketga ega?","o":["Faqat jadval","Ko‘p ustunli","Bitta ustunli faqat","Ustunsiz, faqat rasm"],"a":1,"e":"Gazetada matn bir necha ustunga joylanadi."},{"q":"Rasmiy xat uchun qaysi maket mos keladi?","o":["Animatsiyali","Ko‘p ustunli reklama","Sodda, jiddiy, bir ustunli","Juda rangli, bezakli"],"a":2,"e":"Rasmiy hujjat soddalikni talab qiladi."},{"q":"A4 nima?","o":["Dastur nomi","Qog‘oz o‘lchami standarti","Fayl kengaytmasi","Tarmoq protokoli"],"a":1,"e":"A4 — keng tarqalgan qog‘oz o‘lchami."},{"q":"Bolalar uchun mo‘ljallangan hujjatda nima maqsadga muvofiq?","o":["Rasmsiz zich matn","Ravshan rangli va katta shriftli bezak","Faqat kichik oq-qora matn","Juda murakkab terminlar"],"a":1,"e":"Bolalarga yorqin va tushunarli maket mos."},{"q":"Bir hujjat ichida uslub izchil bo‘lishi nimaga xizmat qiladi?","o":["Hujjatning tartibli va o‘qishga qulay bo‘lishiga","Kompyuter xotirasiga","Internet tezligiga","Faylning o‘chishiga"],"a":0,"e":"Izchillik tartib va qulaylik beradi."}]},{"t":"40-dars. Hujjatga obyektlarni joylashtirish","lesson":"<p>Matnli hujjatga matndan tashqari <b>rasm, jadval, diagramma, shakl, matn maydoni</b> kabi obyektlar ham joylashtiriladi. Obyektlar hujjatni ko‘rgazmali va tushunarli qiladi.</p>\n<h4>Obyektni joylashtirish usullari</h4>\n<ul><li><b>Matn bilan o‘rash</b> — matn obyektni aylanib o‘tadimi, uning ustidan yoki ostidan o‘tadimi, shuni belgilaydi.</li><li><b>Qator ichida</b> — obyekt matn belgisi kabi qatorning ichida turadi.</li><li><b>Tekislash</b> — obyektni chapga, markazga yoki o‘ngga to‘g‘rilash.</li><li><b>Sarlavha (izoh)</b> — rasm yoki jadval tagiga yoziladigan nom.</li></ul>\n<div class=\"ex\"><b>Amaliy qadamlar.</b><ol><li>Hujjatga rasm qo‘shing.</li><li>Rasmni tanlab, matn bilan o‘rash turini belgilang.</li><li>Rasmni sahifada kerakli joyga siljiting.</li><li>Ostiga izoh yozing.</li></ol></div>\n<p>Obyektlar sahifa chegarasidan chiqib ketmasligi, matnni to‘sib qo‘ymasligi lozim. Bir sahifada juda ko‘p obyekt bo‘lsa, hujjat chalkash ko‘rinadi.</p>\n<h4>Eslab qoling</h4><ul><li>Obyekt matnni to‘ldirishi kerak, to‘sib qo‘ymasligi kerak.</li><li>O‘rash turi obyekt va matn munosabatini belgilaydi.</li><li>Rasm va jadvalga izoh yozish hujjatni tartibli qiladi.</li></ul>","quiz":[{"q":"Hujjatga joylashtiriladigan obyektga qaysi biri kiradi?","o":["Faqat fayl nomi","Faqat oddiy matn","Rasm, jadval va diagramma","Faqat sahifa raqami"],"a":2,"e":"Rasm, jadval, diagramma va shakllar hujjat obyektlari hisoblanadi."},{"q":"Matn bilan o‘rash nimani belgilaydi?","o":["Matn obyektni qanday aylanib o‘tishini","Hujjat tilini","Faylning hajmini","Obyektning rangini"],"a":0,"e":"O‘rash obyekt va matn o‘rtasidagi joylashuv munosabatini boshqaradi."},{"q":"“Qator ichida” joylashuvda obyekt qanday turadi?","o":["Matn ustida shaffof","Sahifadan tashqarida","Sahifaning istalgan joyida erkin","Matn belgisi kabi qator ichida"],"a":3,"e":"Bunda obyekt harf kabi qatorda turadi va matn bilan birga siljiydi."},{"q":"Rasm yoki jadval ostiga yoziladigan nom nima deyiladi?","o":["Izoh (sarlavha)","Hoshiya","Ustun","Kolontitul"],"a":0,"e":"Izoh obyekt nimani ko‘rsatishini tushuntiradi."},{"q":"Rasm tanlangan, uni matn orasida erkin siljitmoqchisiz. Avval nima qilish kerak?","o":["Hujjatni boshqa formatda saqlash","Matn bilan o‘rash turini qatordan boshqasiga o‘zgartirish","Rasmni o‘chirib, qayta yozish","Sahifa yo‘nalishini o‘zgartirish"],"a":1,"e":"Qator ichidagi obyekt erkin siljimaydi, shuning uchun o‘rash turi o‘zgartiriladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Obyektlarga izoh yozish mumkin emas","Bir sahifada obyekt qancha ko‘p bo‘lsa, shuncha yaxshi","Obyektlar doim sahifa chegarasidan chiqishi kerak","Obyektlar matnni to‘sib qo‘ymasligi kerak"],"a":3,"e":"Obyekt matnni to‘ldirishi, o‘qishga xalaqit bermasligi lozim."},{"q":"Obyektni sahifa markaziga to‘g‘rilash qaysi amal?","o":["Qirqish","Aylantirish","Tekislash","Nusxalash"],"a":2,"e":"Tekislash chapga, markazga yoki o‘ngga to‘g‘rilaydi."},{"q":"Matn obyektni aylanib o‘tishi uchun qaysi sozlama kerak?","o":["Matn bilan o‘rash","Imloni tekshirish","Sahifa raqamlash","Faylni himoyalash"],"a":0,"e":"O‘rash sozlamasi matnning obyekt atrofida oqishini ta’minlaydi."},{"q":"Bir sahifaga juda ko‘p obyekt joylansa nima bo‘ladi?","o":["Hujjat yaxshiroq ko‘rinadi","Hujjat chalkash va o‘qishga noqulay bo‘ladi","Hujjat tezroq ochiladi","Matn avtomatik tarjima bo‘ladi"],"a":1,"e":"Ortiqcha obyekt e’tiborni tarqatadi."},{"q":"Diagramma hujjat uchun nima beradi?","o":["Matnni imlo xatolaridan tozalashni","Ma’lumotlarni ko‘rgazmali ko‘rsatish imkonini","Printer sozlamasini","Fayl nomini o‘zgartirishni"],"a":1,"e":"Diagramma raqamli ma’lumotlarni tushunarli qiladi."}]},{"t":"41-dars. Header va Footer maydonlarini yaratish","lesson":"<p><b>Kolontitul</b> (Header va Footer) — hujjat sahifalarining yuqori va pastki hoshiyasidagi takrorlanuvchi maydon. <b>Header</b> — yuqori kolontitul, <b>Footer</b> — pastki kolontitul.</p>\n<h4>Nimalar joylanadi</h4>\n<ul><li>Hujjat yoki bo‘lim nomi, muallif, sana.</li><li>Tashkilot logotipi.</li><li><b>Sahifa raqami</b> — odatda pastki kolontitulda.</li></ul>\n<p>Kolontitulga yozilgan ma’lumot barcha sahifalarda avtomatik takrorlanadi, shuning uchun har sahifaga qo‘lda yozish shart emas. Birinchi sahifa (titul) uchun kolontitulni alohida sozlash yoki o‘chirib qo‘yish mumkin. Toq va juft sahifalar uchun turli kolontitul ham beriladi, kitoblarda shunday qilinadi.</p>\n<div class=\"ex\"><b>Amaliy qadamlar.</b><ol><li>Kolontitulni tahrirlash rejimini oching.</li><li>Yuqori kolontitulga hujjat nomini yozing.</li><li>Pastki kolontitulga sahifa raqamini qo‘shing.</li><li>Kolontitulni yoping va barcha sahifalarni ko‘zdan kechiring.</li></ol></div>\n<h4>Eslab qoling</h4><ul><li>Header — yuqorida, Footer — pastda.</li><li>Kolontitul ma’lumoti barcha sahifalarda takrorlanadi.</li><li>Sahifa raqami hujjatda o‘rin topishni osonlashtiradi.</li></ul>","quiz":[{"q":"Header nima?","o":["Sahifaning yuqori kolontituli","Sahifa raqami","Jadval sarlavhasi","Sahifaning pastki kolontituli"],"a":0,"e":"Header yuqori hoshiyadagi takrorlanuvchi maydon."},{"q":"Footer sahifaning qayerida joylashadi?","o":["Pastki qismida","Yuqori qismida","O‘rtasida","Yon chetida"],"a":0,"e":"Footer pastki kolontitul hisoblanadi."},{"q":"Sahifa raqami odatda qayerga qo‘yiladi?","o":["Hujjat nomiga","Rasm ichiga","Jadval katagiga","Pastki kolontitulga"],"a":3,"e":"Raqam ko‘pincha footerda ko‘rsatiladi, ammo header ham mumkin."},{"q":"Kolontitulga yozilgan ma’lumot nima bo‘ladi?","o":["Faqat birinchi sahifada ko‘rinadi","Barcha sahifalarda avtomatik takrorlanadi","Faqat oxirgi sahifada ko‘rinadi","Bosib chiqarilmaydi"],"a":1,"e":"Kolontitul hujjatning hamma sahifasiga tegishli."},{"q":"Hujjat nomini har sahifa tepasida ko‘rsatish uchun nima qilinadi?","o":["Har sahifaga qo‘lda yozib chiqish","Sahifa yo‘nalishini o‘zgartirish","Nomni yuqori kolontitulga yozish","Nomni jadvalga solish"],"a":2,"e":"Kolontitulga bir marta yozish yetarli."},{"q":"Titul sahifada kolontitul kerak bo‘lmasa nima qilinadi?","o":["Hech narsa qilib bo‘lmaydi","Shrift o‘zgartiriladi","Birinchi sahifa uchun alohida sozlanadi yoki o‘chiriladi","Butun hujjat o‘chiriladi"],"a":2,"e":"Birinchi sahifaga alohida kolontitul belgilash imkoni bor."},{"q":"Kitob kabi hujjatlarda toq va juft sahifalar uchun nima mumkin?","o":["Faqat bir xil kolontitul","Kolontitulni qo‘yib bo‘lmaydi","Turli kolontitul belgilash","Faqat rasm qo‘yish"],"a":2,"e":"Toq va juft sahifalarga alohida kolontitul beriladi."},{"q":"Kolontitulga odatda nima joylanmaydi?","o":["Muallif nomi","Logotip","Sana","Hujjatning asosiy matni"],"a":3,"e":"Asosiy matn sahifa tanasida yoziladi."},{"q":"To‘g‘ri mulohazani toping.","o":["Header sahifa pastida bo‘ladi","Kolontitul sahifa chetidagi alohida maydon","Kolontitul faqat rasmlar uchun","Kolontitulni tahrirlab bo‘lmaydi"],"a":1,"e":"Kolontitul tahrirlanadi va hoshiyada joylashadi."},{"q":"Kolontitulga sahifa raqamini qo‘shishdan maqsad nima?","o":["Matnni tarjima qilish","Sahifani topish va tartibni kuzatishni osonlashtirish","Fayl hajmini kamaytirish","Rasm sifatini oshirish"],"a":1,"e":"Raqamlar hujjat bo‘ylab yo‘nalishni osonlashtiradi."}]},{"t":"42-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 5</b> quyidagi darslarni qamrab oladi:</p><ul><li>Internetdan samarali foydalanish. Internetdan topilgan axborotning ishonchliligini baholash</li><li>Fayl kengaytmasi va ularni samarali boshqarish</li><li>Saqlash yoki uzatish uchun fayl hajmini kamaytirish</li><li>Tasvirlarni joylashtirish va tahrirlash uchun dastur uskunalaridan foydalanish</li><li>Tasvirni aniq joylashtirish. Tasvirning tomonlar nisbatini o‘zgartirish</li><li>Tasvirni qirqish va aylantirish</li><li>Tasvir rangi, yorqinligi, kontrasti va aniqligi boshqarish</li><li>Sahifa maketi. Maqsad va auditoriyaga mos hujjat yaratish uchun dasturiy uskunalardan foydalanish</li><li>Hujjatga obyektlarni joylashtirish</li><li>Header va Footer maydonlarini yaratish</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Yo‘qotishsiz siqish nimani anglatadi?","o":["Hajm oshadi","Sifat pasayadi","Fayl o‘chadi","Asl fayl to‘liq tiklanadi"],"a":3,"e":"Ma’lumot saqlanadi."},{"q":"Kolontitulga sahifa raqamini qo‘shishdan maqsad nima?","o":["Matnni tarjima qilish","Sahifani topish va tartibni kuzatishni osonlashtirish","Fayl hajmini kamaytirish","Rasm sifatini oshirish"],"a":1,"e":"Raqamlar hujjat bo‘ylab yo‘nalishni osonlashtiradi."},{"q":"Gazeta sahifalari odatda qanday maketga ega?","o":["Faqat jadval","Ko‘p ustunli","Bitta ustunli faqat","Ustunsiz, faqat rasm"],"a":1,"e":"Gazetada matn bir necha ustunga joylanadi."},{"q":"Quyidagilardan qaysi biri elektron jadval kengaytmasi?","o":["jpg","docx","xlsx","mp3"],"a":2,"e":"xlsx — jadval."},{"q":"Header nima?","o":["Sahifaning yuqori kolontituli","Sahifa raqami","Jadval sarlavhasi","Sahifaning pastki kolontituli"],"a":0,"e":"Header yuqori hoshiyadagi takrorlanuvchi maydon."},{"q":"Ishonchli manba belgisi qaysi?","o":["Muallif noma’lum, manba yo‘q","Faqat reklama ko‘p","Sana ko‘rsatilmagan","Muallif va manbalar ko‘rsatilgan, ma’lumot yangilangan"],"a":3,"e":"Aniq manba ishonch beradi."},{"q":"Rasmiy xat uchun qaysi maket mos keladi?","o":["Animatsiyali","Ko‘p ustunli reklama","Sodda, jiddiy, bir ustunli","Juda rangli, bezakli"],"a":2,"e":"Rasmiy hujjat soddalikni talab qiladi."},{"q":"Vaziyat: noma’lum saytda sensatsion xabar o‘qidingiz. Dastlab nima qilasiz?","o":["Saytga parol kiritasiz","Ishonib qabul qilasiz","Darhol hammaga yuborasiz","Boshqa ishonchli manbalarda tekshirasiz"],"a":3,"e":"Tekshirmay tarqatmang."},{"q":"Vaziyat: nomi “yangi1” kabi fayllar ko‘payib ketdi. Nima qilish kerak?","o":["Hammasini o‘chirish","Hammasini bir papkaga tashlab qo‘yish","Mazmunga mos tushunarli nom berish","Kengaytmasini o‘chirish"],"a":2,"e":"Mazmunli nom topishni osonlashtiradi."},{"q":"Qirqish kompozitsiyaga qanday ta’sir qiladi?","o":["Ovozni qo‘shadi","Faylni zararlaydi","Asosiy obyektga e’tiborni kuchaytiradi","Hech qanday ta’sir qilmaydi"],"a":2,"e":"Keraksiz qismlar olib tashlansa, asosiy obyekt ajralib turadi."},{"q":"Sozlamalarni haddan tashqari oshirsak, nima bo‘lishi mumkin?","o":["Hech narsa o‘zgarmaydi","Tasvir buzilishi mumkin","Fayl avtomatik arxivlanadi","Tasvir sifati albatta yaxshilanadi"],"a":1,"e":"Ortiqcha sozlash tasvirni buzishi mumkin."},{"q":"Qirqilgan qismni keyin tiklay olish uchun nima qilish kerak?","o":["Kompyuterni o‘chirish","Faylni qayta nomlash","Asl fayl nusxasini saqlab qo‘yish","Rangni o‘zgartirish"],"a":2,"e":"Asl nusxa bo‘lsa, kerak bo‘lganda tiklash mumkin."},{"q":"Tasvir hajmini kamaytirish usuli qaysi?","o":["Rangini oshirish","Uni kattalashtirish","Nusxasini ko‘paytirish","O‘lchamini yoki sifatini kamaytirish"],"a":3,"e":"Piksellar kamayadi."},{"q":"Deformatsiya nima?","o":["Fayl nusxasi","Rang kodi","Tasvir shaklining buzilishi","Rasmning saqlanishi"],"a":2,"e":"Notekis o‘zgartirishdan tasvir shakli buziladi."},{"q":"Tahrirlashni boshlashdan oldin nima qilish tavsiya etiladi?","o":["Asl faylning zaxira nusxasini saqlash","Asl faylni o‘chirib yuborish","Kompyuterni qayta yoqish","Fayl kengaytmasini o‘zgartirish"],"a":0,"e":"Asl rasm yo‘qolib qolmasligi uchun nusxa saqlanadi."},{"q":"Obyektni sahifa markaziga to‘g‘rilash qaysi amal?","o":["Qirqish","Aylantirish","Tekislash","Nusxalash"],"a":2,"e":"Tekislash chapga, markazga yoki o‘ngga to‘g‘rilaydi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Obyektlarga izoh yozish mumkin emas","Bir sahifada obyekt qancha ko‘p bo‘lsa, shuncha yaxshi","Obyektlar doim sahifa chegarasidan chiqishi kerak","Obyektlar matnni to‘sib qo‘ymasligi kerak"],"a":3,"e":"Obyekt matnni to‘ldirishi, o‘qishga xalaqit bermasligi lozim."},{"q":"Qorong‘i tushgan suratni yorug‘roq qilish uchun nima oshiriladi?","o":["Fayl hajmi","Papkalar soni","Kengaytma uzunligi","Yorqinlik"],"a":3,"e":"Yorqinlik oshirilsa, tasvir yorug‘lashadi."},{"q":"Rastrli tasvir nimalardan tashkil topadi?","o":["Tovush to‘lqinlaridan","Piksellardan","Faqat matndan","Faqat chiziqlardan"],"a":1,"e":"Rastrli tasvir pikselli to‘r ko‘rinishida bo‘ladi."},{"q":"Kvadrat tasvirning tomonlar nisbati qanday bo‘ladi?","o":["1 : 1","2 : 1","16 : 9","4 : 3"],"a":0,"e":"Kvadratning tomonlari teng."}]},{"t":"43-dars. Korporativ brend va unga xos stil. Korporativ brendga xos stilga muvofiq hujjat tayyorlash","lesson":"<p><b>Korporativ brend</b> — kompaniyaning o‘ziga xos qiyofasi: nomi, logotipi, ranglari, shriftlari va umumiy uslubi. Hamma hujjatlar shu uslubda tayyorlansa, kompaniya tanilishi osonlashadi.</p>\n<h4>Brend elementlari</h4>\n<ul><li><b>Logotip</b> — kompaniya belgisi.</li><li><b>Rang palitrasi</b> — doimiy ishlatiladigan asosiy ranglar.</li><li><b>Shriftlar</b> — sarlavha va asosiy matn uchun belgilangan turlar.</li><li><b>Hujjat shablonlari</b> — tayyor maket: xat blanki, taqdimot, hisobot.</li></ul>\n<div class=\"ex\"><b>Amaliy qadamlar.</b><ol><li>Kompaniyaning brend qoidalarini aniqlang.</li><li>Shablon asosida yangi hujjat oching.</li><li>Logotip va ranglarni qoidaga muvofiq joylang.</li><li>Sarlavha va matnga belgilangan shriftni qo‘llang.</li><li>Hujjatni brend talabi bo‘yicha tekshiring.</li></ol></div>\n<p>Brend qoidalaridan chetga chiqmaslik kerak: logotipni cho‘zish, rangini o‘zgartirish yoki o‘zboshimcha shrift ishlatish uslubni buzadi.</p>\n<h4>Eslab qoling</h4><ul><li>Brend — logotip, ranglar, shrift va uslub birligi.</li><li>Shablon brend talabini tez bajarishga yordam beradi.</li><li>Hujjatlar bir xil uslubda bo‘lsa, kompaniya ishonchli ko‘rinadi.</li></ul>","quiz":[{"q":"Korporativ brend nima?","o":["Kompaniyaning logotip, rang va uslubdan iborat o‘ziga xos qiyofasi","Faqat kompaniya binosi","Kompyuter turi","Dasturlash tili"],"a":0,"e":"Brend nom, belgi, ranglar va uslub majmuasi."},{"q":"Quyidagilardan qaysi biri brend elementi emas?","o":["Korporativ shrift","Logotip","Fayl hajmi","Rang palitrasi"],"a":2,"e":"Fayl hajmi brend uslubiga kirmaydi."},{"q":"Shablon nima uchun kerak?","o":["Faylni arxivlash uchun","Internetga ulanish uchun","Hujjatni o‘chirish uchun","Hujjatni tayyor brend maketi asosida tez yaratish uchun"],"a":3,"e":"Shablon brend talablariga mos tayyor maketni beradi."},{"q":"Logotipni noto‘g‘ri ishlatish holatini toping.","o":["Uni asl nisbatda qo‘yish","Uni belgilangan joyda ishlatish","Uni qoidadagi rangda berish","Uni sahifaga mos qilib cho‘zib, nisbatini buzish"],"a":3,"e":"Logotip nisbati va ko‘rinishi o‘zgartirilmaydi."},{"q":"Kompaniya hujjatlari bir xil uslubda bo‘lishining foydasi nima?","o":["Fayl tezroq yuklanadi","Elektr sarfi kamayadi","Kompaniya tanilishi va ishonchi oshadi","Imlo xatosi yo‘qoladi"],"a":2,"e":"Izchil uslub brendni esda qolarli qiladi."},{"q":"Xodim xat tayyorlayapti. Eng to‘g‘ri harakat qaysi?","o":["Logotipsiz yuborish","Kompaniyaning xat blankidan foydalanish","O‘zi yoqtirgan shrift va rangni tanlash","Boshqa kompaniya logotipini qo‘yish"],"a":1,"e":"Brend blankidan foydalanish uslubni saqlaydi."},{"q":"Rang palitrasi nima?","o":["Sichqoncha tugmalari","Rasm formatlari ro‘yxati","Brend uchun belgilangan asosiy ranglar to‘plami","Printer turi"],"a":2,"e":"Palitra doimiy ishlatiladigan ranglarni belgilaydi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Brendga faqat sayt tegishli","Har bir hujjatda yangi shrift ishlatish shart","Brend qoidalari barcha hujjatlarda bajarilishi kerak","Logotip rangini xohlagancha o‘zgartirish mumkin"],"a":2,"e":"Qoidalar hamma hujjatga tegishli."},{"q":"Taqdimot brend uslubiga mosligini qanday tekshirasiz?","o":["Fayl kengaytmasini o‘zgartirib","Slaydlar sonini sanab","Logotip, rang va shrift qoidaga mosligini ko‘zdan kechirib","Faylni qayta nomlab"],"a":2,"e":"Tekshiruv asosiy brend elementlariga qaratiladi."},{"q":"Brend qoidalarida shrift nima uchun belgilanadi?","o":["Matn kamroq joy olishi uchun","Matn avtomatik yozilishi uchun","Kompyuter tezlashishi uchun","Hujjatlar bir xil ko‘rinishda bo‘lishi uchun"],"a":3,"e":"Bir xil shrift izchil uslub beradi."}]},{"t":"44-dars. Sahifa/slayd izchilligini ta‘minlash","lesson":"<p>Ko‘p sahifali hujjat yoki ko‘p slaydli taqdimotda <b>izchillik</b> — barcha sahifa yoki slaydlarda bir xil uslub, ranglar, shriftlar va elementlar joylashuvining saqlanishi. Izchil ish o‘qishga qulay va professional ko‘rinadi.</p>\n<h4>Izchillikni qanday ta’minlash mumkin</h4>\n<ul><li><b>Stillardan foydalanish</b> — sarlavha, asosiy matn uchun tayyor formatlash to‘plami.</li><li><b>Slayd andozasi (master)</b> — barcha slaydlarga tegishli fon, logotip, shrift.</li><li><b>Kolontitul</b> — har sahifada takrorlanuvchi ma’lumot.</li><li>Obyektlarni doim bir xil joyga qo‘yish va bir xil rang tanlash.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Taqdimotda har slayd sarlavhasi bir xil shriftda, bir xil o‘lchamda va bir joyda turadi. Andozada o‘zgartirish kiritilsa, barcha slaydlar yangilanadi.</div>\n<p>Bitta o‘zgartirishni har sahifaga qo‘lda kiritish o‘rniga stil yoki andoza o‘zgartiriladi: bu vaqtni tejaydi va xatoni kamaytiradi.</p>\n<h4>Eslab qoling</h4><ul><li>Izchillik — bir xil uslub butun hujjat bo‘ylab.</li><li>Stil va andoza izchillikning asosiy vositasi.</li><li>Haddan ortiq shrift va ranglar hujjatni chalkashtiradi.</li></ul>","quiz":[{"q":"Sahifa yoki slayd izchilligi nima?","o":["Har sahifaga turlicha dizayn berish","Barcha sahifalarda bir xil uslub va joylashuvning saqlanishi","Sahifalar sonini ko‘paytirish","Faqat rasm qo‘yish"],"a":1,"e":"Izchillik — uslub birligi."},{"q":"Taqdimotda izchillikni ta’minlovchi asosiy vosita qaysi?","o":["Antivirus","Sichqoncha","Printer","Slayd andozasi"],"a":3,"e":"Andoza barcha slaydlar umumiy ko‘rinishini boshqaradi."},{"q":"Stil nima?","o":["Fayl nomi","Foydalanuvchi paroli","Faqat rasm turi","Tayyor formatlash parametrlari to‘plami"],"a":3,"e":"Stil shrift, o‘lcham, tekislash kabilarni birlashtiradi."},{"q":"Hamma sarlavhaning ko‘rinishini birdaniga o‘zgartirish uchun nima qilinadi?","o":["Sarlavhalar o‘chiriladi","Sarlavha stilini o‘zgartiriladi","Hujjat qayta yoziladi","Har sarlavhani alohida tahrirlanadi"],"a":1,"e":"Stil o‘zgarsa, shu stildagi barcha matn yangilanadi."},{"q":"Quyidagilardan qaysi biri izchillikni buzadi?","o":["Bir xil shrift ishlatish","Har slaydda boshqa shrift va rang ishlatish","Sarlavhani doim bir joyga qo‘yish","Andozadan foydalanish"],"a":1,"e":"Turli shrift va ranglar uslubni buzadi."},{"q":"Slayd andozasiga logotip qo‘yilsa nima bo‘ladi?","o":["Faqat oxirgi slaydda ko‘rinadi","Hech qayerda ko‘rinmaydi","U barcha slaydlarda ko‘rinadi","Faqat birinchi slaydda ko‘rinadi"],"a":2,"e":"Andozadagi element barcha slaydlarga tushadi."},{"q":"Qo‘lda formatlash o‘rniga stil ishlatishning afzalligi nima?","o":["Fayl hajmi kamayadi","Vaqt tejaladi va xato kamayadi","Matn tarjima bo‘ladi","Internet tezlashadi"],"a":1,"e":"Stil bitta o‘zgartirish bilan hamma joyni yangilaydi."},{"q":"To‘g‘ri mulohazani toping.","o":["Hujjatda ko‘p shrift ishlatish uning o‘qilishini qiyinlashtiradi","Izchillik faqat taqdimotlarga tegishli","Shrift qancha ko‘p bo‘lsa, shuncha yaxshi","Stil faqat jadvalda ishlaydi"],"a":0,"e":"Haddan ortiq shrift chalkashlik keltiradi."},{"q":"Qaysi element har sahifada takrorlanib izchillikka yordam beradi?","o":["Kolontitul","Imlo lug‘ati","Hoshiya o‘lchovi","Fayl kengaytmasi"],"a":0,"e":"Kolontitul har sahifada bir xil chiqadi."},{"q":"Hisobotning 10 ta bo‘limi sarlavhalari turlicha ko‘rinyapti. Eng to‘g‘ri yechim?","o":["Rangini tasodifiy tanlash","Barcha sarlavhalarga bitta sarlavha stilini qo‘llash","Har birini qo‘lda o‘lchamini tuzatish","Sarlavhalarni o‘chirish"],"a":1,"e":"Yagona stil birlikni ta’minlaydi."}]},{"t":"45-dars. Yangi stil yaratish","lesson":"<p>Dasturda tayyor stillar yetarli bo‘lmasa, <b>yangi stil</b> yaratish mumkin. Stil — shrift, o‘lcham, rang, tekislash, qator oralig‘i va boshqa parametrlarni bir nom ostida saqlaydigan to‘plam.</p>\n<h4>Yangi stil yaratish tartibi</h4>\n<ol><li>Namuna sifatida matn parchasini kerakli ko‘rinishga keltiring yoki stillar bo‘limidan yangisini boshlang.</li><li>Stilga ma’noli <b>nom</b> bering, masalan, “Bo‘lim sarlavhasi”.</li><li>Shrift, o‘lcham, rang, abzats parametrlarini belgilang.</li><li>Stilni saqlang.</li><li>Kerakli matnga stilni qo‘llang.</li></ol>\n<div class=\"ex\"><b>Misol.</b> “Izoh” stili: shrift o‘lchami kichikroq, kursiv, kulrang. Uni barcha rasm izohlariga qo‘llash uchun har safar formatlash shart emas.</div>\n<p>Stil boshqa stilga asoslanishi mumkin. Asos stil o‘zgarsa, unga tayanuvchi stillar ham o‘zgaradi. Stilni keyin tahrirlash mumkin: o‘zgartirish shu stildagi barcha matnga ta’sir qiladi.</p>\n<h4>Eslab qoling</h4><ul><li>Yangi stil nomi va parametrlar to‘plamidan iborat.</li><li>Stilni qo‘llash — vaqtni tejaydi.</li><li>Stilni tahrirlash barcha bog‘liq matnni yangilaydi.</li></ul>","quiz":[{"q":"Yangi stil nimani saqlaydi?","o":["Formatlash parametrlari to‘plamini bir nom ostida","Faqat rasmni","Faqat matn mazmunini","Fayl parolini"],"a":0,"e":"Stil shrift, rang, abzats kabi sozlamalarni saqlaydi."},{"q":"Yangi stilga nima berilishi shart?","o":["Parol","Sana","Nom","Rasm"],"a":2,"e":"Stilni topish va qo‘llash uchun nom kerak."},{"q":"Yangi stil qachon foydali?","o":["Faqat faylni yopishda","Hech qachon","Faqat jadval yaratishda","Tayyor stillar talabni qoplamaganda"],"a":3,"e":"Maxsus talab bo‘lsa, o‘z stilingizni yaratasiz."},{"q":"Stilni qo‘llash nimaga yordam beradi?","o":["Xatolarni o‘chirishga","Bir xil formatni ko‘p joyga tez berishga","Matnni tarjima qilishga","Faylni siqishga"],"a":1,"e":"Stil formatlashni takrorlamaslikka imkon beradi."},{"q":"Stil parametri tahrirlansa, shu stildagi matn nima bo‘ladi?","o":["Faqat birinchisi o‘zgaradi","Hammasi birdaniga yangilanadi","Hech narsa o‘zgarmaydi","Matn o‘chib ketadi"],"a":1,"e":"Stil o‘zgarsa, unga bog‘liq barcha matn yangilanadi."},{"q":"Quyidagilarning qaysi biri stil parametriga kirmaydi?","o":["Qator oralig‘i","Matn rangi","Foydalanuvchi IP manzili","Shrift o‘lchami"],"a":2,"e":"IP manzil stilga aloqador emas."},{"q":"Yangi stil yaratishda qaysi qadam birinchi keladi?","o":["Faylni bosib chiqarish","Namuna matnni formatlash yoki yangi stilni boshlash","Hujjatni o‘chirish","Dasturni yopish"],"a":1,"e":"Avval ko‘rinish belgilanadi, keyin nom beriladi va saqlanadi."},{"q":"Rasm izohlari uchun “Izoh” stili yaratildi. Uni qanday qo‘llaysiz?","o":["Izohlarni o‘chirish","Har bir izohni tanlab, shu stilni tanlash","Hujjatni qayta nomlash","Har safar shrift va rangni qo‘lda yozish"],"a":1,"e":"Tayyor stilni tanlash bir amalda formatlaydi."},{"q":"Stilga ma’noli nom berish nima uchun yaxshi?","o":["Rang o‘zgarishi uchun","Kerakli stilni osongina topish va tushunish uchun","Dastur tezlashishi uchun","Fayl hajmini kamaytirish uchun"],"a":1,"e":"Tushunarli nom ish qulayligini oshiradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Stil boshqa stilga asoslanishi mumkin","Stil faqat rasmlarga qo‘llanadi","Stilni hech qachon o‘zgartirib bo‘lmaydi","Stil faqat bir marta ishlatiladi"],"a":0,"e":"Asos stil o‘zgarsa, unga tayanuvchi stillar ham o‘zgaradi."}]},{"t":"46-dars. Xatolarni tekshirish uchun dasturlardan foydalanish","lesson":"<p>Ma’lumot bilan ishlaganda xato yuz berishi tabiiy: noto‘g‘ri kiritilgan raqam, imloviy xato, noto‘g‘ri formula. Xatolarni topish va tuzatish uchun maxsus dasturiy vositalar mavjud. Ular ishni tezlashtiradi va natija ishonchliligini oshiradi.</p>\n<h4>Matn bilan ishlashda</h4>\n<ul><li>Imlo va grammatikani tekshirish — xato so‘zlar chiziq bilan ajratiladi.</li>\n<li>Matn muharririda qidirish va almashtirish vositasi.</li></ul>\n<h4>Elektron jadvalda</h4>\n<ul><li>Formulalardagi xatolar maxsus belgi yoki xabar bilan ko‘rsatiladi.</li>\n<li>Ma’lumot turi cheklovlari: masalan, faqat son kiritishga ruxsat berish.</li>\n<li>Takrorlanuvchi yozuvlarni topish.</li></ul>\n<h4>Dasturlashda</h4>\n<ul><li>Dastur tahrirlagichi sintaksis xatolarini ko‘rsatadi.</li>\n<li>Sinov va tuzatish vositalari ishlatiladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Matn muharririda xato yozilgan so‘z qizil to‘lqinsimon chiziq bilan belgilanadi. Uning ustiga bosib tavsiya etilgan variantni tanlash mumkin.</div>\n<p>Shuningdek, ko‘p dasturlarda avtomatik saqlash va oldingi holatga qaytarish (bekor qilish) imkoniyati bor. Bu tasodifiy xatoni tezda tuzatishga yordam beradi. Ishni boshlashdan oldin ma’lumotlarni tekshirishni odat qiling.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Dasturlar xatoni topishga yordam beradi, lekin yakuniy tekshiruv insonda.</li><li>Tekshirish vositalaridan muntazam foydalaning.</li></ul>","quiz":[{"q":"Imlo tekshirgichning vazifasi nima?","o":["Matndagi xato so‘zlarni topish","Faylni arxivlash","Videoni kesish","Rasm chizish"],"a":0,"e":"Imloni tekshiradi."},{"q":"Elektron jadvalda formula xatosi qanday bildiriladi?","o":["Maxsus xabar yoki belgi bilan","Fayl o‘chadi","Ekran o‘chadi","Hech narsa bildirilmaydi"],"a":0,"e":"Xato ko‘rsatiladi."},{"q":"Faqat son kiritishga ruxsat berish qaysi vositaga misol?","o":["Faylni arxivlash","Rasm tahrirlash","Chop etish","Ma’lumotlarni cheklash orqali xatoning oldini olish"],"a":3,"e":"Noto‘g‘ri tur kiritilmaydi."},{"q":"Dasturlash tahrirlagichi nimani ko‘rsatadi?","o":["Internet tezligini","Printer holatini","Fayl rangini","Sintaksis xatolarini"],"a":3,"e":"Kod xatolari."},{"q":"Vaziyat: jadvalda yig‘indi noto‘g‘ri chiqdi. Nima qilish kerak?","o":["Natijaga ishonish","Jadvalni o‘chirish","Kompyuterni almashtirish","Formula va kiritilgan ma’lumotlarni tekshirish"],"a":3,"e":"Manba xatoni topadi."},{"q":"Takrorlanuvchi yozuvlarni topish nima uchun foydali?","o":["Parol uchun","Faylni kattalashtirish uchun","Ma’lumotdagi ortiqcha nusxalarni aniqlash uchun","Rangni o‘zgartirish uchun"],"a":2,"e":"Ortiqchalar xatoga olib keladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Dastur tekshiruvidan so‘ng ham natijani o‘zingiz tekshirishingiz kerak","Xato hech qachon bo‘lmaydi","Dastur doim hamma xatoni topadi","Tekshirish keraksiz"],"a":0,"e":"Dastur ham xato qilishi mumkin."},{"q":"Matn muharririda xato so‘z qanday belgilanadi?","o":["Fayl yopiladi","Chiziq bilan ajratiladi","Rangi yo‘qoladi","O‘chib ketadi"],"a":1,"e":"Odatda to‘lqinsimon chiziq."},{"q":"Qidirish va almashtirish vositasi nimaga yordam beradi?","o":["Ovozni kuchaytirishga","Bir xil xatoni butun hujjatda tuzatishga","Rasmni kesishga","Faylni siqishga"],"a":1,"e":"Ko‘p joyda tuzatadi."},{"q":"Xatoni topish dasturlari ishlatilishining sababi?","o":["Ishni murakkablashtirish","Hajmni oshirish","Xato yaratish","Vaqtni tejash va ishonchlilikni oshirish"],"a":3,"e":"Samaradorlik."}]},{"t":"47-dars. Xatolarni tekshirish usullari","lesson":"<p>Xatolarni tekshirish uchun turli usullar qo‘llaniladi. Xato odam e’tiborsizligi, noto‘g‘ri kiritish yoki dastur nuqsoni tufayli paydo bo‘lishi mumkin. Maqsad — ma’lumot to‘g‘ri, to‘liq va mantiqan mosligini ta’minlash.</p>\n<h4>Tekshirish usullari</h4>\n<ul><li><b>Vizual tekshirish</b> — ma’lumotni ko‘z bilan qayta o‘qib chiqish.</li>\n<li><b>Ikki marta kiritish</b> — ma’lumot ikki marta kiritilib, mosligi solishtiriladi.</li>\n<li><b>Nazorat yig‘indisi</b> — yig‘indini qo‘lda yoki boshqa usulda hisoblab solishtirish.</li>\n<li><b>Diapazon tekshiruvi</b> — qiymat ruxsat etilgan oraliqda ekanini tekshirish (masalan, baho 2 dan 5 gacha).</li>\n<li><b>Format tekshiruvi</b> — sana yoki telefon raqami to‘g‘ri shaklda yozilganini tekshirish.</li>\n<li><b>Sinov</b> — dasturni turli ma’lumotlar bilan ishga tushirib ko‘rish.</li></ul>\n<div class=\"ex\"><b>Misol.</b> O‘quvchi yoshi maydoniga 250 yozildi. Diapazon tekshiruvi bu qiymatni qabul qilmaydi, chunki u mantiqan mumkin emas.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Bir necha usulni birga qo‘llash ishonchlilikni oshiradi.</li><li>Kiritishdagi xatolarni imkon qadar kirituvchi bosqichdayoq to‘xtating.</li></ul>","quiz":[{"q":"Diapazon tekshiruvi nima?","o":["Matnni chop etish","Qiymat ruxsat etilgan oraliqda ekanini tekshirish","Faylni siqish","Parolni o‘zgartirish"],"a":1,"e":"Oraliq tekshiriladi."},{"q":"Baho maydoniga 12 kiritilsa (baho 2 dan 5 gacha), qaysi tekshiruv xatoni topadi?","o":["Formatlash","Diapazon tekshiruvi","Arxivlash","Rang tanlash"],"a":1,"e":"Oraliqdan chiqdi."},{"q":"Ikki marta kiritish usulining mohiyati nima?","o":["Faqat nusxa olinadi","Ma’lumot o‘chiriladi","Ma’lumot ikki marta kiritilib, mosligi solishtiriladi","Bir marta yoziladi"],"a":2,"e":"Moslik xatoni ko‘rsatadi."},{"q":"Format tekshiruvi nimani tekshiradi?","o":["Faylning hajmini","Ekran o‘lchamini","Ma’lumot to‘g‘ri shaklda yozilganini","Printer turini"],"a":2,"e":"Masalan, sana shakli."},{"q":"Vizual tekshirish nima?","o":["Avtomatik arxivlash","Parol kiritish","Ma’lumotni ko‘z bilan qayta o‘qib chiqish","Faylni yuborish"],"a":2,"e":"Qo‘lda ko‘rish."},{"q":"Nazorat yig‘indisi nimaga xizmat qiladi?","o":["Hisoblangan yig‘indini solishtirib xatoni aniqlashga","Fayl nomini berishga","Rasmni bo‘yashga","Internetni ulashga"],"a":0,"e":"Yig‘indi mos kelmasa, xato bor."},{"q":"Vaziyat: telefon raqami maydoniga harflar yozildi. Qaysi tekshiruv aniqlaydi?","o":["Arxivlash","Nusxalash","Rangni tekshirish","Format tekshiruvi"],"a":3,"e":"Raqam shakli buzilgan."},{"q":"Dasturni turli ma’lumotlar bilan ishga tushirib ko‘rish nima deyiladi?","o":["Sinov","Formatlash","Chop etish","Arxivlash"],"a":0,"e":"Sinov xatoni ochadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Bir necha usulni birga qo‘llash ishonchlilikni oshiradi","Xato faqat dasturda bo‘ladi","Tekshirish xatoni ko‘paytiradi","Bitta usul doim yetarli"],"a":0,"e":"Qo‘shimcha himoya."},{"q":"Yosh maydoniga 250 yozilishi qaysi tekshiruvda to‘xtatiladi?","o":["Diapazon tekshiruvi","Rang tekshiruvi","Shrift tekshiruvi","Faylni arxivlash"],"a":0,"e":"Qiymat oraliqdan tashqarida."}]},{"t":"48-dars. Verifikatsiya va validatsiya tuhsunchalari","lesson":"<p>Ma’lumot sifatini ta’minlashda ikki muhim tushuncha qo‘llaniladi: verifikatsiya va validatsiya. Ular o‘xshash eshitilsa-da, ma’nosi har xil. Ikkalasi ham xato va noto‘g‘ri natijalarning oldini olishga xizmat qiladi.</p>\n<h4>Verifikatsiya</h4>\n<ul><li>Ma’lumot yoki mahsulot qoidaga, spetsifikatsiyaga yoki manbaga mosligini tekshirish: “To‘g‘ri qilinganmi?”</li>\n<li>Misol: kiritilgan ma’lumotni asl hujjat bilan solishtirish.</li></ul>\n<h4>Validatsiya</h4>\n<ul><li>Ma’lumot yoki mahsulot maqsadga va foydalanuvchi ehtiyojiga mos, mantiqan maqbul ekanini tekshirish: “To‘g‘ri narsa qilinganmi?”</li>\n<li>Misol: yosh maydonida manfiy son yoki juda katta qiymat qabul qilinmasligi.</li></ul>\n<h4>Farqi</h4>\n<ul><li>Verifikatsiya — manbaga mosligi, validatsiya — ma’lumot qabul qilinadigan va mantiqli ekanligi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Elektron jadvalga kiritilgan o‘quvchi ismlari ro‘yxatni asl ro‘yxat bilan solishtiriladi — bu verifikatsiya. Baho maydoniga faqat 2 dan 5 gacha son kiritishga ruxsat berilishi — validatsiya.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Verifikatsiya — manbaga mosligi.</li><li>Validatsiya — mantiqiy qabul qilinishi va maqsadga mosligi.</li></ul>","quiz":[{"q":"Verifikatsiya nimani tekshiradi?","o":["Ma’lumotning manbaga yoki qoidaga mosligini","Faylning rangini","Tarmoq tezligini","Faqat ekranni"],"a":0,"e":"Moslik tekshiriladi."},{"q":"Validatsiya nimani tekshiradi?","o":["Faqat hajmini","Printerning rangini","Ma’lumotning mantiqan maqbul va maqsadga mosligini","Faylning nomini"],"a":2,"e":"Qabul qilinish tekshiriladi."},{"q":"Kiritilgan ma’lumotni asl hujjat bilan solishtirish qaysi tushunchaga misol?","o":["Formatlash","Validatsiya","Arxivlash","Verifikatsiya"],"a":3,"e":"Manbaga moslik."},{"q":"Baho maydoniga faqat 2 dan 5 gacha son kiritishga ruxsat berish nimaga misol?","o":["Validatsiya","Siqish","Shifrlash","Verifikatsiya"],"a":0,"e":"Mantiqiy qabul."},{"q":"Yosh maydoniga manfiy son kiritilishining oldini olish qaysi tushuncha?","o":["Arxivlash","Validatsiya","Chop etish","Nusxalash"],"a":1,"e":"Qiymat mantiqsiz."},{"q":"Ikki marta kiritib solishtirish qaysi tushunchaga yaqin?","o":["Montaj","Verifikatsiya","Animatsiya","Dasturlash"],"a":1,"e":"Moslik tekshiriladi."},{"q":"Vaziyat: operator ismlarni qo‘lda kiritdi va yana asl ro‘yxat bilan tekshirdi. U nima qildi?","o":["Verifikatsiya qildi","Formatladi","Arxivladi","Validatsiya qilmadi faqat"],"a":0,"e":"Manba bilan solishtirdi."},{"q":"Ikkala tushuncha umumiy maqsadi nima?","o":["Dasturni sekinlashtirish","Faylni kattalashtirish","Xato va noto‘g‘ri ma’lumotning oldini olish","Ma’lumotni ko‘paytirish"],"a":2,"e":"Sifat uchun."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Verifikatsiya va validatsiya bir xil emas, lekin bir-birini to‘ldiradi","Ular aynan bir xil","Faqat bittasi kerak, ikkinchisi zararli","Ular hech qachon ishlatilmaydi"],"a":0,"e":"Ikkalasi ham kerak."},{"q":"Telefon raqamiga harf kiritilishining oldini oladigan tekshiruv qaysi turga kiradi?","o":["Skanerlash","Validatsiya","Arxivlash","Montaj"],"a":1,"e":"Ruxsat etilgan qiymatlar."}]},{"t":"49-dars. Grafik yoki diagramma yaratish. Diagramma turlari","lesson":"<p>Diagramma va grafik ma’lumotlarni ko‘rgazmali shaklda ko‘rsatish usulidir. Raqamlar jadvali o‘rniga rasm ko‘rinishidagi tasvir ma’lumotlarni solishtirish va o‘zgarishlarni tushunishni osonlashtiradi. Diagramma odatda elektron jadvalda tayyorlanadi.</p>\n<h4>Diagramma yaratish tartibi</h4>\n<ul><li>OL:Ma’lumotlarni jadvalga kiriting.|Kerakli katak oralig‘ini belgilang.|Diagramma qo‘shish buyrug‘ini tanlang.|Diagramma turini tanlang.|Sarlavha va yozuvlarni qo‘shing.</li></ul>\n<h4>Diagramma turlari</h4>\n<ul><li><b>Ustunli (gistogramma)</b> — qiymatlarni solishtirish.</li>\n<li><b>Doiraviy</b> — butunning qismlarini ko‘rsatish (foiz ulushi).</li>\n<li><b>Chiziqli (grafik)</b> — vaqt bo‘yicha o‘zgarishni ko‘rsatish.</li>\n<li><b>Nuqtali</b> — ikki kattalik bog‘liqligini ko‘rsatish.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Sinfdagi o‘quvchilarning baholar bo‘yicha taqsimotini doiraviy diagramma ko‘rsatadi, oylar bo‘yicha o‘rtacha bahoning o‘zgarishini esa chiziqli grafik yaxshiroq ifodalaydi.</div>\n<p>Diagramma ma’lumotni tushunishni yengillashtiradi: ko‘pincha bir qarashda eng katta va eng kichik qiymatni, tendensiyani ko‘rish mumkin. Ortiqcha rang va bezaklardan saqlaning, chunki ular diagramma o‘qilishini qiyinlashtiradi. Ma’lumot yorlig‘i qo‘shish aniq qiymatlarni ko‘rsatadi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Diagramma turi ma’lumot xarakteriga mos bo‘lsin.</li><li>Diagrammaga sarlavha va izoh qo‘shing.</li></ul>","quiz":[{"q":"Diagramma nima uchun ishlatiladi?","o":["Ma’lumotlarni ko‘rgazmali ko‘rsatish uchun","Faylni arxivlash uchun","Virus topish uchun","Tovushni yozish uchun"],"a":0,"e":"Ko‘rgazmalilik."},{"q":"Qiymatlarni solishtirishga qaysi diagramma qulay?","o":["Fayl","Ovozli","Ustunli","Matnli"],"a":2,"e":"Ustunlar taqqoslanadi."},{"q":"Butunning qismlarini foizda ko‘rsatish uchun qaysi diagramma mos?","o":["Ustunli faqat","Doiraviy","Chiziqli","Nuqtali"],"a":1,"e":"Ulushlar uchun."},{"q":"Vaqt davomida o‘zgarishni ko‘rsatish uchun qaysi tur qulay?","o":["Doiraviy","Matnli","Rasm","Chiziqli grafik"],"a":3,"e":"Tendensiya."},{"q":"Diagramma yaratishdan oldin nimani tayyorlash kerak?","o":["Faylni o‘chirishni","Ma’lumotlar jadvalini","Parol qo‘yishni","Printerni"],"a":1,"e":"Ma’lumot asos."},{"q":"Quyidagi qadamlarning to‘g‘ri tartibi qaysi?","o":["Tur tanlash, o‘chirish, kiritish","Belgilash, o‘chirish, yopish","Ma’lumot kiritish, oraliq belgilash, diagramma turini tanlash","Chop etish, kiritish, belgilash"],"a":2,"e":"Ma’lumot birinchi."},{"q":"Vaziyat: 5 ta mahsulotning sotilgan sonini solishtirmoqchisiz. Qaysi diagramma mos?","o":["Ustunli","Faqat chiziqli vaqtsiz","Rasmli matn","Hech qaysi"],"a":0,"e":"Solishtirish uchun."},{"q":"Sarlavha va o‘q nomlari nima uchun qo‘shiladi?","o":["Diagramma nimani ko‘rsatishi tushunarli bo‘lishi uchun","Hajmni oshirish uchun","Parol uchun","Rangni o‘zgartirish uchun"],"a":0,"e":"Tushunarlilik."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Hamma ma’lumotga bitta tur mos","Diagramma matn yozadi","Diagramma faqat chop etiladi","Diagramma turini ma’lumot xarakteriga qarab tanlash kerak"],"a":3,"e":"Mos tur."},{"q":"Ikki kattalik orasidagi bog‘liqlikni ko‘rsatishga qaysi tur mos?","o":["Ovozli","Nuqtali","Matnli","Doiraviy"],"a":1,"e":"Nuqtalar bog‘liqlikni ko‘rsatadi."}]},{"t":"50-dars. Tayyorlangan diagrammani boshqarish va o‘zgartirish","lesson":"<p>Tayyor diagramma yaratilgandan keyin ham uni tahrirlash va sozlash mumkin. Diagrammani belgilash orqali uning turini, ranglarini, yozuvlarini, o‘lchamini va manba ma’lumotlarini o‘zgartirish imkoni paydo bo‘ladi. Elektron jadvaldagi ma’lumot o‘zgarsa, diagramma ham mos ravishda yangilanadi.</p>\n<h4>Diagrammani boshqarish</h4>\n<ul><li>Diagrammani sichqoncha bilan belgilash va ko‘chirish.</li>\n<li>Chegara tutqichlari yordamida o‘lchamini o‘zgartirish.</li>\n<li>Diagramma turini boshqasiga almashtirish.</li>\n<li>Sarlavha, o‘q nomlari va legendani qo‘shish yoki tahrirlash.</li>\n<li>Ranglar va stilni o‘zgartirish.</li></ul>\n<h4>Ma’lumotlarni yangilash</h4>\n<ul><li>Manba jadvalidagi qiymatni o‘zgartirsangiz, diagramma avtomatik yangilanadi.</li>\n<li>Ma’lumot oralig‘ini kengaytirish yoki qisqartirish mumkin.</li>\n<li>Diagrammani boshqa hujjat yoki taqdimotga joylash mumkin.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Ustunli diagramma noqulay bo‘lib qolsa, uni doiraviy turga almashtirib ko‘ring. Ma’lumotlarni qayta kiritish shart emas.</div>\n<p>Taqdimot yoki hujjatga joylashtirishdan oldin diagrammani yana bir bor tekshiring: yozuvlar o‘qilarlimi, ranglar farqlanyaptimi, birliklar ko‘rsatilganmi. Shu tarzda tayyor diagramma tinglovchiga fikrni aniq yetkazadi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Diagramma jadval ma’lumotiga bog‘langan.</li><li>Tur, rang va yozuvlarni qulay qilib sozlang.</li></ul>","quiz":[{"q":"Diagramma turini keyin o‘zgartirish mumkinmi?","o":["Ha, ma’lumotlarni qayta kiritmasdan","Faqat yangi fayl yaratib","Yo‘q, hech qachon","Faqat chop etgandan keyin"],"a":0,"e":"Tur almashtiriladi."},{"q":"Jadvaldagi qiymat o‘zgarsa, diagramma nima bo‘ladi?","o":["O‘zgarmaydi","Avtomatik yangilanadi","O‘chadi","Faqat qo‘lda yangilanadi"],"a":1,"e":"Bog‘langan."},{"q":"Legenda nima?","o":["Diagramma elementlarining belgilar izohi","Diagramma sarlavhasi","Ustun balandligi","Faylning nomi"],"a":0,"e":"Izoh."},{"q":"Diagramma o‘lchamini o‘zgartirish uchun nima qilinadi?","o":["Printerni almashtirish","Belgilab, chegara tutqichlarini sudrash","Faylni o‘chirish","Parol qo‘yish"],"a":1,"e":"Tutqich."},{"q":"Diagramma sarlavhasi nima uchun kerak?","o":["Nimani ko‘rsatishini bildirish uchun","Fayl nomini o‘zgartirish uchun","Parol uchun","Kenglikni oshirish uchun"],"a":0,"e":"Mazmunni bildiradi."},{"q":"Vaziyat: ustunli diagrammada foizlar qulay ko‘rinmayapti. Nima qilish mumkin?","o":["Printerni yoqish","Jadvalni yo‘q qilish","Doiraviy turga almashtirish","Diagrammani o‘chirib tashlash"],"a":2,"e":"Ulush uchun doiraviy."},{"q":"Diagrammani tahrirlash uchun avval nima qilinadi?","o":["Kompyuterni o‘chirish","Parolni kiritish","Uni sichqoncha bilan belgilash","Faylni yopish"],"a":2,"e":"Belgilash shart."},{"q":"Ma’lumot oralig‘ini o‘zgartirish nimaga imkon beradi?","o":["Faylni arxivlash","Internetga ulanish","Tovushni o‘zgartirish","Diagrammaga yangi qiymatlarni qo‘shish yoki chiqarish"],"a":3,"e":"Manba o‘zgaradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Diagramma rangini o‘zgartirib bo‘lmaydi","Diagrammani boshqa hujjatga joylash mumkin","Diagrammani nusxalab bo‘lmaydi","Diagramma faqat jadvalda qoladi"],"a":1,"e":"Ko‘chirish mumkin."},{"q":"Diagramma ranglarini o‘zgartirishdan maqsad nima?","o":["Fayl hajmini kamaytirish","Ma’lumotni o‘chirish","Parolni qo‘yish","Ko‘rinishni yaxshilash va elementlarni ajratish"],"a":3,"e":"Ko‘rgazmalilik."}]},{"t":"51-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 6</b> quyidagi darslarni qamrab oladi:</p><ul><li>Korporativ brend va unga xos stil. Korporativ brendga xos stilga muvofiq hujjat tayyorlash</li><li>Sahifa/slayd izchilligini ta‘minlash</li><li>Yangi stil yaratish</li><li>Xatolarni tekshirish uchun dasturlardan foydalanish</li><li>Xatolarni tekshirish usullari</li><li>Verifikatsiya va validatsiya tuhsunchalari</li><li>Grafik yoki diagramma yaratish. Diagramma turlari</li><li>Tayyorlangan diagrammani boshqarish va o‘zgartirish</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Diagramma sarlavhasi nima uchun kerak?","o":["Nimani ko‘rsatishini bildirish uchun","Fayl nomini o‘zgartirish uchun","Parol uchun","Kenglikni oshirish uchun"],"a":0,"e":"Mazmunni bildiradi."},{"q":"Butunning qismlarini foizda ko‘rsatish uchun qaysi diagramma mos?","o":["Ustunli faqat","Doiraviy","Chiziqli","Nuqtali"],"a":1,"e":"Ulushlar uchun."},{"q":"Yangi stil yaratishda qaysi qadam birinchi keladi?","o":["Faylni bosib chiqarish","Namuna matnni formatlash yoki yangi stilni boshlash","Hujjatni o‘chirish","Dasturni yopish"],"a":1,"e":"Avval ko‘rinish belgilanadi, keyin nom beriladi va saqlanadi."},{"q":"Validatsiya nimani tekshiradi?","o":["Faqat hajmini","Printerning rangini","Ma’lumotning mantiqan maqbul va maqsadga mosligini","Faylning nomini"],"a":2,"e":"Qabul qilinish tekshiriladi."},{"q":"Kompaniya hujjatlari bir xil uslubda bo‘lishining foydasi nima?","o":["Fayl tezroq yuklanadi","Elektr sarfi kamayadi","Kompaniya tanilishi va ishonchi oshadi","Imlo xatosi yo‘qoladi"],"a":2,"e":"Izchil uslub brendni esda qolarli qiladi."},{"q":"Ikki kattalik orasidagi bog‘liqlikni ko‘rsatishga qaysi tur mos?","o":["Ovozli","Nuqtali","Matnli","Doiraviy"],"a":1,"e":"Nuqtalar bog‘liqlikni ko‘rsatadi."},{"q":"Yangi stil nimani saqlaydi?","o":["Formatlash parametrlari to‘plamini bir nom ostida","Faqat rasmni","Faqat matn mazmunini","Fayl parolini"],"a":0,"e":"Stil shrift, rang, abzats kabi sozlamalarni saqlaydi."},{"q":"Dasturni turli ma’lumotlar bilan ishga tushirib ko‘rish nima deyiladi?","o":["Sinov","Formatlash","Chop etish","Arxivlash"],"a":0,"e":"Sinov xatoni ochadi."},{"q":"Taqdimot brend uslubiga mosligini qanday tekshirasiz?","o":["Fayl kengaytmasini o‘zgartirib","Slaydlar sonini sanab","Logotip, rang va shrift qoidaga mosligini ko‘zdan kechirib","Faylni qayta nomlab"],"a":2,"e":"Tekshiruv asosiy brend elementlariga qaratiladi."},{"q":"Vaziyat: operator ismlarni qo‘lda kiritdi va yana asl ro‘yxat bilan tekshirdi. U nima qildi?","o":["Verifikatsiya qildi","Formatladi","Arxivladi","Validatsiya qilmadi faqat"],"a":0,"e":"Manba bilan solishtirdi."},{"q":"Matn muharririda xato so‘z qanday belgilanadi?","o":["Fayl yopiladi","Chiziq bilan ajratiladi","Rangi yo‘qoladi","O‘chib ketadi"],"a":1,"e":"Odatda to‘lqinsimon chiziq."},{"q":"Diapazon tekshiruvi nima?","o":["Matnni chop etish","Qiymat ruxsat etilgan oraliqda ekanini tekshirish","Faylni siqish","Parolni o‘zgartirish"],"a":1,"e":"Oraliq tekshiriladi."},{"q":"Logotipni noto‘g‘ri ishlatish holatini toping.","o":["Uni asl nisbatda qo‘yish","Uni belgilangan joyda ishlatish","Uni qoidadagi rangda berish","Uni sahifaga mos qilib cho‘zib, nisbatini buzish"],"a":3,"e":"Logotip nisbati va ko‘rinishi o‘zgartirilmaydi."},{"q":"Legenda nima?","o":["Diagramma elementlarining belgilar izohi","Diagramma sarlavhasi","Ustun balandligi","Faylning nomi"],"a":0,"e":"Izoh."},{"q":"To‘g‘ri mulohazani toping.","o":["Hujjatda ko‘p shrift ishlatish uning o‘qilishini qiyinlashtiradi","Izchillik faqat taqdimotlarga tegishli","Shrift qancha ko‘p bo‘lsa, shuncha yaxshi","Stil faqat jadvalda ishlaydi"],"a":0,"e":"Haddan ortiq shrift chalkashlik keltiradi."},{"q":"Qiymatlarni solishtirishga qaysi diagramma qulay?","o":["Fayl","Ovozli","Ustunli","Matnli"],"a":2,"e":"Ustunlar taqqoslanadi."},{"q":"Qaysi element har sahifada takrorlanib izchillikka yordam beradi?","o":["Kolontitul","Imlo lug‘ati","Hoshiya o‘lchovi","Fayl kengaytmasi"],"a":0,"e":"Kolontitul har sahifada bir xil chiqadi."},{"q":"Stil nima?","o":["Fayl nomi","Foydalanuvchi paroli","Faqat rasm turi","Tayyor formatlash parametrlari to‘plami"],"a":3,"e":"Stil shrift, o‘lcham, tekislash kabilarni birlashtiradi."},{"q":"Yangi stilga nima berilishi shart?","o":["Parol","Sana","Nom","Rasm"],"a":2,"e":"Stilni topish va qo‘llash uchun nom kerak."},{"q":"Elektron jadvalda formula xatosi qanday bildiriladi?","o":["Maxsus xabar yoki belgi bilan","Fayl o‘chadi","Ekran o‘chadi","Hech narsa bildirilmaydi"],"a":0,"e":"Xato ko‘rsatiladi."}]},{"t":"52-dars. Takrorlash","lesson":"<p><b>Takrorlash</b> quyidagi darslarni qamrab oladi:</p><ul><li>Kompyuter qurilmalari va dasturiy ta‘minot. Kompyuter tizimining asosiy komponentlari</li><li>Operatsion tizimlar</li><li>Kompyuter turlari</li><li>Yangi texnologiyalarning ta‘siri</li><li>Kiritish qurilmalari va ularning qo‘llanishi</li><li>Ma‘lumotni bevosita kiritishda foydalaniladigan qurilmalar.</li><li>Chiqarish qurilmalari va ulardan foydalanish</li><li>Xotira qurilmalari va ma‘lumot almashish vositalari</li><li>Turli xotira qurilmalarining afzallik va kamchiliklari</li><li>Xotira hajmiga bog‘liq masalalarni yechish</li><li>Kompyuter tarmoqlari qurilmalari</li><li>Brauzerdan foydalanish. Kompyuter tarmoqlari dasturiy jihati.</li><li>Tarmoq muammolari va kommunikatsiya</li><li>Axborot texnologiyasining bandlikka ta‘siri</li><li>Axborot texnologiyasi (AT) ning tashkilotlar ish uslubiga ta‘siri. Mikroprotsessorli uy qurilmalari</li><li>Axborot texnologiyasi (AT) jihozlaridan uzoq muddat foydalanishning sog‘liqqa ta‘siri</li><li>Kommunikatsiya dasturlari qamrovi. Ma‘lumotlarni boshqarish dasturlari</li><li>O‘lchov dasturlari. Boshqaruv dasturlaridagi mikroprotsessorlar</li><li>Modellashtirish dasturlari. Boshqaruv, ta‘lim, sog‘liqni saqlash, savdo va autentifikatsiyada kompyuter tizimlari</li><li>Tahlil va loyihalash</li><li>Ishlab chiqish, sinash va joriy qilish</li><li>Hujjatlashtirish, baholash va texnik xizmat ko‘rsatish</li><li>Xavfsizlik muammolari. Elektron xavfsizlik. Ma‘lumotlar xavfsizligi</li><li>Axborot himoyasi protokoli. Antiviruslar va fayervol</li><li>Auditoriyani huquqiy, ma‘naviy, axloqiy va madaniy jihatdan baho berish</li><li>Mualliflik huquqi va uning turlari. Mualliflik huquqi himoyasi</li><li>AKT foydalanuvchisi bilan elektron xat orqali muloqot qilish. Spam tushunchasi</li><li>Internetdan samarali foydalanish. Internetdan topilgan axborotning ishonchliligini baholash</li><li>Fayl kengaytmasi va ularni samarali boshqarish</li><li>Saqlash yoki uzatish uchun fayl hajmini kamaytirish</li><li>Tasvirlarni joylashtirish va tahrirlash uchun dastur uskunalaridan foydalanish</li><li>Tasvirni aniq joylashtirish. Tasvirning tomonlar nisbatini o‘zgartirish</li><li>Tasvirni qirqish va aylantirish</li><li>Tasvir rangi, yorqinligi, kontrasti va aniqligi boshqarish</li><li>Sahifa maketi. Maqsad va auditoriyaga mos hujjat yaratish uchun dasturiy uskunalardan foydalanish</li><li>Hujjatga obyektlarni joylashtirish</li><li>Header va Footer maydonlarini yaratish</li><li>Korporativ brend va unga xos stil. Korporativ brendga xos stilga muvofiq hujjat tayyorlash</li><li>Sahifa/slayd izchilligini ta‘minlash</li><li>Yangi stil yaratish</li><li>Xatolarni tekshirish uchun dasturlardan foydalanish</li><li>Xatolarni tekshirish usullari</li><li>Verifikatsiya va validatsiya tuhsunchalari</li><li>Grafik yoki diagramma yaratish. Diagramma turlari</li><li>Tayyorlangan diagrammani boshqarish va o‘zgartirish</li></ul><p>Test <b>10 ta aralash savoldan</b> iborat. Qiynalgan mavzuingizning darsini qayta o‘qib chiqing.</p>","quiz":[{"q":"Quyidagilardan qaysi biri audio fayl?","o":["docx","mp3","jpg","xlsx"],"a":1,"e":"mp3 — audio."},{"q":"Diagramma turini keyin o‘zgartirish mumkinmi?","o":["Ha, ma’lumotlarni qayta kiritmasdan","Faqat yangi fayl yaratib","Yo‘q, hech qachon","Faqat chop etgandan keyin"],"a":0,"e":"Tur almashtiriladi."},{"q":"Ishlash paytida tanaffus nima uchun kerak?","o":["Internetni ulash uchun","Dasturni yangilash uchun","Kompyuterni tezlashtirish uchun","Ko‘z va tanani dam oldirish uchun"],"a":3,"e":"Dam sog‘liq uchun foydali."},{"q":"Quyidagilardan qaysi biri brauzer?","o":["Router","Windows","Mozilla Firefox","Wi-Fi"],"a":2,"e":"Firefox — brauzer."},{"q":"Konditsionerdagi mikroprotsessor nimani boshqaradi?","o":["Derazani","Devor qalinligini","Binoning rangini","Haroratni sozlash rejimini"],"a":3,"e":"U haroratni saqlab turadi."},{"q":"“Uskunaning sozlamalari” deganda nimani tushunamiz?","o":["Fayl nomini","Qalinlik, rang, yumshoqlik kabi parametrlarni","Internet tarmog‘ini","Kompyuter tezligini"],"a":1,"e":"Har bir uskuna uchun parametrlar sozlanadi."},{"q":"OCR texnologiyasi nima uchun ishlatiladi?","o":["Faylni arxivlash","Ovozni yozib olish","Tasvirni chop etish","Tasvirdagi matnni tahrirlanadigan matnga aylantirish"],"a":3,"e":"OCR — optik belgilarni tanish texnologiyasi."},{"q":"Routerni qayta yoqish ko‘pincha nimaga yordam beradi?","o":["Vaqtinchalik ulanish nosozligini bartaraf etishga","Fayl hajmini kamaytirishga","Ekran o‘lchamini oshirishga","Tovushni kuchaytirishga"],"a":0,"e":"Qayta yoqish sozlamalarni yangilaydi."},{"q":"Vaziyat: tez yoqiladigan va shovqinsiz noutbuk kerak. Qaysi xotira mos?","o":["SSD","CD-ROM","Disketa","Magnit lenta"],"a":0,"e":"SSD tez va shovqinsiz."},{"q":"LAN nima?","o":["Mahalliy kompyuter tarmog‘i","Global tarmoq","Antivirus dasturi","Operatsion tizim"],"a":0,"e":"LAN — kichik hududdagi tarmoq."}]},{"t":"53-dars. Matn va sahifa maketini formatlash","lesson":"<p>To‘rtinchi chorakda hujjatlar bilan ishlash ko‘nikmalari mustahkamlanadi. Matn va sahifa maketini formatlash hujjatni tartibli, o‘qishga qulay va chiroyli ko‘rinishga keltiradi. Rasmiy hujjat, referat va hisobotlar maxsus talabga muvofiq bo‘lishi kerak.</p>\n<h4>Matnni formatlash</h4>\n<ul><li>Shrift turi, o‘lchami va rangi.</li>\n<li>Qalin, kursiv va tagiga chizilgan uslub.</li>\n<li>Abzats tekislash: chapga, o‘ngga, markazga, kenglik bo‘yicha.</li>\n<li>Qatorlar oralig‘i va abzats chekinishi.</li>\n<li>Ro‘yxatlar: belgilangan va raqamlangan.</li></ul>\n<h4>Sahifa maketi</h4>\n<ul><li>Sahifa o‘lchami (masalan, A4) va yo‘nalishi: kitob yoki albom.</li>\n<li>Chekka maydonlar.</li>\n<li>Kolontitul va sahifa raqamlari.</li>\n<li>Ustunlar va sahifa bo‘linishi.</li>\n<li>Sarlavha uslublari yordamida mundarija yaratish.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Referat uchun: sarlavhani markazga qo‘ying, asosiy matn uchun bitta shrift tanlang, sahifa raqamlarini qo‘shing va ro‘yxatlarni tartibli rasmiylashtiring.</div>\n<p>Formatlashni boshlashdan oldin hujjatning asosiy matnini to‘liq yozib olish qulay. So‘ng sarlavhalarga, asosiy matnga va ro‘yxatlarga uslub qo‘llanadi. Uslublar yordamida butun hujjat ko‘rinishini bir amalda o‘zgartirish mumkin.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Bir xil uslub hujjatni tartibli qiladi.</li><li>Maket sozlamalari butun hujjatga ta’sir qiladi.</li></ul>","quiz":[{"q":"Sahifa yo‘nalishining turlari qaysi?","o":["Ochiq va yopiq","Kitob va albom","Qizil va ko‘k","Katta va kichik"],"a":1,"e":"Vertikal va gorizontal."},{"q":"Abzats tekislash turlariga qaysi biri kiradi?","o":["Markazga","Faylga","Diagrammaga","Arxivga"],"a":0,"e":"Tekislash."},{"q":"Kolontitul nima?","o":["Rasm turi","Sahifaning yuqori yoki pastki chetidagi takrorlanuvchi matn maydoni","Dastur menyusi","Faylning nomi"],"a":1,"e":"Sahifa chetidagi ma’lumot."},{"q":"Sahifa raqamlari odatda qayerga qo‘shiladi?","o":["Faqat rasmga","Fayl nomiga","Kolontitulga","Faqat sarlavhaga"],"a":2,"e":"Kolontitul."},{"q":"Mundarija qanday yaratiladi?","o":["Sarlavha uslublarini qo‘llab","Faylni arxivlab","Parol qo‘yib","Rasm qo‘shib"],"a":0,"e":"Uslub asos."},{"q":"A4 nima?","o":["Fayl kengaytmasi","Standart qog‘oz o‘lchami","Dastur turi","Shrift nomi"],"a":1,"e":"Qog‘oz formati."},{"q":"Vaziyat: jadvalingiz sahifaga sig‘mayapti. Sahifa sozlamasida nimani o‘zgartirish mumkin?","o":["Faylni arxivlash","Parol qo‘yish","Ekran yorqinligini kamaytirish","Yo‘nalishni albomga o‘zgartirish"],"a":3,"e":"Albom keng."},{"q":"Qatorlar oralig‘i nimaga ta’sir qiladi?","o":["Fayl nomiga","Dastur tezligiga","Tarmoqqa","Matn zichligiga va o‘qilishiga"],"a":3,"e":"Matn ko‘rinishi."},{"q":"Chekka maydonlar nima?","o":["Parol","Rasm turi","Sahifa va matn orasidagi bo‘sh joy","Kengaytma"],"a":2,"e":"Sahifa chetidan masofa."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Rasmiy hujjatda bir xil uslub saqlanishi kerak","Sahifa raqami hech qachon qo‘yilmaydi","Har abzatsda boshqa shrift ishlatish kerak","Formatlash ahamiyatsiz"],"a":0,"e":"Bir xillik tartib beradi."}]},{"t":"54-dars. Dastur uskunalari yordamida jadvallarni tahrirlash","lesson":"<p>Jadval — ma’lumotlarni satr va ustunlarda tartibli ko‘rsatish vositasi. Matn muharririda jadvalni yaratib, keyin tahrirlash — satr, ustun va kataklarni qo‘shish, o‘chirish, birlashtirish, ajratish va ko‘rinishini sozlash mumkin.</p>\n<h4>Jadvalni tahrirlash amallari</h4>\n<ul><li>Satr yoki ustun qo‘shish va o‘chirish.</li>\n<li>Kataklarni birlashtirish va ajratish.</li>\n<li>Ustun kengligi va satr balandligini o‘zgartirish.</li>\n<li>Katak ichidagi matnni tekislash.</li>\n<li>Chegara chiziqlari va fon rangini sozlash.</li>\n<li>Jadvalda ma’lumotlarni saralash.</li></ul>\n<h4>Amaliy ish</h4>\n<ul><li>OL:Kerakli satr va ustunlar sonida jadval qo‘shing.|Sarlavha qatorini kiriting.|Ma’lumotlarni to‘ldiring.|Kerak bo‘lsa, kataklarni birlashtiring.|Chegaralar va fonni sozlang.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Dars jadvalida sarlavha katagini birlashtirib, hafta kunlari bo‘yicha ustunlar hosil qilinadi.</div>\n<p>Jadvalning ma’lumotlari ko‘p bo‘lsa, sarlavha qatorini har sahifada takrorlash qulay. Jadvaldan keraksiz bo‘sh kataklar qolmasligi va matn katakka sig‘ishi lozim. Chiroyli va aniq jadval hujjatni tushunishni ancha osonlashtiradi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Jadval ma’lumotni tartibli ko‘rsatadi.</li><li>Birlashtirish bir necha katakni bittaga aylantiradi.</li></ul>","quiz":[{"q":"Jadval nima uchun ishlatiladi?","o":["Virus topish uchun","Ma’lumotni satr va ustunlarda tartibli ko‘rsatish uchun","Tovush yozish uchun","Fayl siqish uchun"],"a":1,"e":"Tartib."},{"q":"Kataklarni birlashtirish nimani anglatadi?","o":["Bir necha katakni bittaga aylantirish","Jadvalni yopish","Matnni o‘chirish","Katakni o‘chirish"],"a":0,"e":"Birlashtirish."},{"q":"Kataklarni ajratish nima qiladi?","o":["Faylni arxivlaydi","Parol qo‘yadi","Katakni bir necha katakka bo‘ladi","Rasm qo‘shadi"],"a":2,"e":"Bo‘lish."},{"q":"Jadvalga yangi satr qo‘shish mumkinmi?","o":["Yo‘q, hech qachon","Ha","Faqat arxivdan keyin","Faqat yangi fayl yaratib"],"a":1,"e":"Qo‘shish mumkin."},{"q":"Jadval chegaralarini sozlash nimaga ta’sir qiladi?","o":["Fayl hajmiga faqat","Jadvalning ko‘rinishiga","Tarmoq tezligiga","Parolga"],"a":1,"e":"Ko‘rinish."},{"q":"Vaziyat: jadvalda sarlavha bir necha ustunni qoplashi kerak. Nima qilinadi?","o":["Ustunlarni o‘chirish","Rangni o‘zgartirish","Yuqori kataklarni birlashtirish","Jadvalni arxivlash"],"a":2,"e":"Birlashtirish."},{"q":"Ustun kengligini o‘zgartirish uchun nima qilinadi?","o":["Ustun chegarasini sudrash","Printerni yoqish","Faylni o‘chirish","Kompyuterni o‘chirish"],"a":0,"e":"Chegara."},{"q":"Jadval ma’lumotlarini tartiblash qanday nomlanadi?","o":["Arxivlash","Montaj","Saralash","Skanerlash"],"a":2,"e":"Tartiblash."},{"q":"Katak ichidagi matnni markazga qo‘yish nima?","o":["Tekislash","Nusxalash","Arxivlash","Birlashtirish"],"a":0,"e":"Tekislash amali."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Jadval faqat chop etishga","Jadval bir marta yaratilsa o‘zgartirib bo‘lmaydi","Jadval yaratilgandan keyin ham tahrirlanadi","Jadvalga satr qo‘shib bo‘lmaydi"],"a":2,"e":"Tahrirlash mumkin."}]},{"t":"55-dars. Ma‘lumot manbasi bilan hujjatni birlashtirib, pochta orqali yuborish","lesson":"<p>Pochta birlashtirish (mail merge) — bir xil shablondagi hujjatni ko‘p kishi uchun alohida ma’lumotlar bilan tayyorlash usuli. Shablon matn muharririda yoziladi, o‘zgaruvchan ma’lumotlar esa ma’lumot manbasidan (jadval, ro‘yxat yoki ma’lumotlar bazasi) olinadi. Masalan, bir xil taklifnomani har bir mehmon ismi bilan tayyorlash.</p>\n<h4>Asosiy tushunchalar</h4>\n<ul><li><b>Asosiy hujjat</b> — umumiy matn va maydonlar joylashgan shablon.</li>\n<li><b>Ma’lumot manbasi</b> — ism, manzil kabi ma’lumotlar jadvali.</li>\n<li><b>Birlashtirish maydonlari</b> — manbadan qiymat oladigan joylar.</li></ul>\n<h4>Bajarish tartibi</h4>\n<ul><li>OL:Asosiy hujjatni tayyorlang.|Ma’lumot manbasini ulang.|Hujjatga birlashtirish maydonlarini qo‘shing.|Natijani oldindan ko‘ring.|Hujjatlarni chop eting, yangi faylga saqlang yoki elektron pochta orqali yuboring.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab ota-onalarga yig‘ilish haqida xat yuboradi. Xat matni bir xil, ism va sinf maydonlari esa har bir xatda manbadan olinadi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Bir shablon — ko‘p shaxsiylashtirilgan hujjat.</li><li>Yuborishdan oldin natijani ko‘rib chiqing.</li></ul>","quiz":[{"q":"Pochta birlashtirish nima uchun kerak?","o":["Virus qidirish uchun","Faylni arxivlash uchun","Bir shablondan ko‘p shaxsiylashtirilgan hujjat tayyorlash uchun","Rasm chizish uchun"],"a":2,"e":"Ommaviy tayyorlash."},{"q":"Ma’lumot manbasi nima?","o":["Ekran","Dastur kodi","Printer","Ism, manzil kabi ma’lumotlar jadvali"],"a":3,"e":"Ma’lumot manbayi."},{"q":"Asosiy hujjat nima?","o":["Faqat rasm","Umumiy matn va maydonlar bor shablon","Faqat jadval","Pochta qutisi"],"a":1,"e":"Shablon."},{"q":"Birlashtirish maydoni nima qiladi?","o":["Manbadan qiymat olib, hujjatga qo‘yadi","Rasmni kesadi","Tovushni yoqadi","Faylni o‘chiradi"],"a":0,"e":"Qiymat joylashadi."},{"q":"Quyidagilardan qaysi biri pochta birlashtirishga mos vaziyat?","o":["Barcha mehmonlarga ismi yozilgan taklifnoma","Bitta rasm tahriri","Videoni kesish","Faylni siqish"],"a":0,"e":"Ko‘p shaxsiy xat."},{"q":"Birinchi qadam nima?","o":["Asosiy hujjatni tayyorlash","Pochta yuborish","Chop etish","Natijani saqlash"],"a":0,"e":"Shablon boshlanishi."},{"q":"Natijani oldindan ko‘rish nima uchun foydali?","o":["Rangni almashtirish uchun","Xatolarni yuborishdan oldin topish uchun","Parol qo‘yish uchun","Hajmni oshirish uchun"],"a":1,"e":"Tekshirish."},{"q":"Vaziyat: 100 ta o‘quvchiga sertifikat kerak, ismi har xil. Qaysi usul qulay?","o":["Har birini qo‘lda yozish","Rasm chizish","Pochta birlashtirish","Arxivlash"],"a":2,"e":"Qulay va tez."},{"q":"Ma’lumot manbasi qaysi turda bo‘lishi mumkin?","o":["Faqat video","Elektron jadval","Faqat tovush","Faqat rasm"],"a":1,"e":"Jadval manba bo‘ladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Manba ulanmaydi","Natijani faqat qog‘ozda olish mumkin","Pochta birlashtirishda natijani elektron pochta orqali ham yuborish mumkin","Maydon qo‘shib bo‘lmaydi"],"a":2,"e":"Yuborish mumkin."}]},{"t":"56-dars. Ma‘lumotlar bazasi tuzilmasini yaratish. Ma‘lumotlarni boshqarish va taqdim etish","lesson":"<p>Ma’lumotlar bazasi — o‘zaro bog‘liq ma’lumotlarning tartiblangan to‘plami. Uni boshqarish uchun ma’lumotlar bazasini boshqarish tizimi (MBBT) ishlatiladi. Baza tuzilmasini oldindan yaxshi rejalashtirish keyingi ishni osonlashtiradi, chunki noto‘g‘ri tuzilma xatolar va takrorlanishlarga olib keladi.</p>\n<h4>Baza tuzilmasi</h4>\n<ul><li><b>Jadval</b> — ma’lumotlar saqlanadigan asosiy obyekt.</li>\n<li><b>Maydon (ustun)</b> — ma’lumot turi, masalan, ism, sinf.</li>\n<li><b>Yozuv (satr)</b> — bitta obyekt haqidagi to‘liq ma’lumot.</li>\n<li><b>Kalit maydon</b> — har bir yozuvni noyob aniqlaydi.</li>\n<li>Maydon uchun ma’lumot turi tanlanadi: matn, son, sana.</li></ul>\n<h4>Ma’lumotlarni boshqarish va taqdim etish</h4>\n<ul><li>Yozuv qo‘shish, o‘zgartirish va o‘chirish.</li>\n<li>Saralash, qidirish va filtrlash.</li>\n<li>So‘rov — shartga mos ma’lumotni tanlash.</li>\n<li>Hisobot — ma’lumotni chop etishga qulay ko‘rinishda taqdim etish.</li>\n<li>Forma — ma’lumotni qulay kiritish oynasi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> “O‘quvchilar” jadvalida maydonlar: ID, ism, sinf, tug‘ilgan sana. ID — kalit maydon, chunki u takrorlanmaydi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Jadval maydon va yozuvlardan iborat.</li><li>Kalit maydon yozuvni noyob aniqlaydi.</li></ul>","quiz":[{"q":"Ma’lumotlar bazasidagi maydon nima?","o":["Butun baza","Fayl nomi","Jadvalning ustuni (ma’lumot turi)","Jadvalning bitta satri"],"a":2,"e":"Ustun."},{"q":"Yozuv nima?","o":["Bitta obyekt haqidagi to‘liq ma’lumot (satr)","Dastur nomi","Rasm","Bitta ustun"],"a":0,"e":"Satr."},{"q":"Kalit maydon nima uchun kerak?","o":["Ekranni yoritish uchun","Faylni arxivlash uchun","Har bir yozuvni noyob aniqlash uchun","Rangni o‘zgartirish uchun"],"a":2,"e":"Noyoblik."},{"q":"Qaysi maydon kalit bo‘lishi uchun mos?","o":["Sinf harfi","Ismi","O‘quvchi ID raqami","Tug‘ilgan oyi"],"a":2,"e":"ID takrorlanmaydi."},{"q":"So‘rov nima?","o":["Shartga mos ma’lumotni tanlab olish","Rasm chizish","Virus","Jadvalni o‘chirish"],"a":0,"e":"Tanlash."},{"q":"Hisobot nimaga xizmat qiladi?","o":["Ma’lumotni chop etishga qulay shaklda taqdim etishga","Faylni siqishga","Parol saqlashga","Tovush yozishga"],"a":0,"e":"Taqdim etish."},{"q":"Vaziyat: 9-sinf o‘quvchilarining ro‘yxatini ajratib olish kerak. Nima ishlatiladi?","o":["Arxivlash","Hisobotni o‘chirish","Filtr yoki so‘rov","Jadvalni nusxalash"],"a":2,"e":"Shart asosida."},{"q":"Forma nima uchun kerak?","o":["Ma’lumotni qulay kiritish uchun","Faylni siqish uchun","Virus topish uchun","Montaj uchun"],"a":0,"e":"Kiritish oynasi."},{"q":"MBBT nimani anglatadi?","o":["Mikroprotsessor bloki","Matnni boshqarish tizimini","Ma’lumotlar bazasini boshqarish tizimini","Monitor bloki"],"a":2,"e":"Baza bilan ishlaydi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Maydonlar turi muhim emas","Tuzilma ahamiyatsiz","Jadvalsiz baza bo‘ladi","Baza tuzilmasini oldindan rejalashtirish xatolarni kamaytiradi"],"a":3,"e":"Reja foydali."}]},{"t":"57-dars. Ob‘yektlarni to‘g‘ri joylash. Taqdimot slaydlarini yaratish uchun mos dastur imkoniyatlaridan foydalanish","lesson":"<p>Taqdimot slaydlarida obyektlarni to‘g‘ri joylashtirish tinglovchi e’tiborini ushlab turadi va fikrni aniq yetkazadi. Slayd matn, rasm, jadval, diagramma, audio va video obyektlaridan tashkil topadi. Ularning joylashuvi tartibli, mutanosib va o‘qishga qulay bo‘lishi kerak.</p>\n<h4>Obyektlarni joylashtirish qoidalari</h4>\n<ul><li>Slaydga ko‘p matn joylamang, qisqa tezislar yozing.</li>\n<li>Obyektlarni tekislash va teng taqsimlash vositalaridan foydalaning.</li>\n<li>Rasm va diagrammani mazmunga mos tanlang.</li>\n<li>Shrift va ranglar o‘qishga qulay bo‘lsin.</li>\n<li>Har slaydda bitta asosiy fikr bo‘lsin.</li>\n<li>Bir xil dizayn (andoza) ishlating.</li></ul>\n<h4>Slaydlarni yaratish</h4>\n<ul><li>OL:Taqdimot dasturida yangi taqdimot oching.|Maket (joylashuv) turini tanlang.|Sarlavha va matnni kiriting.|Rasm, jadval va diagramma qo‘shing.|O‘tish va animatsiya effektlarini me’yorida qo‘llang.</li></ul>\n<div class=\"ex\"><b>Misol.</b> “Internet xavfsizligi” slaydida chap tomonda 3 ta qisqa band, o‘ng tomonda mavzuga mos rasm joylashtiriladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Slayd sodda, tartibli va o‘qishga qulay bo‘lsin.</li><li>Ortiqcha effekt e’tiborni chalg‘itadi.</li></ul>","quiz":[{"q":"Slaydda matn qanday bo‘lishi kerak?","o":["O‘qib bo‘lmaydigan rangda","Butun abzatslar","Juda mayda shriftda","Qisqa va tezis ko‘rinishida"],"a":3,"e":"Qisqalik."},{"q":"Obyektlarni tekislash nima uchun kerak?","o":["Slayd tartibli ko‘rinishi uchun","Faylni kichraytirish uchun","Tarmoqni tezlashtirish uchun","Parol uchun"],"a":0,"e":"Tartib."},{"q":"Slayd maketi nima?","o":["Obyektlarning slayddagi joylashuv shakli","Ekran rangi","Dastur nomi","Fayl kengaytmasi"],"a":0,"e":"Joylashuv."},{"q":"Har slaydda nechta asosiy fikr bo‘lgani yaxshi?","o":["Hech qancha","Bitta","Yuz","Yigirma"],"a":1,"e":"Aniqlik."},{"q":"Ortiqcha animatsiyalar nimaga olib keladi?","o":["E’tiborni chalg‘itishga","Tushunish osonlashishiga","Hajm kichrayishiga","Tezlik oshishiga"],"a":0,"e":"Chalg‘itadi."},{"q":"Vaziyat: slaydda matn juda ko‘p, shrift mayda. Nima qilasiz?","o":["Hech narsa qilmaysiz","Shriftni yana kichraytirasiz","Matnni qisqartirib, tezislarga ajratasiz","Matn rangini fon rangiga o‘xshatasiz"],"a":2,"e":"Qisqartirish."},{"q":"Quyidagilardan qaysi biri slayd obyekti?","o":["Virus","Parol","Rasm","Kabel"],"a":2,"e":"Rasm obyekt."},{"q":"Bir xil dizayn (andoza) ishlatish nimani ta’minlaydi?","o":["Tarmoq sekinlashuvini","Fayl hajmi oshishini","Slaydlar yo‘qolishini","Taqdimot yaxlit ko‘rinishini"],"a":3,"e":"Yaxlitlik."},{"q":"Shrift va fon ranglari qanday tanlanadi?","o":["Bir xil rangdagi","Tasodifiy","Juda yorqin aralash","Yaxshi kontrast beradigan"],"a":3,"e":"Kontrast o‘qilishni oshiradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Rasmlar mazmunga mos bo‘lishi kerak","Rasm mavzuga aloqasiz bo‘lsa ham yaxshi","Rasm qo‘yilmasligi kerak","Faqat matn yaxshi"],"a":0,"e":"Mazmunga mos."}]},{"t":"58-dars. Taqdimotga elektron jadvaldan diagrammalarni import qilish","lesson":"<p>Elektron jadvalda tayyorlangan diagrammani taqdimotga olib o‘tish mumkin. Bunda ma’lumotni qayta kiritish va diagramma chizish shart emas. Taqdimotda diagramma tinglovchiga raqamlar mohiyatini ko‘rgazmali ko‘rsatadi.</p>\n<h4>Import usullari</h4>\n<ul><li>Diagrammani elektron jadvalda belgilab, nusxalash va slaydga joylash.</li>\n<li>Joylashtirishda ulanish usulini tanlash: <b>bog‘lash</b> yoki <b>joylashtirish (kiritish)</b>.</li>\n<li>Bog‘langan diagramma manba fayl o‘zgarganda yangilanishi mumkin.</li>\n<li>Joylashtirilgan diagramma taqdimot ichida alohida saqlanadi.</li></ul>\n<h4>Qadamlar</h4>\n<ul><li>OL:Elektron jadvalda diagrammani belgilang.|Nusxalang.|Taqdimotda kerakli slaydni oching.|Joylashtirish usulini tanlang.|Diagramma o‘lchami va o‘rnini sozlang.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Sinfning chorak baholari diagrammasi elektron jadvaldan taqdimotga ko‘chirilib, tahlil slaydiga qo‘yiladi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Diagramma jadvaldan taqdimotga ko‘chiriladi.</li><li>Bog‘lash manba o‘zgarganda yangilanishga imkon beradi.</li></ul>","quiz":[{"q":"Diagrammani taqdimotga olib o‘tish nima uchun foydali?","o":["Ma’lumotni qayta kiritmasdan ko‘rgazmali ko‘rsatish","Fayl hajmini kamaytirish","Parol qo‘yish","Tovush yozish"],"a":0,"e":"Qulaylik."},{"q":"Diagrammani ko‘chirishning birinchi qadami qaysi?","o":["Rasmni o‘chirish","Faylni yopish","Diagrammani belgilash","Dasturni o‘chirish"],"a":2,"e":"Belgilash."},{"q":"Qaysi amal diagrammani taqdimotga joylashtiradi?","o":["O‘chirish","Faqat chop etish","Faylni arxivlash","Nusxalab, slaydga joylash"],"a":3,"e":"Joylash."},{"q":"Bog‘lash usuli nimani bildiradi?","o":["Manba o‘zgarsa, diagramma yangilanishi mumkin","Fayl siqiladi","Tarmoq uziladi","Diagramma o‘chadi"],"a":0,"e":"Aloqa saqlanadi."},{"q":"Joylashtirilgan (kiritilgan) diagramma qayerda saqlanadi?","o":["Faqat jadval faylida","Pochtada","Printerda","Taqdimot ichida"],"a":3,"e":"Taqdimotda."},{"q":"Vaziyat: jadvaldagi ma’lumot o‘zgardi, taqdimotdagi diagramma ham avtomatik o‘zgarishi kerak. Qaysi usul mos?","o":["Chop etish","Bog‘lash","Faylni o‘chirish","Rasm sifatida joylash"],"a":1,"e":"Bog‘lanish."},{"q":"Diagrammani slaydga joylagach, nimani sozlash mumkin?","o":["Faqat tarmoqni","O‘lcham va joylashuvni","Faqat parolni","Hech narsani"],"a":1,"e":"Sozlash."},{"q":"Diagrammadan taqdimotda foydalanishdan maqsad nima?","o":["Slaydni murakkablashtirish","Raqamlar mohiyatini ko‘rgazmali tushuntirish","Tinglovchini chalg‘itish","Fayl hajmini oshirish"],"a":1,"e":"Ko‘rgazmalilik."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Diagramma faqat jadvalda ishlaydi","Hamma diagramma bir xil mos","Taqdimotga diagramma qo‘yib bo‘lmaydi","Diagramma turini mavzuga mos tanlash kerak"],"a":3,"e":"Mos tur."},{"q":"Diagramma slaydida nimani qo‘shish foydali?","o":["Uzun abzatslar","Ortiqcha bezaklar","Hech narsa","Qisqa sarlavha va xulosa"],"a":3,"e":"Tushunarlilik."}]},{"t":"59-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 7</b> quyidagi darslarni qamrab oladi:</p><ul><li>Matn va sahifa maketini formatlash</li><li>Dastur uskunalari yordamida jadvallarni tahrirlash</li><li>Ma‘lumot manbasi bilan hujjatni birlashtirib, pochta orqali yuborish</li><li>Ma‘lumotlar bazasi tuzilmasini yaratish. Ma‘lumotlarni boshqarish va taqdim etish</li><li>Ob‘yektlarni to‘g‘ri joylash. Taqdimot slaydlarini yaratish uchun mos dastur imkoniyatlaridan foydalanish</li><li>Taqdimotga elektron jadvaldan diagrammalarni import qilish</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Natijani oldindan ko‘rish nima uchun foydali?","o":["Rangni almashtirish uchun","Xatolarni yuborishdan oldin topish uchun","Parol qo‘yish uchun","Hajmni oshirish uchun"],"a":1,"e":"Tekshirish."},{"q":"Ma’lumotlar bazasidagi maydon nima?","o":["Butun baza","Fayl nomi","Jadvalning ustuni (ma’lumot turi)","Jadvalning bitta satri"],"a":2,"e":"Ustun."},{"q":"Bog‘lash usuli nimani bildiradi?","o":["Manba o‘zgarsa, diagramma yangilanishi mumkin","Fayl siqiladi","Tarmoq uziladi","Diagramma o‘chadi"],"a":0,"e":"Aloqa saqlanadi."},{"q":"Katak ichidagi matnni markazga qo‘yish nima?","o":["Tekislash","Nusxalash","Arxivlash","Birlashtirish"],"a":0,"e":"Tekislash amali."},{"q":"Vaziyat: jadvalda sarlavha bir necha ustunni qoplashi kerak. Nima qilinadi?","o":["Ustunlarni o‘chirish","Rangni o‘zgartirish","Yuqori kataklarni birlashtirish","Jadvalni arxivlash"],"a":2,"e":"Birlashtirish."},{"q":"Ma’lumot manbasi nima?","o":["Ekran","Dastur kodi","Printer","Ism, manzil kabi ma’lumotlar jadvali"],"a":3,"e":"Ma’lumot manbayi."},{"q":"Sahifa yo‘nalishining turlari qaysi?","o":["Ochiq va yopiq","Kitob va albom","Qizil va ko‘k","Katta va kichik"],"a":1,"e":"Vertikal va gorizontal."},{"q":"Vaziyat: 9-sinf o‘quvchilarining ro‘yxatini ajratib olish kerak. Nima ishlatiladi?","o":["Arxivlash","Hisobotni o‘chirish","Filtr yoki so‘rov","Jadvalni nusxalash"],"a":2,"e":"Shart asosida."},{"q":"Abzats tekislash turlariga qaysi biri kiradi?","o":["Markazga","Faylga","Diagrammaga","Arxivga"],"a":0,"e":"Tekislash."},{"q":"Har slaydda nechta asosiy fikr bo‘lgani yaxshi?","o":["Hech qancha","Bitta","Yuz","Yigirma"],"a":1,"e":"Aniqlik."},{"q":"Birlashtirish maydoni nima qiladi?","o":["Manbadan qiymat olib, hujjatga qo‘yadi","Rasmni kesadi","Tovushni yoqadi","Faylni o‘chiradi"],"a":0,"e":"Qiymat joylashadi."},{"q":"Qaysi maydon kalit bo‘lishi uchun mos?","o":["Sinf harfi","Ismi","O‘quvchi ID raqami","Tug‘ilgan oyi"],"a":2,"e":"ID takrorlanmaydi."},{"q":"A4 nima?","o":["Fayl kengaytmasi","Standart qog‘oz o‘lchami","Dastur turi","Shrift nomi"],"a":1,"e":"Qog‘oz formati."},{"q":"Birinchi qadam nima?","o":["Asosiy hujjatni tayyorlash","Pochta yuborish","Chop etish","Natijani saqlash"],"a":0,"e":"Shablon boshlanishi."},{"q":"Quyidagilardan qaysi biri slayd obyekti?","o":["Virus","Parol","Rasm","Kabel"],"a":2,"e":"Rasm obyekt."},{"q":"Chekka maydonlar nima?","o":["Parol","Rasm turi","Sahifa va matn orasidagi bo‘sh joy","Kengaytma"],"a":2,"e":"Sahifa chetidan masofa."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Diagramma faqat jadvalda ishlaydi","Hamma diagramma bir xil mos","Taqdimotga diagramma qo‘yib bo‘lmaydi","Diagramma turini mavzuga mos tanlash kerak"],"a":3,"e":"Mos tur."},{"q":"Ortiqcha animatsiyalar nimaga olib keladi?","o":["E’tiborni chalg‘itishga","Tushunish osonlashishiga","Hajm kichrayishiga","Tezlik oshishiga"],"a":0,"e":"Chalg‘itadi."},{"q":"Jadval ma’lumotlarini tartiblash qanday nomlanadi?","o":["Arxivlash","Montaj","Saralash","Skanerlash"],"a":2,"e":"Tartiblash."},{"q":"Diagrammani ko‘chirishning birinchi qadami qaysi?","o":["Rasmni o‘chirish","Faylni yopish","Diagrammani belgilash","Dasturni o‘chirish"],"a":2,"e":"Belgilash."}]},{"t":"60-dars. Ma‘lumotlar modelini yaratish. Nisbiy va absolyut murojaat.","lesson":"<p>Elektron jadvalda ma’lumotlar modelini yaratishda katak murojaatlaridan foydalaniladi. Formulada katak manzili (masalan, B2) ishlatiladi. Formulani nusxalaganda murojaat o‘zgarishi yoki o‘zgarmay qolishi murojaat turiga bog‘liq. Bu hisoblash modelining asosidir.</p>\n<h4>Murojaat turlari</h4>\n<ul><li><b>Nisbiy murojaat</b> (masalan, A1) — formula nusxalanganda manzil joyiga qarab o‘zgaradi.</li>\n<li><b>Absolyut murojaat</b> (masalan, $A$1) — nusxalanganda manzil o‘zgarmaydi.</li>\n<li><b>Aralash murojaat</b> (masalan, $A1 yoki A$1) — faqat ustun yoki faqat satr qotiriladi.</li></ul>\n<h4>Qachon qaysi biri kerak</h4>\n<ul><li>Har qatorda o‘z qiymati bilan hisoblash uchun — nisbiy.</li>\n<li>Doimiy qiymat (masalan, kurs yoki soliq stavkasi) uchun — absolyut.</li>\n<li>Murojaatni qotirish uchun $ belgisi qo‘yiladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> B2 katakda narx, C1 katakda kurs. Har qator uchun narxni kursga ko‘paytirish: =B2*$C$1. Formulani pastga nusxalaganda B2 o‘zgaradi (B3, B4), kurs esa o‘zgarmaydi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>$ belgisi murojaatni qotiradi.</li><li>Doimiy qiymat uchun absolyut murojaat ishlatiladi.</li></ul>","quiz":[{"q":"Nisbiy murojaat nusxalanganda nima bo‘ladi?","o":["Formula o‘chadi","Manzil joyiga qarab o‘zgaradi","Manzil o‘zgarmaydi","Jadval yopiladi"],"a":1,"e":"Siljiydi."},{"q":"Qaysi yozuv absolyut murojaat?","o":["A1","A$1 emas, B2","C3","$A$1"],"a":3,"e":"Ikkala $ bor."},{"q":"$ belgisi nimani anglatadi?","o":["Pul birligini faqat","Matnni o‘chirishni","Rangni o‘zgartirishni","Murojaatning qotirilishini"],"a":3,"e":"Qotirish."},{"q":"Doimiy kurs qiymati uchun qaysi murojaat mos?","o":["Absolyut","Nisbiy","Faqat matnli","Hech qaysi"],"a":0,"e":"Qiymat qotiriladi."},{"q":"Aralash murojaatga misol qaysi?","o":["A1","B2:C3","$A1","$A$1"],"a":2,"e":"Bittasi qotirilgan."},{"q":"Vaziyat: =B2*$C$1 formulasi pastga nusxalandi. Qaysi qism o‘zgarmaydi?","o":["B2","$C$1","Ikkalasi o‘zgarmaydi","Ikkalasi o‘zgaradi"],"a":1,"e":"Absolyut qism."},{"q":"Formulani pastga nusxalaganda B2 ning o‘rniga qaysi paydo bo‘ladi?","o":["C2","$B$2","B1","B3"],"a":3,"e":"Qator ortadi."},{"q":"Formula nimadan boshlanadi?","o":["= belgisidan","# belgisidan","% belgisidan","@ belgisidan"],"a":0,"e":"Tenglik belgisi."},{"q":"Murojaat turini tez almashtirish uchun nima qo‘yiladi?","o":["& belgisi","# belgisi","% belgisi","$ belgisi"],"a":3,"e":"$ qotiradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Doimiy qiymatni formulada absolyut murojaat bilan yozish kerak","Barcha murojaatlar doim nisbiy","Absolyut murojaat nusxalanganda o‘zgaradi","Murojaat turi ahamiyatsiz"],"a":0,"e":"Doimiy qotiriladi."}]},{"t":"61-dars. Formula va funksiyalar hamda ulardan foydalanish","lesson":"<p>Elektron jadvalda formula va funksiyalar hisob-kitobni avtomatlashtiradi. Formula tenglik belgisi bilan boshlanadi va qiymat, katak manzili, amallar hamda funksiyalardan iborat bo‘ladi. Funksiya — tayyor formula bo‘lib, nomi va qavs ichidagi argumentlaridan iborat.</p>\n<h4>Arifmetik amallar</h4>\n<ul><li>Qo‘shish +, ayirish -, ko‘paytirish *, bo‘lish /, daraja ^.</li>\n<li>Amallar tartibi matematikadagidek; qavslar ustunlikni o‘zgartiradi.</li></ul>\n<h4>Mashhur funksiyalar</h4>\n<ul><li><b>SUM</b> — yig‘indi, masalan, =SUM(A1:A5).</li>\n<li><b>AVERAGE</b> — o‘rta arifmetik.</li>\n<li><b>MAX</b> va <b>MIN</b> — eng katta va eng kichik qiymat.</li>\n<li><b>COUNT</b> — sonli kataklar soni.</li>\n<li><b>IF</b> — shart bo‘yicha qiymat tanlash.</li></ul>\n<h4>Eslatma</h4>\n<ul><li>A1:A5 — A1 dan A5 gacha katakchalar oralig‘i.</li>\n<li>Formulaning natijasi katakda ko‘rinadi, formulaning o‘zi formulalar qatorida.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Baholar B2:B11 oralig‘ida bo‘lsa, o‘rtacha bahoni =AVERAGE(B2:B11) formulasi hisoblaydi.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Formula = bilan boshlanadi.</li><li>Funksiya qavs ichida argumentlarni oladi.</li></ul>","quiz":[{"q":"Formula qaysi belgidan boshlanadi?","o":["@","?","#","="],"a":3,"e":"Tenglik."},{"q":"A1:A5 oralig‘i nimani bildiradi?","o":["A1 dan A5 gacha katakchalarni","Faqat A1 ni","A ustunidagi barcha katakni","Faqat A5 ni"],"a":0,"e":"Oraliq."},{"q":"SUM funksiyasi nima qiladi?","o":["Eng kattani topadi","Sonini sanaydi","O‘rtachani topadi","Yig‘indini hisoblaydi"],"a":3,"e":"Yig‘indi."},{"q":"AVERAGE funksiyasi nimani hisoblaydi?","o":["Eng kichikni","Yig‘indini","Ko‘paytmani","O‘rta arifmetikni"],"a":3,"e":"O‘rtacha."},{"q":"Eng katta qiymatni topish uchun qaysi funksiya ishlatiladi?","o":["MAX","COUNT","SUM","MIN"],"a":0,"e":"Maksimum."},{"q":"Ko‘paytirish amali qaysi belgi bilan yoziladi?","o":["*","-","^","+"],"a":0,"e":"Yulduzcha."},{"q":"Vaziyat: B2:B11 dagi baholarning o‘rtachasi kerak. Qaysi formula to‘g‘ri?","o":["AVERAGE(B2:B11)","=SUM(B2:B11)","=AVERAGE(B2:B11)","=MAX(B2:B11)"],"a":2,"e":"= bilan boshlanadi."},{"q":"IF funksiyasi nimaga xizmat qiladi?","o":["Shartga qarab qiymat tanlashga","Faylni arxivlashga","Rasmni kesishga","Tovushni yozishga"],"a":0,"e":"Shart."},{"q":"Darajaga ko‘tarish amali qaysi belgi?","o":["*","^","-","/"],"a":1,"e":"Ustki belgi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Funksiya qo‘lda yoziladi, argument qabul qilmaydi","Funksiya faqat matnda ishlaydi","Funksiya tayyor formula bo‘lib, argumentlarni qavs ichida oladi","Formula ko‘p hollarda tenglik belgisisiz yoziladi"],"a":2,"e":"Argumentlar qavsda."}]},{"t":"62-dars. Ma‘lumotlar modelini sinovdan o‘tkazish. Ma‘lumotlarni boshqarish","lesson":"<p>Ma’lumotlar modeli tayyor bo‘lgach, uni sinovdan o‘tkazish kerak: model muammoni to‘g‘ri aks ettiradimi, hisob-kitoblar natijasi to‘g‘rimi, tekshirish kerak. Sinov xatolarni foydalanuvchi ishlata boshlagandan oldin topishga yordam beradi.</p>\n<h4>Modelni sinash</h4>\n<ul><li>Oldindan natijasi ma’lum bo‘lgan sinov ma’lumotlarini kiriting va model chiqargan natija bilan solishtiring.</li><li>Oddiy, chegaraviy va noto‘g‘ri qiymatlar bilan sinab ko‘ring.</li><li>Topilgan xatolar tuzatilib, sinov qayta o‘tkaziladi.</li></ul>\n<h4>Ma’lumotlarni boshqarish</h4>\n<ul><li>Ma’lumotlarni saqlash, yangilash, o‘chirish va zaxira nusxasini yaratish boshqarishga kiradi.</li><li>Ma’lumotlarga kirish huquqi faqat vakolatli foydalanuvchilarga beriladi.</li><li>Eskirgan va takrorlangan yozuvlar tozalab turiladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Jadvalda 5 ta sonning yig‘indisi hisoblanadi. Siz kalkulyatorda hisoblab chiqqan natijani jadval formulasi bergan natija bilan solishtirasiz. Natijalar bir xil bo‘lsa, formula to‘g‘ri ishlayapti.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Sinovdan maqsad xatolarni topish va tuzatishdir.</li><li>Sinov uchun natijasi oldindan ma’lum ma’lumotlar olinadi.</li><li>Ma’lumotlarning zaxira nusxasi muntazam yaratiladi.</li></ul>","quiz":[{"q":"Modelni sinovdan o‘tkazishdan asosiy maqsad nima?","o":["Xatolarni topib, to‘g‘ri ishlashini tekshirish","Modelni o‘chirib tashlash","Modelni chiroyli qilish","Fayl hajmini kamaytirish"],"a":0,"e":"Sinov model natijalarining to‘g‘riligini tasdiqlaydi."},{"q":"Sinov uchun qanday ma’lumotlar qulay?","o":["Faqat matnli ma’lumotlar","Faqat bo‘sh kataklar","Tasodifiy tanlangan, hech kim bilmaydigan ma’lumotlar","Natijasi oldindan ma’lum bo‘lgan ma’lumotlar"],"a":3,"e":"Kutilgan natija bilan solishtirish uchun natija oldindan ma’lum bo‘lishi kerak."},{"q":"Sinov davomida xato topilsa, nima qilinadi?","o":["Natija qo‘lda o‘zgartirib qo‘yiladi","Xatoga e’tibor berilmaydi","Xato tuzatilib, sinov qayta o‘tkaziladi","Model o‘chiriladi va ish to‘xtatiladi"],"a":2,"e":"Tuzatishdan keyin qayta sinash shart."},{"q":"Ma’lumotlarni boshqarishga nima kiradi?","o":["Faqat rasm chizish","Saqlash, yangilash, himoyalash va zaxiralash","Faqat ekran yorqinligini sozlash","Faqat chop etish"],"a":1,"e":"Boshqarish ma’lumotlar bilan butun ish jarayonini qamraydi."},{"q":"Zaxira nusxa nima uchun kerak?","o":["Dastur tezligini oshirish uchun","Ma’lumotlarni o‘chirish uchun","Faylni shifrlash uchun","Ma’lumotlar yo‘qolganda tiklash uchun"],"a":3,"e":"Zaxira nusxadan yo‘qolgan ma’lumotlar tiklanadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Sinov modelni yaratishdan oldin o‘tkaziladi","Chegaraviy qiymatlar bilan ham sinash kerak","Faqat bitta qiymat bilan sinash yetarli","Xato topilsa, uni hisobga olmaslik kerak"],"a":1,"e":"Model turli qiymatlarda, jumladan chegaraviy qiymatlarda ham sinaladi."},{"q":"Vaziyat: formula natijasi kalkulyatordagi natijadan farq qilyapti. Nima qilasiz?","o":["Jadvalni o‘chirib tashlayman","Natijani qo‘lda yozib qo‘yaman","Kalkulyator natijasini noto‘g‘ri deb hisoblayman","Formulani tekshirib, xatoni topaman"],"a":3,"e":"Farq xato borligini bildiradi, uni topib tuzatish kerak."},{"q":"Ma’lumotlarga kirish huquqi kimlarga beriladi?","o":["Hammaga bir xil","Faqat vakolatli foydalanuvchilarga","Hech kimga","Faqat tasodifiy odamlarga"],"a":1,"e":"Himoya uchun kirish huquqi cheklanadi."},{"q":"Takrorlangan va eskirgan yozuvlar bilan nima qilinadi?","o":["Hech qachon tegilmaydi","Ko‘paytirib boriladi","Rasmga aylantiriladi","Tozalab turiladi"],"a":3,"e":"Ma’lumotlar sifatini saqlash uchun tozalash kerak."},{"q":"Sinov jarayoni qaysi bosqichdan keyin bajariladi?","o":["Dastur o‘chirilgandan keyin","Muammo aniqlanmasdan oldin","Hech qachon bajarilmaydi","Model yaratilgandan keyin"],"a":3,"e":"Model tayyor bo‘lgach sinaladi."}]},{"t":"63-dars. Ma‘lumotlarni taqdim etish","lesson":"<p>Ma’lumotlarni taqdim etish — ularni tushunarli, qulay va ko‘rgazmali shaklda ko‘rsatish demakdir. Bir xil ma’lumotni jadval, diagramma, grafik yoki hisobot ko‘rinishida berish mumkin. Shaklni tanlash kimga va nima uchun ko‘rsatilayotganiga bog‘liq.</p>\n<h4>Taqdim etish shakllari</h4>\n<ul><li>Jadval aniq qiymatlarni ko‘rsatadi.</li><li>Diagramma qiymatlarni solishtirishni osonlashtiradi.</li><li>Grafik vaqt davomida o‘zgarishni ko‘rsatadi.</li><li>Matnli hisobot xulosa va izohlarni beradi.</li></ul>\n<h4>Yaxshi taqdim etish qoidalari</h4>\n<ul><li>Sarlavha, o‘lchov birliklari va izohlar yozilsin.</li><li>Ortiqcha bezaklar va rang-barang ranglardan qochish kerak.</li><li>Muhim natijalar ajratib ko‘rsatilsin.</li><li>Ma’lumotlar manbasi va sanasi ko‘rsatilsa, ishonchliroq bo‘ladi.</li><li>Bir xil turdagi ma’lumotlar bir xil shaklda berilsin.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Sinf o‘quvchilarining baholari tarqalishini ko‘rsatish uchun doiraviy diagramma qulay, sinfning yillik o‘zgarishini ko‘rsatish uchun esa chiziqli grafik qulay.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Taqdim etish shakli maqsadga qarab tanlanadi.</li><li>Diagramma sarlavha va izohga ega bo‘lishi kerak.</li><li>Grafik vaqt bo‘yicha o‘zgarishni yaxshi ko‘rsatadi.</li></ul>","quiz":[{"q":"Ma’lumotlarni taqdim etish nima?","o":["Ma’lumotlarni o‘chirish","Ma’lumotlarni faqat saqlash","Ma’lumotlarni tushunarli shaklda ko‘rsatish","Ma’lumotlarni shifrlash"],"a":2,"e":"Taqdim etish — ma’lumotni o‘quvchiga qulay ko‘rsatish."},{"q":"Vaqt davomida o‘zgarishni ko‘rsatish uchun qaysi shakl qulay?","o":["Chiziqli grafik","Sarlavha","Faqat matn abzasi","Rasm fayli"],"a":0,"e":"Grafik o‘zgarish tendensiyasini ko‘rsatadi."},{"q":"Aniq qiymatlarni ko‘rsatish uchun qaysi shakl qulay?","o":["Animatsiya","Shaffof rasm","Jadval","Audio yozuv"],"a":2,"e":"Jadvalda har bir qiymat aniq yoziladi."},{"q":"Diagrammaga nima qo‘shish tavsiya etiladi?","o":["Faqat rang","Tasodifiy rasmlar","Sarlavha va izohlar","Ortiqcha bezaklar"],"a":2,"e":"Sarlavha va izoh diagrammani tushunarli qiladi."},{"q":"Qismlarning butundagi ulushini ko‘rsatish uchun qaysi diagramma qulay?","o":["Doiraviy diagramma","Sarlavha","Jadval katagi","Formula"],"a":0,"e":"Doiraviy diagramma ulushlarni ko‘rsatadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Hamma ma’lumot faqat bitta shaklda beriladi","Ranglar qancha ko‘p bo‘lsa, shuncha yaxshi","Taqdim etish shakli auditoriya va maqsadga bog‘liq","Izohlar taqdimotni buzadi"],"a":2,"e":"Shakl maqsadga qarab tanlanadi."},{"q":"Vaziyat: sinf baholarining tarqalishini ko‘rsatmoqchisiz. Nima tanlaysiz?","o":["Parol","Audio fayl","Faqat uzun matn","Diagramma"],"a":3,"e":"Diagramma ulush va tarqalishni ko‘rgazmali ko‘rsatadi."},{"q":"Diagramma o‘qlarida nima ko‘rsatilishi kerak?","o":["Foydalanuvchi paroli","Hech narsa","Faqat tasodifiy sonlar","O‘lchov birliklari va nomlar"],"a":3,"e":"Birlik va nomlar tushunishga yordam beradi."},{"q":"Ortiqcha bezaklar nimaga olib keladi?","o":["Ma’lumotlar tezroq tushunilishiga","Ma’lumotlar to‘g‘ri bo‘lishiga","Asosiy ma’lumot ko‘rinmay qolishiga","Fayl himoyalanishiga"],"a":2,"e":"Bezak e’tiborni chalg‘itadi."},{"q":"Hisobot nima beradi?","o":["Kompyuter nomini","Faqat tovush","Xulosa va izohlarni","Faqat rasm o‘lchami"],"a":2,"e":"Hisobotda natijalar va xulosa bayon etiladi."}]},{"t":"64-dars. Veb dasturlashning uch qatlami. Veb sahifa yaratish","lesson":"<p>Veb sahifalar uch qatlamdan iborat: tuzilma, ko‘rinish va xatti-harakat. Bu qatlamlar bir-biridan alohida bo‘lib, har biri o‘z texnologiyasi bilan yoziladi. Shu tufayli sahifani boshqarish va o‘zgartirish osonlashadi.</p>\n<h4>Uch qatlam</h4>\n<ul><li><b>HTML</b> — sahifa tuzilmasi va mazmuni: sarlavha, abzas, rasm, havola.</li><li><b>CSS</b> — ko‘rinish: rang, shrift, joylashuv.</li><li><b>JavaScript</b> — xatti-harakat: tugma bosilganda sahifa javob qaytarishi.</li></ul>\n<h4>Oddiy veb sahifa yaratish</h4>\n<ul><li>Veb sahifa matn muharririda yoziladi va .html kengaytmasi bilan saqlanadi.</li><li>HTML teglar bilan ishlaydi: ochuvchi va yopuvchi teglar jufti.</li><li>Fayl brauzer orqali ochilib, natija ko‘riladi.</li><li>Har bir o‘zgartirishdan keyin faylni saqlab, brauzerda sahifani yangilash kerak.</li></ul>\n<div class=\"ex\"><b>Misol.</b> <p>Sahifa tuzilishi: &lt;html&gt;, &lt;head&gt; (sarlavha va sozlamalar) hamda &lt;body&gt; (ko‘rinadigan mazmun) qismlaridan iborat.</p></div>\n<h4>Eslab qoling</h4>\n<ul><li>HTML tuzilma, CSS ko‘rinish, JavaScript xatti-harakat uchun.</li><li>Sahifa faylining kengaytmasi .html bo‘ladi.</li><li>Ko‘rinadigan mazmun body qismida yoziladi.</li></ul>","quiz":[{"q":"Veb dasturlashning uchta qatlami qaysilar?","o":["Word, Excel, Paint","BIOS, DOS, USB","HTML, CSS, JavaScript","Wi-Fi, LAN, WAN"],"a":2,"e":"Tuzilma, ko‘rinish va xatti-harakat qatlamlari."},{"q":"Sahifa tuzilmasi va mazmunini qaysi texnologiya belgilaydi?","o":["CSS","JavaScript","HTML","Faqat brauzer"],"a":2,"e":"HTML sahifa tuzilmasini beradi."},{"q":"Rang va shrift kabi ko‘rinishni qaysi qatlam boshqaradi?","o":["Operatsion tizim","Faqat server","HTML","CSS"],"a":3,"e":"CSS ko‘rinish uchun javob beradi."},{"q":"Tugma bosilganda sahifaning javob qaytarishi qaysi qatlamga tegishli?","o":["Fayl nomi","HTML tuzilma","JavaScript","CSS rangi"],"a":2,"e":"JavaScript xatti-harakatni ta’minlaydi."},{"q":"Veb sahifa fayli odatda qanday kengaytma bilan saqlanadi?","o":[".exe",".mp3",".html",".zip"],"a":2,"e":"HTML fayllari .html kengaytmasiga ega."},{"q":"Sahifaning ko‘rinadigan mazmuni qaysi qismda yoziladi?","o":["Faqat fayl nomida","body","head sarlavhasidan tashqarida","Brauzer sozlamasida"],"a":1,"e":"Ko‘rinadigan mazmun body ichida bo‘ladi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["HTML dasturi faqat o‘yin","Veb sahifa faqat Excelda yoziladi","Teglar faqat rasm bo‘ladi","Teglar odatda ochuvchi va yopuvchi juft bo‘ladi"],"a":3,"e":"Teglar odatda juft ishlatiladi."},{"q":"Vaziyat: sahifa matnining rangini o‘zgartirmoqchisiz. Qaysi qatlam kerak?","o":["Ma’lumotlar bazasi","Klaviatura","CSS","HTML sarlavhasi"],"a":2,"e":"Rang ko‘rinishga tegishli, ya’ni CSS."},{"q":"Veb sahifani yozish uchun nima yetarli?","o":["Faqat mikrofon","Oddiy matn muharriri va brauzer","Faqat skaner","Faqat printer"],"a":1,"e":"Matn muharriri va brauzer bilan sahifa yaratish mumkin."},{"q":"Qatlamlarning ajratilishi nimaga qulaylik beradi?","o":["Fayl o‘chirishga","Parol buzishga","Kompyuter tezligini pasaytirishga","Sahifani boshqarish va o‘zgartirishga"],"a":3,"e":"Alohida qatlamlarni mustaqil o‘zgartirish mumkin."}]},{"t":"65-dars. Linklar, bookmarklar va ankor. Absolyut va nisbiy fayl manzillari","lesson":"<p>Veb sahifalar bir-biri bilan havolalar (linklar) orqali bog‘lanadi. Havola bosilganda brauzer boshqa sahifa yoki joyga o‘tadi. Havola HTMLda &lt;a&gt; tegi va href atributi bilan yoziladi.</p>\n<h4>Havola turlari</h4>\n<ul><li><b>Ankor</b> — havola matni, foydalanuvchi bosadigan qism.</li><li><b>Ichki havola</b> — o‘z saytingizdagi sahifaga o‘tadi.</li><li><b>Tashqi havola</b> — boshqa saytga o‘tadi.</li><li><b>Bookmark</b> — brauzerda saqlab qo‘yilgan sahifa manzili (xatcho‘p).</li></ul>\n<h4>Fayl manzillari</h4>\n<ul><li><b>Absolyut manzil</b> — to‘liq yo‘l, masalan, http bilan boshlanadigan to‘liq URL.</li><li><b>Nisbiy manzil</b> — hozirgi faylga nisbatan yo‘l, masalan, rasmlar/a.png.</li><li>Nisbiy manzillar saytni boshqa joyga ko‘chirganda ham ishlayveradi.</li><li>Havola manzilidagi xato sahifa ochilmasligiga olib keladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> <p>&lt;a href=\"about.html\"&gt;Biz haqimizda&lt;/a&gt; — bu yerda \"Biz haqimizda\" ankor, about.html esa nisbiy manzil.</p></div>\n<h4>Eslab qoling</h4>\n<ul><li>Havola a tegi va href atributi bilan yoziladi.</li><li>Ankor — bosiladigan matn.</li><li>Nisbiy manzil sayt ichida ko‘chirishga qulay.</li></ul>","quiz":[{"q":"Havola yaratish uchun qaysi teg ishlatiladi?","o":["a","img","p","br"],"a":0,"e":"a tegi havola yaratadi."},{"q":"Havola manzili qaysi atributda yoziladi?","o":["src","width","href","alt"],"a":2,"e":"href manzilni ko‘rsatadi."},{"q":"Ankor nima?","o":["Havolaning bosiladigan matni","Kompyuter nomi","Fayl kengaytmasi","Rasm hajmi"],"a":0,"e":"Ankor — foydalanuvchi bosadigan matn."},{"q":"Absolyut manzil qanday bo‘ladi?","o":["To‘liq yo‘lni ko‘rsatadi","Faqat papka nomi","Bo‘sh qoladi","Faqat fayl nomi"],"a":0,"e":"Absolyut manzil to‘liq yo‘ldan iborat."},{"q":"Nisbiy manzil nimaga nisbatan beriladi?","o":["Kompyuter markaziga","Hozirgi fayl joylashuviga","Printer joyiga","Dunyo xaritasiga"],"a":1,"e":"Nisbiy manzil joriy faylga nisbatan yoziladi."},{"q":"Bookmark (xatcho‘p) nima uchun kerak?","o":["Sahifa manzilini saqlab, keyin tez ochish uchun","Sahifani o‘chirish uchun","Parol yaratish uchun","Rasmni kichraytirish uchun"],"a":0,"e":"Xatcho‘p sahifaga tez qaytishga yordam beradi."},{"q":"Vaziyat: saytni boshqa papkaga ko‘chirdingiz va havolalar buzilmasligi kerak. Qaysi manzil qulay?","o":["Faqat tasodifiy matn","Hech qaysi","Nisbiy manzil","Boshqa kompyuter yo‘li"],"a":2,"e":"Nisbiy manzillar ko‘chirishda ishlayveradi."},{"q":"Boshqa saytga olib boradigan havola qanday ataladi?","o":["Nisbiy havola faqat","Ichki havola","Tashqi havola","Ankor bo‘sh"],"a":2,"e":"Tashqi havola boshqa saytga o‘tkazadi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["href atributi rang beradi","Ankor faqat rasm bo‘ladi","Havola faqat sarlavhada yoziladi","Havola matni ankor deb ataladi"],"a":3,"e":"Ankor — havola matni."},{"q":"&lt;a href=\"info.html\"&gt;Ma’lumot&lt;/a&gt; yozuvida ankor qaysi?","o":["a","Ma’lumot","Biror teg","href"],"a":1,"e":"Teglar orasidagi matn ankor bo‘ladi."}]},{"t":"66-dars. Stil jadvallaridan foydalanish. Veb saytni sinash va publikatsiya qilish","lesson":"<p>CSS (stil jadvallari) yordamida sahifaning ko‘rinishi belgilanadi. Stil qoidasi tanlovchi va uning xususiyatlaridan iborat: qaysi element, qaysi xususiyat, qanday qiymat. Stillarni alohida .css faylga yozib, bir nechta sahifaga ulash mumkin.</p>\n<h4>Stillarni qo‘llash usullari</h4>\n<ul><li><b>Ichki</b> — teg ichidagi style atributi.</li><li><b>Ichki jadval</b> — head ichida style tegi.</li><li><b>Tashqi</b> — alohida .css fayl, link tegi orqali ulanadi.</li></ul>\n<h4>Sinash va publikatsiya</h4>\n<ul><li>Sayt turli brauzerlarda va ekran o‘lchamlarida sinab ko‘riladi.</li><li>Havolalar va rasmlar to‘g‘ri ochilishi tekshiriladi.</li><li>Sayt tayyor bo‘lgach, hosting (veb-server)ga joylashtiriladi — bu publikatsiya.</li><li>Foydalanuvchilar sayt manzili (domen) orqali kiradi.</li><li>Saytni vaqti-vaqti bilan yangilab turish ham kerak.</li></ul>\n<div class=\"ex\"><b>Misol.</b> p { color: blue; } qoidasi barcha abzaslar matnini ko‘k rangga bo‘yaydi: p — tanlovchi, color — xususiyat, blue — qiymat.</div>\n<h4>Eslab qoling</h4>\n<ul><li>Tashqi stil jadvali bir nechta sahifaga ulanadi.</li><li>Saytni e’lon qilishdan oldin sinash shart.</li><li>Publikatsiya — saytni serverga joylashtirish.</li></ul>","quiz":[{"q":"CSS nima uchun ishlatiladi?","o":["Ma’lumotlarni shifrlash uchun","Sahifa ko‘rinishini belgilash uchun","Tarmoq tezligini o‘lchash uchun","Rasm skanerlash uchun"],"a":1,"e":"CSS ko‘rinishni boshqaradi."},{"q":"p { color: blue; } qoidasida p nima?","o":["Qiymat","Izoh","Xususiyat","Tanlovchi"],"a":3,"e":"p — qaysi elementga qo‘llanishini ko‘rsatadi."},{"q":"Qoidada color nima?","o":["Tanlovchi","Domen","Xususiyat","Fayl nomi"],"a":2,"e":"color — xususiyat nomi."},{"q":"Tashqi stil jadvali qanday fayl?","o":["Faqat rasm","Alohida .css fayl",".exe fayl",".mp4 fayl"],"a":1,"e":"Tashqi stil .css faylida yoziladi."},{"q":"Tashqi stil jadvalining afzalligi nima?","o":["Rasm hajmini oshiradi","Sahifani o‘chiradi","Faqat bitta sahifaga mos","Bir nechta sahifaga ulash mumkin"],"a":3,"e":"Bitta fayl butun saytga ulanadi."},{"q":"Saytni e’lon qilishdan oldin nima qilinadi?","o":["Hech narsa tekshirilmaydi","Parol o‘zgartiriladi","Sinab ko‘riladi","Barcha rasmlar o‘chiriladi"],"a":2,"e":"Xatolarni oldindan topish uchun sinov o‘tkaziladi."},{"q":"Publikatsiya nima?","o":["Sayt rangini o‘zgartirish","Saytni o‘chirish","Saytni serverga joylashtirib e’lon qilish","Saytni chop etish"],"a":2,"e":"Publikatsiya — saytni internetda ko‘rinadigan qilish."},{"q":"Vaziyat: sayt telefonda noto‘g‘ri ko‘rinyapti. Nima qilish kerak?","o":["Saytni o‘chirish","Telefonni almashtirish","Hech narsa qilmaslik","Turli ekran o‘lchamlarida sinab, stilni tuzatish"],"a":3,"e":"Turli qurilmalarda sinash va tuzatish kerak."},{"q":"Sayt manzili nima orqali topiladi?","o":["Printer orqali","Quvvat adapteri orqali","Sichqoncha orqali","Domen nomi orqali"],"a":3,"e":"Foydalanuvchilar domen orqali kiradi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Havolalarni tekshirish shart emas","CSS faqat serverda ishlaydi","Havolalar publikatsiyadan oldin tekshiriladi","Sinov saytni buzadi"],"a":2,"e":"Ishlamaydigan havolalar oldindan topilishi kerak."}]},{"t":"67-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 8</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ma‘lumotlar modelini yaratish. Nisbiy va absolyut murojaat.</li><li>Formula va funksiyalar hamda ulardan foydalanish</li><li>Ma‘lumotlar modelini sinovdan o‘tkazish. Ma‘lumotlarni boshqarish</li><li>Ma‘lumotlarni taqdim etish</li><li>Veb dasturlashning uch qatlami. Veb sahifa yaratish</li><li>Linklar, bookmarklar va ankor. Absolyut va nisbiy fayl manzillari</li><li>Stil jadvallaridan foydalanish. Veb saytni sinash va publikatsiya qilish</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Formula nimadan boshlanadi?","o":["= belgisidan","# belgisidan","% belgisidan","@ belgisidan"],"a":0,"e":"Tenglik belgisi."},{"q":"Vaziyat: sayt telefonda noto‘g‘ri ko‘rinyapti. Nima qilish kerak?","o":["Saytni o‘chirish","Telefonni almashtirish","Hech narsa qilmaslik","Turli ekran o‘lchamlarida sinab, stilni tuzatish"],"a":3,"e":"Turli qurilmalarda sinash va tuzatish kerak."},{"q":"Publikatsiya nima?","o":["Sayt rangini o‘zgartirish","Saytni o‘chirish","Saytni serverga joylashtirib e’lon qilish","Saytni chop etish"],"a":2,"e":"Publikatsiya — saytni internetda ko‘rinadigan qilish."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Funksiya qo‘lda yoziladi, argument qabul qilmaydi","Funksiya faqat matnda ishlaydi","Funksiya tayyor formula bo‘lib, argumentlarni qavs ichida oladi","Formula ko‘p hollarda tenglik belgisisiz yoziladi"],"a":2,"e":"Argumentlar qavsda."},{"q":"To‘g‘ri mulohazani tanlang.","o":["href atributi rang beradi","Ankor faqat rasm bo‘ladi","Havola faqat sarlavhada yoziladi","Havola matni ankor deb ataladi"],"a":3,"e":"Ankor — havola matni."},{"q":"Nisbiy manzil nimaga nisbatan beriladi?","o":["Kompyuter markaziga","Hozirgi fayl joylashuviga","Printer joyiga","Dunyo xaritasiga"],"a":1,"e":"Nisbiy manzil joriy faylga nisbatan yoziladi."},{"q":"Tugma bosilganda sahifaning javob qaytarishi qaysi qatlamga tegishli?","o":["Fayl nomi","HTML tuzilma","JavaScript","CSS rangi"],"a":2,"e":"JavaScript xatti-harakatni ta’minlaydi."},{"q":"CSS nima uchun ishlatiladi?","o":["Ma’lumotlarni shifrlash uchun","Sahifa ko‘rinishini belgilash uchun","Tarmoq tezligini o‘lchash uchun","Rasm skanerlash uchun"],"a":1,"e":"CSS ko‘rinishni boshqaradi."},{"q":"Sinov davomida xato topilsa, nima qilinadi?","o":["Natija qo‘lda o‘zgartirib qo‘yiladi","Xatoga e’tibor berilmaydi","Xato tuzatilib, sinov qayta o‘tkaziladi","Model o‘chiriladi va ish to‘xtatiladi"],"a":2,"e":"Tuzatishdan keyin qayta sinash shart."},{"q":"AVERAGE funksiyasi nimani hisoblaydi?","o":["Eng kichikni","Yig‘indini","Ko‘paytmani","O‘rta arifmetikni"],"a":3,"e":"O‘rtacha."},{"q":"Aniq qiymatlarni ko‘rsatish uchun qaysi shakl qulay?","o":["Animatsiya","Shaffof rasm","Jadval","Audio yozuv"],"a":2,"e":"Jadvalda har bir qiymat aniq yoziladi."},{"q":"Formula qaysi belgidan boshlanadi?","o":["@","?","#","="],"a":3,"e":"Tenglik."},{"q":"Vaziyat: sahifa matnining rangini o‘zgartirmoqchisiz. Qaysi qatlam kerak?","o":["Ma’lumotlar bazasi","Klaviatura","CSS","HTML sarlavhasi"],"a":2,"e":"Rang ko‘rinishga tegishli, ya’ni CSS."},{"q":"Ortiqcha bezaklar nimaga olib keladi?","o":["Ma’lumotlar tezroq tushunilishiga","Ma’lumotlar to‘g‘ri bo‘lishiga","Asosiy ma’lumot ko‘rinmay qolishiga","Fayl himoyalanishiga"],"a":2,"e":"Bezak e’tiborni chalg‘itadi."},{"q":"Qismlarning butundagi ulushini ko‘rsatish uchun qaysi diagramma qulay?","o":["Doiraviy diagramma","Sarlavha","Jadval katagi","Formula"],"a":0,"e":"Doiraviy diagramma ulushlarni ko‘rsatadi."},{"q":"Veb sahifani yozish uchun nima yetarli?","o":["Faqat mikrofon","Oddiy matn muharriri va brauzer","Faqat skaner","Faqat printer"],"a":1,"e":"Matn muharriri va brauzer bilan sahifa yaratish mumkin."},{"q":"Vaziyat: =B2*$C$1 formulasi pastga nusxalandi. Qaysi qism o‘zgarmaydi?","o":["B2","$C$1","Ikkalasi o‘zgarmaydi","Ikkalasi o‘zgaradi"],"a":1,"e":"Absolyut qism."},{"q":"Vaziyat: saytni boshqa papkaga ko‘chirdingiz va havolalar buzilmasligi kerak. Qaysi manzil qulay?","o":["Faqat tasodifiy matn","Hech qaysi","Nisbiy manzil","Boshqa kompyuter yo‘li"],"a":2,"e":"Nisbiy manzillar ko‘chirishda ishlayveradi."},{"q":"Ma’lumotlarni boshqarishga nima kiradi?","o":["Faqat rasm chizish","Saqlash, yangilash, himoyalash va zaxiralash","Faqat ekran yorqinligini sozlash","Faqat chop etish"],"a":1,"e":"Boshqarish ma’lumotlar bilan butun ish jarayonini qamraydi."},{"q":"Vaziyat: formula natijasi kalkulyatordagi natijadan farq qilyapti. Nima qilasiz?","o":["Jadvalni o‘chirib tashlayman","Natijani qo‘lda yozib qo‘yaman","Kalkulyator natijasini noto‘g‘ri deb hisoblayman","Formulani tekshirib, xatoni topaman"],"a":3,"e":"Farq xato borligini bildiradi, uni topib tuzatish kerak."}]},{"t":"68-dars. Takrorlash","lesson":"<p><b>Takrorlash</b> quyidagi darslarni qamrab oladi:</p><ul><li>Kompyuter qurilmalari va dasturiy ta‘minot. Kompyuter tizimining asosiy komponentlari</li><li>Operatsion tizimlar</li><li>Kompyuter turlari</li><li>Yangi texnologiyalarning ta‘siri</li><li>Kiritish qurilmalari va ularning qo‘llanishi</li><li>Ma‘lumotni bevosita kiritishda foydalaniladigan qurilmalar.</li><li>Chiqarish qurilmalari va ulardan foydalanish</li><li>Xotira qurilmalari va ma‘lumot almashish vositalari</li><li>Turli xotira qurilmalarining afzallik va kamchiliklari</li><li>Xotira hajmiga bog‘liq masalalarni yechish</li><li>Kompyuter tarmoqlari qurilmalari</li><li>Brauzerdan foydalanish. Kompyuter tarmoqlari dasturiy jihati.</li><li>Tarmoq muammolari va kommunikatsiya</li><li>Axborot texnologiyasining bandlikka ta‘siri</li><li>Axborot texnologiyasi (AT) ning tashkilotlar ish uslubiga ta‘siri. Mikroprotsessorli uy qurilmalari</li><li>Axborot texnologiyasi (AT) jihozlaridan uzoq muddat foydalanishning sog‘liqqa ta‘siri</li><li>Kommunikatsiya dasturlari qamrovi. Ma‘lumotlarni boshqarish dasturlari</li><li>O‘lchov dasturlari. Boshqaruv dasturlaridagi mikroprotsessorlar</li><li>Modellashtirish dasturlari. Boshqaruv, ta‘lim, sog‘liqni saqlash, savdo va autentifikatsiyada kompyuter tizimlari</li><li>Tahlil va loyihalash</li><li>Ishlab chiqish, sinash va joriy qilish</li><li>Hujjatlashtirish, baholash va texnik xizmat ko‘rsatish</li><li>Xavfsizlik muammolari. Elektron xavfsizlik. Ma‘lumotlar xavfsizligi</li><li>Axborot himoyasi protokoli. Antiviruslar va fayervol</li><li>Auditoriyani huquqiy, ma‘naviy, axloqiy va madaniy jihatdan baho berish</li><li>Mualliflik huquqi va uning turlari. Mualliflik huquqi himoyasi</li><li>AKT foydalanuvchisi bilan elektron xat orqali muloqot qilish. Spam tushunchasi</li><li>Internetdan samarali foydalanish. Internetdan topilgan axborotning ishonchliligini baholash</li><li>Fayl kengaytmasi va ularni samarali boshqarish</li><li>Saqlash yoki uzatish uchun fayl hajmini kamaytirish</li><li>Tasvirlarni joylashtirish va tahrirlash uchun dastur uskunalaridan foydalanish</li><li>Tasvirni aniq joylashtirish. Tasvirning tomonlar nisbatini o‘zgartirish</li><li>Tasvirni qirqish va aylantirish</li><li>Tasvir rangi, yorqinligi, kontrasti va aniqligi boshqarish</li><li>Sahifa maketi. Maqsad va auditoriyaga mos hujjat yaratish uchun dasturiy uskunalardan foydalanish</li><li>Hujjatga obyektlarni joylashtirish</li><li>Header va Footer maydonlarini yaratish</li><li>Korporativ brend va unga xos stil. Korporativ brendga xos stilga muvofiq hujjat tayyorlash</li><li>Sahifa/slayd izchilligini ta‘minlash</li><li>Yangi stil yaratish</li><li>Xatolarni tekshirish uchun dasturlardan foydalanish</li><li>Xatolarni tekshirish usullari</li><li>Verifikatsiya va validatsiya tuhsunchalari</li><li>Grafik yoki diagramma yaratish. Diagramma turlari</li><li>Tayyorlangan diagrammani boshqarish va o‘zgartirish</li><li>Matn va sahifa maketini formatlash</li><li>Dastur uskunalari yordamida jadvallarni tahrirlash</li><li>Ma‘lumot manbasi bilan hujjatni birlashtirib, pochta orqali yuborish</li><li>Ma‘lumotlar bazasi tuzilmasini yaratish. Ma‘lumotlarni boshqarish va taqdim etish</li><li>Ob‘yektlarni to‘g‘ri joylash. Taqdimot slaydlarini yaratish uchun mos dastur imkoniyatlaridan foydalanish</li><li>Taqdimotga elektron jadvaldan diagrammalarni import qilish</li><li>Ma‘lumotlar modelini yaratish. Nisbiy va absolyut murojaat.</li><li>Formula va funksiyalar hamda ulardan foydalanish</li><li>Ma‘lumotlar modelini sinovdan o‘tkazish. Ma‘lumotlarni boshqarish</li><li>Ma‘lumotlarni taqdim etish</li><li>Veb dasturlashning uch qatlami. Veb sahifa yaratish</li><li>Linklar, bookmarklar va ankor. Absolyut va nisbiy fayl manzillari</li><li>Stil jadvallaridan foydalanish. Veb saytni sinash va publikatsiya qilish</li></ul><p>Test <b>10 ta aralash savoldan</b> iborat. Qiynalgan mavzuingizning darsini qayta o‘qib chiqing.</p>","quiz":[{"q":"Ta’limda kompyuter tizimiga misol qaysi?","o":["Onlayn kurs","Doska bo‘ri","Kitob javoni","Qalam"],"a":0,"e":"Masofaviy o‘qitish."},{"q":"To‘g‘ri mulohazani toping.","o":["Hujjatda ko‘p shrift ishlatish uning o‘qilishini qiyinlashtiradi","Izchillik faqat taqdimotlarga tegishli","Shrift qancha ko‘p bo‘lsa, shuncha yaxshi","Stil faqat jadvalda ishlaydi"],"a":0,"e":"Haddan ortiq shrift chalkashlik keltiradi."},{"q":"Zaxira nusxa olishning maqsadi nima?","o":["Ma’lumot yo‘qolsa tiklash","Faylni o‘chirish","Internetni tezlashtirish","Ekranni tozalash"],"a":0,"e":"Nusxadan tiklash mumkin."},{"q":"Nusxali (qatlamli) hujjatlarni bir yo‘la chop etishga qaysi printer mos?","o":["Lazerli printer","Proyektor","Matritsali printer","Purkagichli printer"],"a":2,"e":"Matritsali printer ignalar bilan bosib, nusxa hosil qiladi."},{"q":"Aniq qiymatlarni ko‘rsatish uchun qaysi shakl qulay?","o":["Animatsiya","Shaffof rasm","Jadval","Audio yozuv"],"a":2,"e":"Jadvalda har bir qiymat aniq yoziladi."},{"q":"Hujjatlashtirishning maqsadi nima?","o":["Dasturni o‘chirish","Ekran bo‘yash","Xato yaratish","Tizimni tushuntiruvchi yozma materiallar tayyorlash"],"a":3,"e":"Qo‘llanma foydalanuvchiga yordam beradi."},{"q":"Joylashtirilgan (kiritilgan) diagramma qayerda saqlanadi?","o":["Faqat jadval faylida","Pochtada","Printerda","Taqdimot ichida"],"a":3,"e":"Taqdimotda."},{"q":"To‘g‘ri mulohazani toping.","o":["SSD ichida aylanuvchi disk bor","Fleshka internetsiz ishlamaydi","HDD zarbaga eng chidamli qurilma","Fleshkani yo‘qotib qo‘yish ma’lumot yo‘qolishiga olib kelishi mumkin"],"a":3,"e":"Ko‘chma qurilmani yo‘qotish xavfi bor."},{"q":"Xodim xat tayyorlayapti. Eng to‘g‘ri harakat qaysi?","o":["Logotipsiz yuborish","Kompaniyaning xat blankidan foydalanish","O‘zi yoqtirgan shrift va rangni tanlash","Boshqa kompaniya logotipini qo‘yish"],"a":1,"e":"Brend blankidan foydalanish uslubni saqlaydi."},{"q":"To‘g‘ri mulohazani tanlang.","o":["Sinov modelni yaratishdan oldin o‘tkaziladi","Chegaraviy qiymatlar bilan ham sinash kerak","Faqat bitta qiymat bilan sinash yetarli","Xato topilsa, uni hisobga olmaslik kerak"],"a":1,"e":"Model turli qiymatlarda, jumladan chegaraviy qiymatlarda ham sinaladi."}]}];
